// Atlas of Visual Effects · official prompts, licensed references, and labeled offline substitutes.
const atlasPreviewData = {
  "1-bit-dithering": {"prompt": "Apply a 1-bit dithering effect using only pure black and pure white pixels. Translate shadows and gradients into tightly distributed error-diffusion dot patterns, with denser black clusters in darker regions, crisp pixel-stepped edges, and no actual gray, color, blur, or transparency. Keep the original subject and composition.", "credit": "Painting: Tor-Arne Moen; photo: Tor-Arne Moen (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Tor-Arne_Moen_Natural_selection.jpg", "local": "1-bit-dithering.webp", "title": "1-Bit Dithering, applied to “Tor-Arne Moen Natural selection”", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "1-bit-threshold": {"prompt": "Apply a 1-Bit Threshold effect, forcing every pixel to either pure black or pure white using one consistent brightness cutoff. Create solid shadow masses, stark white highlights, abrupt hard contours, and simplified internal detail, with no gray, dithering, grain, or soft transitions. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "1-bit-threshold.webp", "title": "1-Bit Threshold", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "2-5d-parallax": {"prompt": "Apply a 2.5D Parallax effect as a single layered-depth still, separating foreground, subject, and background into subtly offset planes. Suggest shallow spatial movement through tiny edge reveals, gently differentiated focus, and seamlessly filled background gaps, without obvious collage seams. Keep the original subject and composition.", "credit": "Shohei Ohtaki / Motion Prompt · 本地取帧", "source": "https://showheyohtaki.github.io/motion-prompt/#016", "license": "MIT", "licenseUrl": "https://github.com/showheyohtaki/motion-prompt/blob/main/LICENSE", "title": "2.5D Parallax · 动效分镜", "previewKind": "开源同类示例", "local": "2-5d-parallax.webp"},
  "360-panorama": {"prompt": "Apply a 360° Panorama effect as a flattened equirectangular-style projection, with a level central horizon, widened peripheral space, and progressively stretched shapes near the top and bottom poles. Suggest seamless panoramic stitching and consistent lighting, keeping the main subject minimally distorted near its original position. Keep the original subject and composition.", "credit": "Capricorn4049 · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Capanna_Regina_Margherita_Spherical_Panorama.jpg", "local": "360-panorama.webp", "title": "360° Panorama", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "3d-gaussian-splatting": {"prompt": "Apply a 3D Gaussian Splatting look with a photorealistic central subject surrounded by softly overlapping translucent splats in uncertain background areas. Preserve convincing illumination and surface color while adding sparse floating flecks, cloudy depth transitions, and gently dissolving peripheral edges. Keep the original subject and composition.", "credit": "Óscar Mirás", "source": "https://commons.wikimedia.org/wiki/File:Polycam_gaussian_splatting_exemplo.png", "local": "3d-gaussian-splatting.webp", "title": "Polycam gaussian splatting exemplo", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "active-contour-snake": {"prompt": "Apply an Active Contour Snake effect, overlaying a single smooth, closed neon-green curve around the main visible subject's estimated boundary. Include small, evenly spaced control points along the curve, gently rounding fine protrusions while keeping the underlying photograph visible and otherwise unchanged. Keep the original subject and composition.", "credit": "Image: Varshesh Joshi varshesh · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Architecture_in_Agra_(Unsplash).jpg", "local": "active-contour-snake.webp", "title": "Active Contour Snake", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "adaptive-threshold": {"prompt": "Apply Adaptive Thresholding, converting the photograph into pure black and white using locally adjusted brightness divisions. Retain small details across both shaded and brightly lit areas, with crisp irregular boundaries, stippled textures, and no gray tones. Avoid broad lighting gradients overwhelming detail. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "adaptive-threshold.webp", "title": "Adaptive Thresholding", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "aerial-photography": {"prompt": "Apply an early Aerial Photography aesthetic, emphasizing any existing overhead geometry, flattened spatial layers, distant atmospheric haze, and finely resolved surface patterns. Use muted gray-brown plate tones, restrained contrast, slight peripheral softness, and sparse wet-plate blemishes without inventing buildings or changing the viewpoint. Keep the original subject and composition.", "credit": "Black, James Wallace, 1825-1896 · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Boston,_as_the_Eagle_and_the_Wild_Goose_See_It_-_DPLA_-_f038de20f279486a5dc8a64206171059.jpg", "local": "aerial-photography.webp", "title": "Aerial Photography", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "affine-texture-warping": {"prompt": "Apply an Affine Texture Warping effect to receding surfaces, stretching and skewing their textures unevenly across visible triangular sections. Add mismatched texture scale, kinked pattern lines, coarse texels, and slight whole-pixel vertex offsets to suggest unstable early polygon rendering without global motion blur. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/affine-texture-warping", "title": "Affine Texture Warping · 本库原创图解", "previewKind": "原创技法示意", "local": "affine-texture-warping.webp"},
  "airbrush-illustration": {"prompt": "Transform this image into an Airbrush Illustration with seamless sprayed gradients, idealized rounded forms, polished highlights, and velvety shadow transitions. Combine soft pigment clouds with crisp masked contours, tiny overspray speckles, and smooth glossy surfaces without visible brushstrokes. Retain recognizable structural details. Keep the original subject and composition.", "credit": "Fabio pastori · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:F1_fireman_helmet.jpg", "local": "airbrush-illustration.webp", "title": "Airbrush Illustration", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "albums-print": {"prompt": "Transform this image into an Albumen Print with finely resolved details, warm sepia and honey-brown tones, creamy paper highlights, and a smooth, subtly glossy protein-coated surface. Add delicate fading toward the margins and minimal visible grain rather than coarse texture. Keep the original subject and composition.", "credit": "Unknown authorUnknown author / Public domain; Wikimedia Commons", "source": "https://www.getty.edu/conservation/publications_resources/pdf_publications/pdf/atlas_albumen.pdf", "local": "albums-print.webp", "title": "Albumen Print", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "aliasing-jaggies": {"prompt": "Apply Aliasing Jaggies, giving the photograph a visibly coarse pixel grid with hard staircase contours and blocky diagonals. Break thin lines into uneven segments and introduce false repeating patterns in dense textures. Use crisp nearest-neighbor edges without smoothing or added grain. Keep the original subject and composition.", "credit": "Image: FORREST CAVALE forrestcavale · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Road_dust_under_setting_sun_(Unsplash).jpg", "local": "aliasing-jaggies.webp", "title": "Aliasing Jaggies", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "alpha-matte": {"prompt": "Transform this image into an Alpha Matte visualization with opaque foreground areas in white, fully transparent background areas in black, and intermediate opacity in gray. Preserve delicate hair, fine fibers, and translucent edge details through soft, precise transitions rather than uniformly blurred outlines. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "alpha-matte.webp", "title": "Alpha Matte", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "ambient-occlusion": {"prompt": "Apply an ambient occlusion effect with soft, localized darkening in creases, recesses, narrow gaps, and points where surfaces touch. Build subtle neutral-toned contact shadows that fade smoothly outward, strengthening volume and grounding objects without black outlines, altered materials, or new directional lighting. Keep the original subject and composition.", "credit": "Vlad3D at English Wikipedia", "source": "https://commons.wikimedia.org/wiki/File:Screen_space_ambient_occlusion.jpg", "local": "ambient-occlusion.webp", "title": "Screen space ambient occlusion", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "ambrotype": {"prompt": "Transform this image into an Ambrotype, rendering the photograph as a delicate silver-gray positive on glass backed by deep black. Use subdued highlights, dark translucent shadows, fine detail, slight surface reflections, and uneven collodion edges with tiny scratches. Keep the original subject and composition.", "credit": "The Metropolitan Museum of Art, 2015.400.104 / Public Domain", "source": "https://www.loc.gov/exhibits/civil-war-photographs/the-photographic-process.html", "local": "ambrotype.webp", "title": "Ambrotype", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "anaglyph-stereo": {"prompt": "Apply an Anaglyph Stereo effect using overlapping red and cyan image channels with small horizontal offsets. Vary the separation by apparent depth, producing recognizable doubled contours around foreground forms while keeping distant regions more closely aligned. Retain clear underlying detail and restrained neutral midtones. Keep the original subject and composition.", "credit": "Richard Bartz, Munich aka Makro Freak", "source": "https://commons.wikimedia.org/wiki/File:Auchenorrhyncha_Anaglyph.jpg", "local": "anaglyph-stereo.webp", "title": "Auchenorrhyncha Anaglyph", "license": "CC BY-SA 2.5", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.5/"},
  "anamorphic-lens-flare": {"prompt": "Apply an anamorphic lens flare effect with thin horizontal blue-cyan light streaks extending from existing bright sources, faint colored reflection ghosts, and localized veiling glare. Add gentle highlight bloom and reduced contrast near intense lights while retaining crisp detail elsewhere. Keep the original subject and composition.", "credit": "1bumer (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Bydgoszcz,_Przysta%C5%84_Bydgoszcz,_okna.jpg", "local": "anamorphic-lens-flare.webp", "title": "Anamorphic Lens Flare, applied to “Bydgoszcz, Przystań Bydgoszcz, okna”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "anamorphic-widescreen": {"prompt": "Apply an Anamorphic Widescreen lens effect with horizontal blue-white light streaks, vertically elongated oval background bokeh, gentle edge softness, and subtle barrel distortion. Suggest expansive cinematic space through peripheral lens rendering rather than cropping, while retaining natural central proportions and restrained film grain. Keep the original subject and composition.", "credit": "Kdmitry", "source": "https://commons.wikimedia.org/wiki/File:Ruralscope_Anamorphic_Projection_Lense.jpg", "local": "anamorphic-widescreen.webp", "title": "Ruralscope Anamorphic Projection Lense", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "animated-gif": {"prompt": "Apply an Animated GIF aesthetic as a single representative frame, using a limited palette of no more than 256 colors, hard pixel edges, flat color areas, and speckled dithering. Suggest stepped looping movement with a few tightly spaced motion echoes around active details. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/animated-gif", "title": "Animated GIF · 本库原创图解", "previewKind": "原创技法示意", "local": "animated-gif.webp"},
  "animatronics": {"prompt": "Apply an animatronics practical-effects treatment, rendering the subject as a tangible articulated replica with molded silicone skin, painted foam-latex textures, discreet panel seams, and joint divisions. Add glossy inset details, subtle mechanical fittings, and convincing contact shadows under cinematic set lighting. Keep the original subject and composition.", "credit": "Michael Barera · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Texas_Auto_Show_September_2019_09_(Hank_the_Robot).jpg", "local": "animatronics.webp", "title": "Animatronics", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "anisotropic-diffusion": {"prompt": "Apply Anisotropic Diffusion, smoothing random grain and tiny color fluctuations within surfaces while stopping cleanly at strong contrast boundaries. Give flat regions a softly painted finish, preserve continuous tonal shading, and keep important outlines crisp without sharpening halos or exaggerated brush marks. Keep the original subject and composition.", "credit": "Image: Boris Stefanik bstefanik · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Doorman_on_Leadenhall_Street_(Unsplash).jpg", "local": "anisotropic-diffusion.webp", "title": "Anisotropic Diffusion", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "ansi-16-color-terminal": {"prompt": "Apply an ANSI 16-Color Terminal effect, reducing the image to coarse rectangular character-cell blocks in a restricted sixteen-color palette. Use black, gray, saturated primary and secondary hues, and bright variants, with hard stepped edges and flat shading; omit interface decorations. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "ansi-16-color-terminal.webp", "title": "ANSI 16-Color Terminal", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "anthotype": {"prompt": "Transform this image into an Anthotype using a single pale botanical purple pigment on absorbent paper. Create sun-bleached highlights, low contrast, soft edges, uneven hand-coated staining, and faint plant-dye mottling, allowing the image to appear fragile and partially faded without deep blacks. Keep the original subject and composition.", "credit": "Hutschi · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Ahornblatt_(Anthotypie).jpg", "local": "anthotype.webp", "title": "Anthotype", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "ar-face-filters": {"prompt": "Apply an AR Face Filters effect to visible faces, adding softly shaded animal ears, a fitted translucent facial mask, and subtly enlarged expressive eyes. Align overlays precisely with facial landmarks, head angle, and perspective, using consistent highlights and believable occlusion around hair. Keep the original subject and composition.", "credit": "Eva van Kempen", "source": "https://commons.wikimedia.org/wiki/File:Eva_van_kempen-1583406753.jpg", "local": "ar-face-filters.webp", "title": "Eva van kempen-1583406753", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "ascii-art-render": {"prompt": "Transform this image into an ASCII Art Render built entirely from evenly spaced monospace characters on a white background. Use dense dark glyphs for shadows, sparse punctuation for midtones, and blank spaces for highlights. Maintain a strict character grid without photographic texture. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "ascii-art-render.webp", "title": "ASCII Art Render", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "ascii-art": {"prompt": "Transform this image into ASCII Art, rebuilding its visible forms entirely from evenly spaced monospaced letters, numbers, and punctuation. Use dense character clusters for shadows and sparse marks for highlights, with black glyphs on an ivory background and clearly readable stepped contours. Keep the original subject and composition.", "credit": "Numberguy6", "source": "https://commons.wikimedia.org/wiki/File:Ascii_art_alphabet.png", "local": "ascii-art.webp", "title": "Ascii art alphabet", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "astrophotography": {"prompt": "Apply an Astrophotography treatment with deep charcoal blacks, cool silvery highlights, fine photographic grain, and luminous points concentrated in existing bright details. Suggest long-exposure celestial light through restrained halos and faint cloudlike tonal structures, preserving clear subject contours rather than replacing the scene. Keep the original subject and composition.", "credit": "Giles Laurent · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:036_Milky_Way_during_Perseids_seen_from_Oeschinensee_with_water_reflections_Photo_by_Giles_Laurent.jpg", "local": "astrophotography.webp", "title": "Astrophotography", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "atkinson-dither": {"prompt": "Apply an Atkinson Dither effect using pure black and white pixels, with compact dot clusters, open white highlights, and bold dark shadow areas. Replace smooth shading with airy, high-contrast pixel patterns that retain less midtone detail, avoiding gray pixels and regular checkerboard screens. Keep the original subject and composition.", "credit": "Image: Samantha Scholl sauriel · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Horse_herd_in_Wales_(Unsplash).jpg", "local": "atkinson-dither.webp", "title": "Atkinson Dither", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "autochrome-lumiere": {"prompt": "Transform this image into an Autochrome photograph with softly luminous colors, muted greens, warm coral reds, and delicate violet shadows. Add a fine mosaic of colored starch-like granules, gentle optical softness, restrained contrast, and the translucent glow of a backlit glass positive. Keep the original subject and composition.", "credit": "Clifton R. Adams", "source": "https://commons.wikimedia.org/wiki/File:Mauretania_in_drydock_1928_autochrome_process_starboard_side.jpg", "local": "autochrome-lumiere.webp", "title": "Mauretania in drydock 1928 autochrome process starboard side", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "autostereogram": {"prompt": "Transform this image into an Autostereogram covered edge to edge with dense, horizontally repeating multicolored speckles. Encode the subject as hidden depth through small local shifts in repeat spacing, with nearer forms receiving greater disparity and no visible outlines or conventional shading. Keep the original subject and composition.", "credit": "Nevit Dilmen (talk) · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Autostereogram_Leyla_on_water.jpg", "local": "autostereogram.webp", "title": "Autostereogram", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "backlit-animation": {"prompt": "Apply an optical backlit animation effect, simplifying surfaces into dark cel-like shapes edged by luminous cyan, electric blue, and warm orange contours. Give each illuminated line a sharp bright core, soft colored halo, slight optical bloom, and fine photographic grain. Keep the original subject and composition.", "credit": "Digital Effects Inc.", "source": "https://commons.wikimedia.org/wiki/File:Digital_Effects,_%22Times_Square,%22_1980._DEI19800401_DEI001.JPG", "local": "backlit-animation.webp", "title": "Digital Effects, \"Times Square,\" 1980. DEI19800401 DEI001", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "barrel-lens-warp": {"prompt": "Apply Barrel Lens Warp, introducing moderate outward bowing of straight lines toward the frame edges. Gently expand central forms and compress peripheral spacing, producing smooth convex lens geometry rather than waves or a spiral. Retain original colors, sharpness, and natural lighting. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "barrel-lens-warp.webp", "title": "Barrel Lens Warp", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "bayer-cfa-mosaic": {"prompt": "Apply Bayer CFA Mosaic, converting the photograph into a fine, visibly resolved checkerboard of single-channel samples. Repeat two-by-two tiles containing two green sites, one red site, and one blue site, each varying in brightness with the source image. Avoid blended pixel colors. Keep the original subject and composition.", "credit": "Image: adrian aows · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:White_Multnomah_Falls_(Unsplash).jpg", "local": "bayer-cfa-mosaic.webp", "title": "Bayer CFA Mosaic", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "bayer-ordered-dither": {"prompt": "Apply a Bayer Ordered Dither effect using only black and white pixels. Replace smooth gradients with visibly repeating square threshold patterns, producing regular checkerboards and stepped tonal textures. Keep pixel edges hard, pattern spacing consistent, and outlines recognizable without blur or random grain. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "bayer-ordered-dither.webp", "title": "Bayer Ordered Dither", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "beauty-filter": {"prompt": "Apply a Beauty Filter effect with selectively smoothed skin, reduced pores, softened blemishes, brightened under-eye areas, and a subtle peach glow. Preserve crisp eyelashes, eyebrows, and lip edges against the polished complexion, avoiding excessive facial reshaping or plastic texture. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/beauty-filter", "title": "Beauty Filter · 本库原创图解", "previewKind": "原创技法示意", "local": "beauty-filter.webp"},
  "ben-day-dots": {"prompt": "Apply a Ben-Day Dots effect with evenly spaced, consistently sized dots filling selected tonal regions, bold black contours, and flat cyan, magenta, yellow, and red areas. Add overlapping dot colors, slight print misregistration, and lightly textured off-white paper without smooth gradients. Keep the original subject and composition.", "credit": "Wilfredor (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Ana_rosa_metro_station,_S%C3%A3o_Paulo,_Brazil.jpg", "local": "ben-day-dots.webp", "title": "Ben-Day Dots, applied to “Ana rosa metro station, São Paulo, Brazil”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "bevel-and-chrome-look": {"prompt": "Apply a bevel and chrome effect, giving prominent forms polished silver surfaces, chamfered edges, crisp white highlights, and alternating near-black and bright reflection bands. Add subtle cool environmental reflections and tight contact shadows to suggest solid extruded metal rather than flat gray paint. Keep the original subject and composition.", "credit": "AdamChajjadi2008", "source": "https://commons.wikimedia.org/wiki/File:Adam_Chajjadi_Productions_New_Concept_Logo_(Metallic_Model_Era).png", "local": "bevel-and-chrome-look.webp", "title": "Adam Chajjadi Productions New Concept Logo (Metallic Model Era)", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "bilateral-filter": {"prompt": "Apply Bilateral Filter to smooth noise and fine texture inside similar-colored regions while maintaining clearly defined boundaries between contrasting areas. Create clean, gently flattened color fields with intact silhouettes and natural lighting gradients. Avoid edge halos, color bleeding, and uniform defocus. Preserve the original subject and composition.", "credit": "Basotxerri (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Lech_-_B%C3%BCrstegg_-_Sitzbank_01.jpg", "local": "bilateral-filter.webp", "title": "Bilateral Filter, applied to “Lech - Bürstegg - Sitzbank 01”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "binary-object-mask": {"prompt": "Transform this image into a Binary Object Mask, rendering the selected main subject as solid pure white and all background areas as solid pure black. Use hard, clean silhouette boundaries, retain meaningful internal openings, and remove color, shading, texture, and gray transitions. Keep the original subject and composition.", "credit": "Bijay Chaurasia (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Old_man_reading_newspaper_early_in_the_morning_at_Basantapur-IMG_6800.jpg", "local": "binary-object-mask.webp", "title": "Binary Object Mask, applied to “Old man reading newspaper early in the morning at Basantapur-IMG 6800”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "bit-plane-slicing": {"prompt": "Apply Bit-Plane Slicing, rendering the photograph as overlapping binary layers of stark black and white. Combine broad threshold-like silhouettes with finer fragmented contours and granular static patterns, suggesting separate high-order structural bits and low-order noise. Keep recognizable forms beneath the digital abstraction. Keep the original subject and composition.", "credit": "Image: Stefan Steinbauer usinglight · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Gazing_up_in_the_forest_(Unsplash).jpg", "local": "bit-plane-slicing.webp", "title": "Bit-Plane Slicing", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "black-and-white-infrared": {"prompt": "Transform this image into Black-and-White Infrared photography with snowy white foliage wherever present, deeply darkened blue skies, and unusually pale skin. Use luminous material contrasts, rich black water, fine monochrome grain, and gentle highlight halation for an uncanny sunlit appearance. Keep the original subject and composition.", "credit": "Reinhard Brunsch / CC BY-SA 3.0; Wikimedia Commons", "source": "https://www.ilfordphoto.com/using-ilford-sfx-part-1/", "local": "black-and-white-infrared.webp", "title": "Black-and-White Infrared", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "bleach-bypass": {"prompt": "Apply a Bleach Bypass effect with strongly reduced color saturation, dense charcoal shadows, hard tonal contrast, and bright metallic-looking highlights. Overlay pronounced silver-like photographic grain while retaining tactile surface detail and a faint residue of the original hues. Avoid a completely monochrome result. Keep the original subject and composition.", "credit": "Soerfm / CC BY-SA 3.0; Wikimedia Commons", "source": "https://www.kodak.com/en/motion/page/processing-techniques/", "local": "bleach-bypass.webp", "title": "Bleach Bypass", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "blob-detection": {"prompt": "Apply Blob Detection with thin cyan circles centered on compact bright or dark patches that contrast with their surroundings. Vary circle diameters to indicate each blob's estimated extent, including small texture spots and larger rounded regions. Preserve natural photographic detail beneath the overlay. Keep the original subject and composition.", "credit": "Image: Isaak Dury isaakdury · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:San_Francisco_Skyline_and_Alcatraz_Island_seen_from_Sausalito_-_Isaak_Dury_2013_(Unsplash).jpg", "local": "blob-detection.webp", "title": "Blob Detection", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "block-glitch": {"prompt": "Apply a Block Glitch effect by displacing selected rectangular image patches horizontally and vertically. Create hard-edged seams, duplicated fragments, mismatched local textures, and occasional narrow pixel strips. Leave enough surrounding areas intact to make the fragmented image clearly recognizable; keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "block-glitch.webp", "title": "Block Glitch", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "bloom": {"prompt": "Apply Bloom to make the brightest highlights radiate soft, luminous halos into neighboring areas. Spread warm whites and existing highlight colors gently beyond their edges, with smooth falloff and additive brightness. Keep shadows comparatively crisp and avoid uniform fog. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "bloom.webp", "title": "Bloom", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "blue-noise-dither": {"prompt": "Apply a Blue-Noise Dither effect, representing tones with tiny pure black and white pixels distributed in an evenly dispersed, nonrepeating pattern. Make shading read smoothly at a distance while avoiding clumps, directional trails, and visible grids; retain sharp contours without blur. Keep the original subject and composition.", "credit": "Image: Julian Hanslmaier j_h · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Farmer%27s_Market_Produce_(Unsplash).jpg", "local": "blue-noise-dither.webp", "title": "Blue-Noise Dither", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "bokeh": {"prompt": "Apply a Bokeh effect with a sharply focused subject and strongly defocused background, turning distant light sources into soft luminous discs with gentle rims and occasional aperture-shaped highlights. Preserve natural foreground texture, realistic depth transitions, and warm or cool light colors without uniform blur. Keep the original subject and composition.", "credit": "Aprisonsan", "source": "https://commons.wikimedia.org/wiki/File:Coucang.jpg", "local": "bokeh.webp", "title": "Coucang", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "bounding-box-detection": {"prompt": "Apply a Bounding Box Detection effect, overlaying thin, saturated rectangular frames tightly around visible objects. Add small technical labels with plausible object categories and illustrative confidence percentages, using compact lettering and colored label tabs. Leave the underlying photograph clear, without replacing objects or scenery. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "bounding-box-detection.webp", "title": "Bounding Box Detection", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "box-blur": {"prompt": "Apply a Box Blur effect using uniform square-neighborhood softening across the photograph. Spread nearby colors evenly, suppress fine texture and grain, and soften high-contrast boundaries with faint square-edged halos rather than creamy circular bokeh. Retain broad tonal masses and the existing color palette. Keep the original subject and composition.", "credit": "Pumpkins pumpkin (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Fruit_collection_(Unsplash).jpg", "local": "box-blur.webp", "title": "Box Blur, applied to “Fruit collection (Unsplash)”", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "brick-mosaic": {"prompt": "Transform this image into a Brick Mosaic of colored rectangular tiles arranged in horizontal rows, offsetting every alternate row. Fill each brick with its corresponding averaged photo color and separate tiles with narrow, pale mortar gaps. Use crisp edges and restrained surface texture; keep the original subject and composition.", "credit": "Image: Igor Ovsyannykov igorovsyannykov · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Factory_Worker_Making_Clothes_(Unsplash).jpg", "local": "brick-mosaic.webp", "title": "Brick Mosaic", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "bromoil-print": {"prompt": "Transform this image into a Bromoil Print with velvety brown-black ink, warm paper highlights, and selectively softened contours. Add stippled pigment deposits, irregular brush and stipple textures, subdued photographic detail, and broad, painterly tonal masses on matte gelatin-coated paper. Keep the original subject and composition.", "credit": "Hiart", "source": "https://commons.wikimedia.org/wiki/File:Untitled_(Walther_K%C3%BChn)_by_Heinrich_K%C3%BChn,_c._1900,_bromoil_transfer_print,_Museum_of_Modern_Art.jpg", "local": "bromoil-print.webp", "title": "Untitled (Walther Kühn) by Heinrich Kühn, c. 1900, bromoil transfer print, Museum of Modern Art", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "brulage": {"prompt": "Apply Brûlage as a heat-damaged photographic print, with flowing emulsion distortions, blistered bubbles, rippled contours, and scorched tonal patches. Use silvery blacks, smoky grays, pale translucent voids, and irregular melted edges. Concentrate severe damage around peripheral details while retaining recognizable features. Keep the original subject and composition.", "credit": "Jindřich Heisler (1914-1953) · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Frontispice_pour_La_Philosophie_dans_la_boudoire_(1944).jpg", "local": "brulage.webp", "title": "Brûlage", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "bullet-time": {"prompt": "Apply a Bullet Time effect that suggests an orbiting camera around nearly frozen action. Keep the subject exceptionally sharp, suspend tiny airborne particles, and add restrained curved motion streaks only to distant surroundings, emphasizing depth separation and cinematic directional lighting. Keep the original subject and composition.", "credit": "Nathan Boor of Aimed Research", "source": "https://commons.wikimedia.org/wiki/File:Bullet_Time,_Time_Slicing.JPG", "local": "bullet-time.webp", "title": "Bullet Time, Time Slicing", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/"},
  "bump-mapping": {"prompt": "Apply a Bump Mapping effect, giving existing surfaces finely pebbled, wrinkled, or engraved relief through directional highlights and tiny shaded depressions. Preserve smooth outer silhouettes, emphasizing apparent texture without protruding geometry; use restrained material colors and raking light to reveal the simulated roughness. Keep the original subject and composition.", "credit": "GDallimore", "source": "https://commons.wikimedia.org/wiki/File:Bump_map_vs_isosurface2.png", "local": "bump-mapping.webp", "title": "Bump map vs isosurface2", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "busby-berkeley-top-shot": {"prompt": "Apply a Busby Berkeley Top Shot-inspired treatment with overhead-style decorative formations, concentric rings, radiating spokes, and flowerlike repetitions of small dancer silhouettes. Use flattened depth, crisp theatrical lighting, monochrome silver tones, and precise radial symmetry around the existing focal point. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/busby-berkeley-top-shot", "title": "Busby Berkeley Top Shot · 本库原创图解", "previewKind": "原创技法示意", "local": "busby-berkeley-top-shot.webp"},
  "calotype": {"prompt": "Transform this image into a Calotype positive print with warm brown monochrome tones, soft contours, and broad, quiet tonal areas. Let visible paper fibers gently interrupt fine detail, adding matte texture, restrained contrast, slightly mottled shadows, and delicate fading toward the edges. Keep the original subject and composition.", "credit": "William Henry Fox Talbot / The Metropolitan Museum of Art. The Met Open Access / Public Domain.", "source": "https://www.metmuseum.org/essays/william-henry-fox-talbot-1800-1877-and-the-invention-of-photography", "local": "calotype.webp", "title": "Calotype", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "canny-edge-detection": {"prompt": "Apply Canny Edge Detection, converting the photograph into thin, crisp white binary outlines on a pure black background. Trace significant boundaries with continuous, nearly single-pixel lines, suppressing weak texture and isolated noise. Remove color, shading, and filled tonal regions. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "canny-edge-detection.webp", "title": "Canny Edge Detection", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "canvas-extension-schematic": {"prompt": "Apply Canvas Extension using mirrored border content, enlarging the canvas around the untouched photograph. Fill the added margins with reflected continuations of nearby colors, textures, and shapes, creating recognizable symmetrical repetitions at the original boundaries rather than invented scenery. Match exposure and surface detail throughout. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "canvas-extension-schematic.webp", "title": "Canvas Extension", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "carbon-print": {"prompt": "Transform this image into a Carbon Print with deep charcoal pigment, warm neutral midtones, crisp fine detail, and an expansive, unfaded tonal range. Add a subtly textured paper base and slight gelatin relief in dense shadows, with restrained surface sheen and no halftone pattern. Keep the original subject and composition.", "credit": "Adolphe Braun · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Adolphe_Braun_-_Sculptures_from_the_Parthenon,_British_Museum_-_1998.161_-_Cleveland_Museum_of_Art.tif", "local": "carbon-print.webp", "title": "Carbon Print", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "carte-de-visite": {"prompt": "Transform this image into a Carte de Visite, presenting a small warm-brown photographic print on a larger cream rectangular card mount. Use fine albumen detail, subdued studio-like lighting, gently faded highlights, softly worn card corners, and a narrow decorative border without lettering. Keep the original subject and composition.", "credit": "André-Adolphe-Eugène Disdéri · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Andr%C3%A9-Adolphe-Eug%C3%A8ne_Disd%C3%A9ri_-_Duc_de_Coimbra_-_Google_Art_Project.jpg", "local": "carte-de-visite.webp", "title": "Carte de Visite", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "cel-animation": {"prompt": "Transform this image into a Cel Animation frame with clean ink outlines, opaque flat colors, and restrained two-tone shading on foreground subjects. Render the background as detailed painted scenery, adding subtle acetate sheen, tiny paint irregularities, and faint layer shadows between foreground and backdrop. Keep the original subject and composition.", "credit": "Unknown · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:The_Monkey_King_in_Havoc_in_Heaven_(1961-1964_film)_-_Cel_Animation_Art.jpg", "local": "cel-animation.webp", "title": "Cel Animation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "cel-shading": {"prompt": "Transform this image into Cel Shading, using flat saturated color fills, two or three discrete lighting bands, and crisp black contour lines. Replace soft gradients with hard-edged shadow shapes, simplify surface textures, and retain dimensional form through clearly separated light and dark planes. Keep the original subject and composition.", "credit": "Donniedeboer · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Cel_shading_composite_final_image.png", "local": "cel-shading.webp", "title": "Cel Shading", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "chan-vese-level-set": {"prompt": "Apply a Chan–Vese Level Set effect, reducing the photograph to a clean black-and-white binary mask with two uniform regions. Follow broad intensity-defined shapes, smooth their boundaries, and suppress fine texture, tiny holes, and noisy edges. Avoid gradients or decorative outlines. Keep the original subject and composition.", "credit": "Image: Avel Chuklanov · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Cheering-1031743.jpg", "local": "chan-vese-level-set.webp", "title": "Chan–Vese Level Set", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "channel-mixer": {"prompt": "Apply a Channel Mixer effect, rebuilding red from green, green from blue, and blue from red. Produce striking false-color substitutions across the scene, with altered color-dependent brightness and crisp photographic detail. Preserve smooth gradients and avoid channel misalignment, fringes, or spatial displacement. Keep the original subject and composition.", "credit": "Image: Emre Gencer reo · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Pink_flowers_on_branches_(Unsplash).jpg", "local": "channel-mixer.webp", "title": "Channel Mixer", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "charcoal-contour": {"prompt": "Apply a Charcoal Contours effect with rough black outlines, broad matte shadow masses, and smoky gray shading on off-white paper. Add broken granular strokes, dusty smudges, and visible paper tooth, emphasizing existing edges while leaving bright areas lightly marked. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "charcoal-contour.webp", "title": "Charcoal Contours", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "chemigram": {"prompt": "Transform this image into a Chemigram-style photographic print with organic chemical blooms, wax-resist islands, sharp masked boundaries, and concentric reaction bands. Use warm paper whites, deep brown-black deposits, amber stains, and granular silver textures, translating existing forms into irregular developed regions. Keep the original subject and composition.", "credit": "Paolo Monti · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Paolo_Monti_-_Serie_fotografica_-_BEIC_6363655.jpg", "local": "chemigram.webp", "title": "Chemigram", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "chroma-key": {"prompt": "Apply a vintage Chroma Key composite effect, separating the foreground with slightly hard matte edges and placing a flatter, independently lit rendering of the existing background behind it. Add restrained green spill, thin color fringes, minor edge chatter, and mismatched grain between layers. Keep the original subject and composition.", "credit": "Imyzc. CC BY-SA 3.0", "source": "https://commons.wikimedia.org/wiki/File:Chroma_key.png", "local": "chroma-key.webp", "title": "Chroma Key", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "chroma-subsampling": {"prompt": "Apply Chroma Subsampling, preserving sharp brightness details while reducing color resolution. Make saturated boundaries bleed slightly into neighboring pixels, with small blocky color patches around vivid edges and fine colored details. Retain clear luminance contours and natural lighting without overall blur. Keep the original subject and composition.", "credit": "Image: Anna Goncharova goanne · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Peaceful_landscape_in_Yosemite_(Unsplash).jpg", "local": "chroma-subsampling.webp", "title": "Chroma Subsampling", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "chromadepth-3d": {"prompt": "Apply a chromatic depth 3D effect, mapping foreground forms to vivid red and orange, middle distances to yellow and green, and distant areas to cyan and deep blue. Use black negative space, crisp boundaries, and flat saturated color without stereo ghosting. Keep the original subject and composition.", "credit": "Paweł Janczewski · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Katarzyna_Kobylarz_-_Drzewo_%C5%BBycia_Obraz_w_technologii_3D_Chromadepth_2017_r.jpg", "local": "chromadepth-3d.webp", "title": "ChromaDepth 3D", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "chromatic-aberration": {"prompt": "Apply a Chromatic Aberration effect with subtle red and cyan-blue fringes along high-contrast edges, increasing progressively toward the frame corners. Keep the central region nearly aligned and sharp, with slight radial color separation near the perimeter rather than uniform ghosting; keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "chromatic-aberration.webp", "title": "Chromatic Aberration", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "chromolithography": {"prompt": "Apply a Chromolithography effect with rich, opaque reds, blues, yellows, and greens printed in overlapping layers. Add irregular crayon stippling, subtly misregistered color edges, dense ink coverage, and warm paper texture. Preserve clear outlines and use layered pigment rather than photographic gradients. Keep the original subject and composition.", "credit": "DeBaptiste, George, 1815-1875, publisher; DeBaptiste, George, 1815-1875, copyright clai… · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Toussaint_L%27Ouverture_-_Corrie%27s_Detroit_Chromo_Lith._office._LCCN2014645197.tif", "local": "chromolithography.webp", "title": "Chromolithography", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "chronophotography": {"prompt": "Apply a Chronophotography effect, showing multiple overlapping phases of the subject's movement within one undivided frame. Use pale monochrome silhouettes, crisp stroboscopic contours, measured spacing, subtle photographic grain, and a dark stationary background that retains the original setting's structure. Keep the original subject and composition.", "credit": "Étienne-Jules Marey · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:%C3%89tienne-Jules_Marey_-_Chronophotograph_of_a_Flying_Heron_-_2009.349_-_Cleveland_Museum_of_Art.tif", "local": "chronophotography.webp", "title": "Chronophotography", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "cinemagraph": {"prompt": "Apply a Cinemagraph aesthetic, making the scene appear completely frozen except for one small region of implied motion. Use delicate localized blur in existing smoke, water, or loose fabric, with seamless boundaries and otherwise tack-sharp surroundings. Preserve photographic lighting and avoid global movement streaks. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/cinemagraph", "title": "Cinemagraph · 本库原创图解", "previewKind": "原创技法示意", "local": "cinemagraph.webp"},
  "cinerama": {"prompt": "Apply a three-panel panoramic cinema effect with a gently curved-screen appearance, subtle perspective differences between three equal vertical sections, and faint seams at their joins. Add slightly mismatched panel exposure, rich projected-film color, fine grain, and soft peripheral falloff without cropping. Keep the original subject and composition.", "credit": "Chemical Engineer · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:This_Is_Cinerama_02.jpg", "local": "cinerama.webp", "title": "Cinerama", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "circle-packing-mosaic": {"prompt": "Transform this image into a Circle Packing Mosaic of non-overlapping disks in varied sizes, each filled with a sampled local color. Fit smaller circles into remaining spaces, leave narrow neutral background gaps, and use crisp circular edges without internal gradients or outlines; keep the original subject and composition.", "credit": "Image: Pete Bellis petebellis · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Coffee_cup_in_woman%27s_hands_(Unsplash).jpg", "local": "circle-packing-mosaic.webp", "title": "Circle Packing Mosaic", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "clahe-local-contrast": {"prompt": "Apply CLAHE Local Contrast to reveal fine detail within separate tonal neighborhoods, lifting shadow textures and clarifying bright surfaces without uniformly increasing contrast. Keep colors natural, highlights controlled, edges crisp, and grain restrained; avoid harsh halos or obvious tiled boundaries. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "clahe-local-contrast.webp", "title": "CLAHE Local Contrast", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "classical-image-inpainting": {"prompt": "Apply Classical Image Inpainting to a small damaged or distracting background area, reconstructing it from nearby colors, textures, and continuing contours. Blend the repair seamlessly, allowing slight local softness without introducing new objects, conspicuous seams, or altered lighting. Leave everything outside the repair unchanged. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "classical-image-inpainting.webp", "title": "Classical Image Inpainting", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "cliche-verre": {"prompt": "Transform this image into a Cliché Verre print resembling a delicate scratched-glass drawing transferred onto photographic paper. Use fluid dark lines, irregular etched hatching, softly blurred line edges, and warm ivory highlights. Add sparse coating specks and gently uneven exposure without conventional photographic grain. Keep the original subject and composition.", "credit": "Jean-Baptiste Camille Corot · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Jean_Baptiste_Camille_Corot_-_A_Souvenir_of_the_Bas-Br%C3%A9au_-_1925.561_-_Cleveland_Museum_of_Art.tif", "local": "cliche-verre.webp", "title": "Cliché Verre", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "collotype": {"prompt": "Apply a Collotype effect, converting the image into a finely detailed monochrome ink print with smooth tonal transitions, deep shadows, and delicate highlights. Introduce microscopic wormlike reticulation, subtle matte paper fibers, and softly absorbed ink edges without any regular halftone dots. Keep the original subject and composition.", "credit": "User:CatOnMars · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Collotype_of_Cooking_Oil_Coupon,_Hangzhou_National_Archives_113.jpg", "local": "collotype.webp", "title": "Collotype", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "color-blindness-simulation": {"prompt": "Apply a Color-Blindness Simulation effect using a deuteranopia approximation. Compress red–green distinctions into similar muted yellow-brown tones while retaining clearer blue–yellow separation. Preserve natural brightness relationships, photographic texture, sharp edges, and existing illumination; avoid uniform desaturation or a simple tinted overlay. Keep the original subject and composition.", "credit": "Image: Keith Hardy keithhardy2001 · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Namib_Desert,_Namibia_(Unsplash).jpg", "local": "color-blindness-simulation.webp", "title": "Color-Blindness Simulation", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "color-channel-noise": {"prompt": "Apply a Color Channel Noise effect with independent red, green, and blue speckles scattered across the image. Make chromatic grain most visible in shadows and smooth surfaces, with occasional bright single-pixel flecks. Retain underlying contours and lighting without shifting entire color layers; keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "color-channel-noise.webp", "title": "Color Channel Noise", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "color-inversion": {"prompt": "Apply a Color Inversion effect, subtracting each RGB channel from its maximum to produce an exact photographic negative. Turn white black, black white, red cyan, green magenta, and blue yellow, retaining every original edge, texture, and tonal transition without added artifacts. Keep the original subject and composition.", "credit": "Image: Matt Howard thematthoward · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Just_leaving_(Unsplash)_(cropped).jpg", "local": "color-inversion.webp", "title": "Color Inversion", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "color-negative": {"prompt": "Apply a Color Negative effect, reversing every red, green, and blue channel so highlights become dark, shadows become light, and colors turn into their exact complements. Render uncanny cyan, magenta, and yellow relationships while retaining sharp detail and smooth texture. Keep the original subject and composition.", "credit": "LoMit", "source": "https://commons.wikimedia.org/wiki/File:Color_print_film_strip_01_-_negative.jpg", "local": "color-negative.webp", "title": "Color print film strip 01 - negative", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "combination-printing": {"prompt": "Apply a Combination Printing treatment with seamlessly blended tonal regions, carefully balanced local exposures, and coherent illumination across the scene. Use warm monochrome silver-print tones, fine paper grain, subtly softened masking transitions, and rich but detailed shadows, avoiding visible collage seams. Keep the original subject and composition.", "credit": "Oscar Gustav Rejlander / Wikimedia Commons. Public domain / faithful reproduction on Commons.", "source": "https://www.metmuseum.org/art/collection/search/294822", "local": "combination-printing.webp", "title": "Combination Printing", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "composite-portraiture": {"prompt": "Apply a Composite Portraiture effect using subtly offset, translucent exposures of the same subject. Align central features so they remain comparatively sharp while hair, ears, jawlines, and outer contours accumulate soft ghost outlines. Use muted monochrome, delicate plate grain, and diffuse historical studio lighting. Keep the original subject and composition.", "credit": "Francis Galton · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Galton_Composite_Photograph_of_Family.jpg", "local": "composite-portraiture.webp", "title": "Composite Portraiture", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "computational-night-mode": {"prompt": "Apply a Computational Night Mode effect with readable shadow detail, clear low-light colors, restrained grain, and balanced bright lamps against deep evening tones. Retain natural surface detail rather than waxy smoothing, with faint motion ghosts only around already moving elements. Keep the original subject and composition.", "credit": "The wub · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Aurora_Borealis_2024-05-10_from_Theydon_Bois,_Essex_03.jpg", "local": "computational-night-mode.webp", "title": "Computational Night Mode", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "connected-components": {"prompt": "Transform this image into a Connected Components visualization, separating contiguous patches of similar brightness into individually labeled color regions. Assign each disconnected patch a distinct saturated color, preserve holes and irregular boundaries, and eliminate photographic shading, texture, and gradients for a crisp analytical appearance. Keep the original subject and composition.", "credit": "Image: Vincent van Zalinge vincentvanzalinge · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Perched_blue_and_orange_bird_(Unsplash),_crop.jpg", "local": "connected-components.webp", "title": "Connected Components", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "contour-extraction": {"prompt": "Apply Contour Extraction, reducing the photograph to continuous pale boundary lines on a black field. Trace closed silhouettes, internal holes, and nested region borders with clean, uniformly thin strokes and slightly polygonal turns. Remove surface shading, color, and incidental texture. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "contour-extraction.webp", "title": "Contour Extraction", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "controlnet-conditioning": {"prompt": "Apply a ControlNet Conditioning visualization, retaining the photograph and extending the canvas with an aligned contour-map panel beside it. Show thin white structural lines on black, tracing the same silhouettes, facial landmarks, and major interior edges. Keep the map clean, without labels or interface elements. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "controlnet-conditioning.webp", "title": "ControlNet Conditioning", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "convex-hull-mask": {"prompt": "Apply a Convex Hull Mask effect to the main subject silhouette, enclosing its outermost points within one solid white convex polygon against black. Bridge inward dents, fill every interior hole, and use straight, angular boundary segments without texture or shading. Keep the original subject and composition.", "credit": "Image: NeONBRAND neonbrand · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Downtown,_Las_Vegas,_United_States_(Unsplash).jpg", "local": "convex-hull-mask.webp", "title": "Convex Hull Mask", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "conways-game-of-life": {"prompt": "Transform this image into a Conway's Game of Life grid snapshot, constructing recognizable forms from small white live cells on a black square lattice. Include characteristic four-cell blocks, three-cell blinker rows, and five-cell glider clusters along contours, with hard edges and no tonal gradients. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/conways-game-of-life", "title": "Conway's Game of Life · 本库原创图解", "previewKind": "原创技法示意", "local": "conways-game-of-life.webp"},
  "crash-zoom": {"prompt": "Apply a Crash Zoom effect as a frozen instant of rapid optical magnification. Anchor the existing focal subject sharply while stretching surrounding details into radial streaks, with faint concentric scale echoes, intensified peripheral blur, and punchy contrast; avoid cropping or changing the viewpoint. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/crash-zoom", "title": "Crash Zoom · 本库原创图解", "previewKind": "原创技法示意", "local": "crash-zoom.webp"},
  "cross-processing": {"prompt": "Apply a Cross Processing effect with pronounced cyan-green shadows, warm yellow highlights, and unexpectedly saturated reds. Increase contrast, deepen dark areas, and introduce fine photographic grain with uneven color shifts across the tonal range, creating chemically altered film rather than a uniform tint. Keep the original subject and composition.", "credit": "Jenna Post", "source": "https://commons.wikimedia.org/wiki/File:Central_Camera_Company.jpg", "local": "cross-processing.webp", "title": "Central Camera Company", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "cross-stitch-pattern": {"prompt": "Transform this image into a Cross-Stitch Pattern composed of evenly spaced X-shaped thread stitches on pale woven fabric. Sample a restrained color palette from the photo, assign one color per grid cell, and leave small fabric gaps between stitches. Show subtle thread texture; keep the original subject and composition.", "credit": "Image: Luca Bravo · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Sunset_at_Times_Square,_New_York_City_(2017).jpg", "local": "cross-stitch-pattern.webp", "title": "Cross-Stitch Pattern", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "crosshatching": {"prompt": "Transform this image into a Crosshatching drawing built entirely from intersecting sets of fine black parallel lines on white paper. Layer diagonal strokes densely in shadows, use fewer crossings in midtones, and leave highlights mostly empty. Avoid solid gray fills; keep the original subject and composition.", "credit": "Image: Nicolai Berntsen nicolaiberntsen · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:New_York_city_center_street_at_night-time_(Unsplash).jpg", "local": "crosshatching.webp", "title": "Crosshatching", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "crowd-simulation": {"prompt": "Apply a Crowd Simulation effect by populating available background space with dense groups of small, varied digital figures. Give individuals different poses, clothing colors, orientations, and spacing, with believable perspective, mutual occlusion, and shared environmental lighting. Avoid identical repeated formations or obscuring the focal subject. Keep the original subject and composition.", "credit": "Paul Donnellan · CC BY 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Crowd_simulation,_Covent_Garden.jpg", "local": "crowd-simulation.webp", "title": "Crowd Simulation", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/"},
  "crt-scanlines": {"prompt": "Apply a CRT scanlines effect, covering the image with fine alternating bright and dark horizontal bands. Add subtle red-green-blue phosphor structure, gentle highlight bloom, slightly curved screen geometry, softened corner focus, and deep but luminous blacks without heavy tape tracking damage. Keep the original subject and composition.", "credit": "Scan by NYPL (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Full-page_portrait_of_Matthew_in_gold_frame_on_purple_background,_with_gold,_green,_and_other_colors_(NYPL_b12455533).jpg", "local": "crt-scanlines.webp", "title": "CRT Scanlines, applied to “Full-page portrait of Matthew in gold frame on purple background, with gold, gre”", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "crystal-ball-refraction": {"prompt": "Apply Crystal Ball Refraction to a prominent circular region, bending and stretching the underlying photograph as though seen through a clear glass sphere. Add curved edge compression, subtle rim highlights, and delicate reflections while leaving the surrounding image undistorted. Retain natural colors. Preserve the original subject and composition.", "credit": "Image: Yaoqi LAI yaoqiqiqilai · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Public_Transportation_(Unsplash).jpg", "local": "crystal-ball-refraction.webp", "title": "Crystal Ball Refraction", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "crystoleum": {"prompt": "Apply a Crystoleum effect, placing fine photographic detail beneath gently convex glass with soft hand-painted color visible from behind. Combine delicate rosy, blue, and cream pigments with photographic shading, glossy curved reflections, subtle edge refraction, and a luminous sense of suspended color. Keep the original subject and composition.", "credit": "Rijksmuseum · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Portret_in_lijst,_RP-F-F17623.jpg", "local": "crystoleum.webp", "title": "Crystoleum", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "cyanotype-simulation": {"prompt": "Apply a Cyanotype Simulation effect, converting the photograph into rich Prussian blue shadows, blue midtones, and clean paper-white highlights. Create a matte photographic print appearance with subtle paper texture and delicate tonal detail, without technical annotations, gridlines, or drawn blueprint outlines. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "cyanotype-simulation.webp", "title": "Cyanotype Simulation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "cyanotype": {"prompt": "Transform this image into a Cyanotype with deep Prussian blue shadows, pale blue intermediate tones, and clean paper-white highlights. Add matte watercolor-paper fibers, subtle coating irregularities, delicate translucent tonal transitions, and softly brushed blue borders, avoiding any other ink colors. Keep the original subject and composition.", "credit": "Anna Atkins / The Metropolitan Museum of Art. The Met Open Access / Public Domain.", "source": "https://www.metmuseum.org/art/collection/search/286656", "local": "cyanotype.webp", "title": "Cyanotype", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "cymatics": {"prompt": "Transform this image into a Cymatics study, using fine pale sand gathered into branching nodal lines, symmetrical lattices, and concentric rings across dark vibrating surfaces. Introduce shallow liquid cells, rippling highlights, granular deposits, and precise standing-wave geometry that follows existing forms. Keep the original subject and composition.", "credit": "Hladnison · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:1010_Hz.jpg", "local": "cymatics.webp", "title": "Cymatics", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "daguerreotype": {"prompt": "Transform this image into a Daguerreotype on polished silver-plated copper, with exceptionally sharp fine detail, silvery monochrome tones, and mirrorlike reflections. Suggest viewing-angle-dependent contrast through localized bright sheen and dark reflective patches, adding delicate peripheral tarnish and microscopic surface scratches. Keep the original subject and composition.", "credit": "Louis Daguerre; Société française de photography / Wikimedia Commons. Public domain (Commons PDM / faithful reproduction).", "source": "https://www.metmuseum.org/essays/daguerre-1787-1851-and-the-invention-of-photography", "local": "daguerreotype.webp", "title": "Daguerreotype", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "dark-channel-dehaze": {"prompt": "Apply Dark Channel Dehaze, removing the milky atmospheric veil to reveal distant structures, deeper blacks, richer natural colors, and stronger local contrast. Preserve believable depth and existing light direction, keeping skies smooth and avoiding dark edge halos, excessive saturation, or crushed shadow detail. Keep the original subject and composition.", "credit": "Image: Boris Smokrovic borisworkshop · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Dragonfly_landing_(Unsplash).jpg", "local": "dark-channel-dehaze.webp", "title": "Dark Channel Dehaze", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "databending": {"prompt": "Apply a databending effect with abrupt horizontal offsets, displaced scanline bands, fractured color channels, and unexpected patches of corrupted pixel data. Mix intact photographic areas with jagged digital discontinuities, acidic color breaks, and sparse static, avoiding flowing motion trails or uniformly distributed distortion. Keep the original subject and composition.", "credit": "Subhashish Panigrahi", "source": "https://commons.wikimedia.org/wiki/File:Databending_Odia_Wikipedia_article_raw_image.jpg", "local": "databending.webp", "title": "Databending Odia Wikipedia article raw image", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "datamoshing": {"prompt": "Apply a datamoshing effect with blocky compression fragments, smeared color patches, and displaced textures that appear dragged along implied motion paths. Let selected edges dissolve into fluid rectangular trails and mismatched image residues while retaining recognizable central features. Use uneven digital breakup rather than uniform noise. Keep the original subject and composition.", "credit": "Lee Brenton. CC BY 3.0", "source": "https://commons.wikimedia.org/wiki/File:My_first_datamosh.webm", "local": "datamoshing.webp", "title": "Datamoshing", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/"},
  "day-for-night": {"prompt": "Apply a Day for Night effect by lowering exposure, cooling colors toward midnight blue, suppressing bright skies, and deepening shadows without losing essential detail. Turn existing directional sunlight into restrained moonlight, mute warm surfaces, and preserve subtly visible silhouettes. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/day-for-night", "title": "Day for Night · 本库原创图解", "previewKind": "原创技法示意", "local": "day-for-night.webp"},
  "decalcomania": {"prompt": "Apply a Decalcomania effect with pressed-paint textures, branching vein networks, spongy cellular patches, and irregular pools of thick pigment. Use earthy greens, ochres, cream, and dark brown, with glossy ridges and torn-looking transfer edges suggesting surfaces pulled apart. Keep the original subject and composition.", "credit": "H. Grobe · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Decalcomanie-03_hg.jpg", "local": "decalcomania.webp", "title": "Decalcomania", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "decorrelation-stretch": {"prompt": "Apply a Decorrelation Stretch effect, separating previously similar colors into vivid cyan, magenta, yellow, violet, and green variations. Amplify subtle chromatic differences across muted surfaces while retaining recognizable tonal structure, fine texture, and crisp boundaries, without adding objects or geometric distortion. Keep the original subject and composition.", "credit": "Image: Dhruv Deshmukh dhruvywuvy · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Looking_Up_Architecture_(Unsplash).jpg", "local": "decorrelation-stretch.webp", "title": "Decorrelation Stretch", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "deep-focus-photography": {"prompt": "Apply a Deep Focus effect with simultaneously sharp foreground, middle ground, and background details. Resolve fine textures throughout, remove selective-focus blur, and use strong directional illumination, clean tonal separation, and restrained film grain to clarify spatial layers without artificial sharpening halos. Keep the original subject and composition.", "credit": "Photo by User:Utudanuki", "source": "https://commons.wikimedia.org/wiki/File:Deepfocus.JPG", "local": "deep-focus-photography.webp", "title": "Deepfocus", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "deep-fried-meme": {"prompt": "Apply a Deep-Fried Meme effect with violently boosted saturation, crushed shadows, glaring yellow-white highlights, coarse compression blocks, and crunchy sharpening halos. Push reds and oranges toward neon, add scattered digital noise and exaggerated flare glints, and retain recognizable silhouettes. Keep the original subject and composition.", "credit": "Lord Belbury · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Deep_fried_meme.jpg", "local": "deep-fried-meme.webp", "title": "Deep-Fried Meme", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "deepdream": {"prompt": "Apply a DeepDream effect with recurring eye-like motifs, animal-shaped suggestions, and recursive organic patterns emerging from existing textures. Intensify jewel-toned colors, curl edges into nested forms, and create intricate, hallucinatory surface detail while keeping the underlying scene legible rather than replacing it entirely. Keep the original subject and composition.", "credit": "Google Inc.; Alexander Mordvintsev, Christopher Olah & Mike Tyka. CC BY 4.0", "source": "https://research.google/blog/inceptionism-going-deeper-into-neural-networks/", "local": "deepdream.webp", "title": "DeepDream", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "deepfake": {"prompt": "Apply a Deepfake effect by subtly synthesizing a changed facial expression while retaining the person's identity. Use photorealistic facial texture, slightly over-smoothed skin, faint blending seams near the jawline, and minor inconsistencies in eye reflections, matching the surrounding light and color. Keep the original subject and composition.", "credit": "Steve Jurvetson", "source": "https://commons.wikimedia.org/wiki/File:DigiDoug_DeepFake_at_TED2019.jpg", "local": "deepfake.webp", "title": "DigiDoug DeepFake at TED2019", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "delaunay-triangle-mosaic": {"prompt": "Transform this image into a Delaunay Triangle Mosaic of interlocking, non-overlapping triangles filled with flat sampled colors. Concentrate smaller facets along strong contours and use larger triangles across smooth areas. Create crisp shared edges without outlines, gaps, or shading within individual facets; keep the original subject and composition.", "credit": "Image: Mark Cruz mark_crz · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Man_working_on_computer_(Unsplash).jpg", "local": "delaunay-triangle-mosaic.webp", "title": "Delaunay Triangle Mosaic", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "depth-map-portrait": {"prompt": "Apply a Depth-Map Portrait effect, keeping the face and principal subject sharply resolved while progressively blurring background regions according to apparent distance. Preserve natural skin texture, soft background light discs, and believable focus transitions, with only faint segmentation softness around stray hairs. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/depth-map-portrait", "title": "Depth-Map Portrait · 本库原创图解", "previewKind": "原创技法示意", "local": "depth-map-portrait.webp"},
  "difference-of-gaussians": {"prompt": "Apply Difference of Gaussians, creating a monochrome bandpass rendering with pale and dark contour halos around medium-scale details. Flatten broad lighting gradients and suppress the finest grain, leaving selected textures and high-contrast transitions prominent against midgray. Use soft, closely spaced edge bands. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "difference-of-gaussians.webp", "title": "Difference of Gaussians", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "digital-color-grading": {"prompt": "Apply Digital Color Grading with cool blue shadows, warm amber highlights, controlled skin tones where present, and a unified cinematic palette. Deepen blacks, gently compress bright areas, and use selective saturation to establish consistent color relationships across the scene without flattening local detail. Keep the original subject and composition.", "credit": "SavidgeMichael · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Conjured_Memories_of_a_Grimm_Fairytale_Forest_I_-_Letterboxing.jpg", "local": "digital-color-grading.webp", "title": "Digital Color Grading", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "digital-de-aging": {"prompt": "Apply a Digital De-Aging effect, making the person appear naturally younger through softened wrinkles, reduced under-eye hollows, subtly fuller cheeks, and firmer facial contours. Retain pores, characteristic facial proportions, believable hair texture, and lighting-consistent shadows, avoiding waxy smoothing or exaggerated reshaping. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/digital-de-aging", "title": "Digital De-Aging · 本库原创图解", "previewKind": "原创技法示意", "local": "digital-de-aging.webp"},
  "digital-video-effects": {"prompt": "Apply an early Digital Video Effects treatment, presenting the image as a nearly full-frame floating video panel with slight perspective tilt, beveled borders, and a curled corner. Add smaller offset panel echoes behind it, subtle scanlines, and saturated electronic highlights. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/digital-video-effects", "title": "Digital Video Effects · 本库原创图解", "previewKind": "原创技法示意", "local": "digital-video-effects.webp"},
  "diorama-light-change": {"prompt": "Apply a Diorama Light Change effect with translucent painted-canvas texture, warm daylight transitioning into cool blue night, and soft shadows shifting across existing forms. Suggest rear illumination revealing faint details within the scene, with glowing windows or luminous accents where appropriate. Keep the original subject and composition.", "credit": "Pierre Tribhou · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Bry-sur-Marne_Diorama_de_Louis_Daguerre_01.jpg", "local": "diorama-light-change.webp", "title": "Diorama Light Change", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "direct-animation-on-film": {"prompt": "Apply a Direct Animation on Film effect with scratched white contours, irregular translucent paint patches, saturated color splashes, and raw black emulsion textures. Add pinholes, scraped streaks, pigment pooling, and slightly misaligned marks that suggest handmade frame-by-frame energy. Keep the original subject and composition.", "credit": "Stan Brakhage · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Mothlight_(1963)_title.jpg", "local": "direct-animation-on-film.webp", "title": "Direct Animation on Film", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "displacement-map": {"prompt": "Apply Displacement Map, warping local contours according to an irregular noise-like relief pattern. Introduce uneven bulges, shallow dents, and meandering shifts across existing textures, with smooth transitions between distorted areas. Retain photographic detail and original lighting without overlaying an actual relief surface. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "displacement-map.webp", "title": "Displacement Map", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "displacement-mapping": {"prompt": "Apply a Displacement Mapping effect that visibly pushes and pulls image surfaces into textured ridges, ripples, and shallow grooves. Bend existing lines and color boundaries along a coherent relief pattern, adding matching highlights and crevice shadows while leaving major forms recognizable. Keep the original subject and composition.", "credit": "Morn", "source": "https://commons.wikimedia.org/wiki/File:BMRT_-_Displacement_Shader.png", "local": "displacement-mapping.webp", "title": "BMRT - Displacement Shader", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "dissolve": {"prompt": "Apply a Dissolve effect, depicting the midpoint of a cinematic transition as the original scene fades into a softly illuminated alternative setting. Blend both environments at partial opacity, creating translucent overlapping contours, intermingled light, and gentle tonal merging without a hard dividing edge. Keep the original subject and composition.", "credit": "Shohei Ohtaki / Motion Prompt · 本地取帧", "source": "https://showheyohtaki.github.io/motion-prompt/#044", "license": "MIT", "licenseUrl": "https://github.com/showheyohtaki/motion-prompt/blob/main/LICENSE", "title": "Dissolve · 动效分镜", "previewKind": "开源同类示例", "local": "dissolve.webp"},
  "dissolving-views": {"prompt": "Apply a Dissolving Views effect showing a single frozen midpoint between two aligned painted versions of the scene. Blend warm daylight with cool twilight, translucent overlapping details, soft lantern-projector illumination, slight registration ghosts, and a gently darkened screen perimeter. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/dissolving-views", "title": "Dissolving Views · 本库原创图解", "previewKind": "原创技法示意", "local": "dissolving-views.webp"},
  "distance-fog": {"prompt": "Apply a Distance Fog effect that progressively blends scenery into a uniform muted blue-gray according to depth. Keep nearby details crisp and saturated, reduce contrast and color in middle distances, and merge far silhouettes into smooth haze without visible smoke curls or particles. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/distance-fog", "title": "Distance Fog · 本库原创图解", "previewKind": "原创技法示意", "local": "distance-fog.webp"},
  "distance-transform": {"prompt": "Transform this image into a Distance Transform visualization, isolating the main foreground silhouettes against solid black. Make their boundaries dark and increase grayscale brightness progressively toward points deepest inside each shape, producing smooth interior ridges rather than directional illumination or photographic shading. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "distance-transform.webp", "title": "Distance Transform", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "distortion-photography": {"prompt": "Apply a Distortion Photography effect resembling a curved mirror reflection, with localized stretching, swollen curves, pinched shapes, and smoothly bent contours. Retain photographic surface texture, realistic highlights, and continuous lighting across warped areas rather than adding painterly abstraction. Keep the original subject recognizable and preserve the overall composition.", "credit": "ŠJů (cs:ŠJů) · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:V%C4%9Btru%C5%A1e,_zrcadlov%C3%A9_bludi%C5%A1t%C4%9B.jpg", "local": "distortion-photography.webp", "title": "Distortion Photography", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "dolly-zoom": {"prompt": "Apply a Dolly Zoom effect as a single cinematic still, keeping the main subject sharp and unchanged in size while stretching background depth along the existing perspective lines. Add restrained radial streaking, exaggerated near-to-far separation, and subtle optical softness toward the edges. Keep the original subject and composition.", "credit": "Shohei Ohtaki / Motion Prompt · 本地取帧", "source": "https://showheyohtaki.github.io/motion-prompt/#032", "license": "MIT", "licenseUrl": "https://github.com/showheyohtaki/motion-prompt/blob/main/LICENSE", "title": "Dolly Zoom · 动效分镜", "previewKind": "开源同类示例", "local": "dolly-zoom.webp"},
  "dot-matrix-printout": {"prompt": "Transform this image into a dot-matrix printout on warm off-white continuous-feed paper. Build every contour and tonal area from round black ink dots in regular rows, with stepped curves, faint ribbon strikes, occasional missing dots, and subtle horizontal printhead banding. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/dot-matrix-printout", "title": "Dot-Matrix Printout · 本库原创图解", "previewKind": "原创技法示意", "local": "dot-matrix-printout.webp"},
  "double-exposure": {"prompt": "Apply a Double Exposure effect by layering a translucent secondary view of existing environmental details across the photograph. Let textures pass through the main subject, with overlapping contours, luminous combined highlights, muted shadows, and fine analog grain. Keep the primary silhouette clearly recognizable. Keep the original subject and composition.", "credit": "William H. Mumler / possibly Helen F. Mumler; J. Paul Getty Museum. Getty Open Content; historical work in the public domain.", "source": "https://www.metmuseum.org/art/collection/search/296300", "local": "double-exposure.webp", "title": "Double Exposure", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "droste-recursion": {"prompt": "Apply Droste Recursion to nest progressively smaller copies of the photograph inside itself, twisting them into a seamless inward spiral. Repeat recognizable colors, textures, and silhouettes through each shrinking layer, with smooth joins and a tightly receding center. Preserve the original subject and composition within the repeated image.", "credit": "Image: Jude Dias judedias · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Thick_pine_forest_(Unsplash).jpg", "local": "droste-recursion.webp", "title": "Droste Recursion", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "dunning-process": {"prompt": "Apply a Dunning Process treatment as a black-and-white optical composite, separating a clearly lit foreground from the existing setting. Introduce fine silhouette fringes, subtly different contrast between layers, soft background detail, and period film grain. Keep foreground surfaces naturally shaded rather than visibly blue or yellow. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/dunning-process", "title": "Dunning Process · 本库原创图解", "previewKind": "原创技法示意", "local": "dunning-process.webp"},
  "duotone-mapping": {"prompt": "Apply a Duotone Mapping effect, replacing the full color palette with a continuous gradient from deep navy shadows to warm peach highlights. Map intermediate brightness into blends of these two inks, preserving readable contours, fine texture, and the existing lighting pattern. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "duotone-mapping.webp", "title": "Duotone Mapping", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "duotone": {"prompt": "Apply a Duotone effect using deep indigo for shadows and vivid coral for highlights, with intermediate tones formed only by blends of these two inks. Preserve tonal separation, crisp silhouettes, and fine surface detail, adding subtle matte print grain without introducing additional hues. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins (public domain) · duotone applied for the Atlas", "source": "https://helpx.adobe.com/photoshop/using/duotones.html", "local": "duotone.webp", "title": "Duotone", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "dutch-angle": {"prompt": "Apply a Dutch Angle effect by rotating the entire image plane to create a clearly tilted horizon and slanting verticals. Preserve natural perspective, realistic lighting, original colors, and coherent edges; extend borders subtly rather than cropping important details. Keep the original subject and relative composition.", "credit": "Wil540 art", "source": "https://commons.wikimedia.org/wiki/File:Person_passed_out_on_sidewalk_photographed_with_a_dutch_angle_NYC.tif", "local": "dutch-angle.webp", "title": "Person passed out on sidewalk photographed with a dutch angle NYC", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "dynamation": {"prompt": "Apply a rear-projection stop-motion composite effect, rendering the main subject with tactile miniature textures, painted surfaces, and slightly rigid articulation. Give the photographic surroundings softer projected grain, faint matte-edge halos, and modest exposure mismatch, retaining existing foreground overlaps to integrate the model. Keep the original subject and composition.", "credit": "Columbia Pictures · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:20_million_miles_to_earth_(1957)_Ymir.png", "local": "dynamation.webp", "title": "Dynamation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "emboss-2": {"prompt": "Apply an Embossed Relief effect, replacing photographic colors with a neutral gray surface. Turn existing contours and texture into shallow raised impressions, with bright upper-left edges and dark lower-right edges suggesting directional light. Keep broad areas flat and avoid deep sculptural changes. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "emboss-2.webp", "title": "Embossed Relief", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "emboss": {"prompt": "Apply an emboss effect, translating image detail into shallow raised relief on a matte silver-gray surface. Define contours with paired bright upper-left edges and dark lower-right edges, flatten original colors, and retain fine texture as subtle engraved ridges under consistent raking light. Keep the original subject and composition.", "credit": "Varsho", "source": "https://commons.wikimedia.org/wiki/File:Industrial_Bio-Test_embossed_corporate_seal.jpg", "local": "emboss.webp", "title": "Industrial Bio-Test embossed corporate seal", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "false-color-infrared": {"prompt": "Apply a False-Color Infrared effect, rendering existing vegetation crimson or magenta, skies deep cyan to blue, and water nearly black. Give other surfaces unusual pale pink, cool gray, or turquoise tones, with crisp tonal separation and subtle photographic grain. Keep the original subject and composition.", "credit": "Wrev", "source": "https://commons.wikimedia.org/wiki/File:Ribeira_da_Janela_Valley_on_Madeira_Island,_view_from_Levada,_Infrared_False-Color_Film_(10-79.c).jpg", "local": "false-color-infrared.webp", "title": "Ribeira da Janela Valley on Madeira Island, view from Levada, Infrared False-Color Film (10-79.c)", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "fast-corners": {"prompt": "Apply FAST Corners as a sparse feature-detection overlay, placing small bright green crosses at sharp corners, junctions, and distinctive texture points. Leave smooth surfaces largely unmarked, use uniform marker sizes, and preserve the photograph's natural lighting and colors beneath the digital annotations. Keep the original subject and composition.", "credit": "Image: PICSELI picseli · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Monochrome_yin_yang_coffee_(Unsplash).jpg", "local": "fast-corners.webp", "title": "FAST Corners", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "film-colorization": {"prompt": "Apply an early Film Colorization effect, retaining monochrome-style luminance and photographic grain beneath broad, muted color regions. Use restrained peach, dusty blue, olive, and faded brown hues, with slightly imprecise color boundaries and limited variation within each material. Preserve the underlying light and shadow. Keep the original subject and composition.", "credit": "Bink111 · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:A_frame_depicting_Thomas_Hutter_from_moonflix.com_colorization_of_Nosferatu_(1922).jpg", "local": "film-colorization.webp", "title": "Film Colorization", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "film-grain": {"prompt": "Apply a Film Grain effect with irregular, finely clustered silverlike particles across the photograph, most noticeable in midtones and smooth surfaces. Use gently muted colors, soft highlight rolloff, slightly softened edges, and organic density variations rather than uniform digital noise. Keep the original subject and composition.", "credit": "Wiley.andrew.r / CC0; Wikimedia Commons", "source": "https://www.kodak.com/content/products-brochures/Film/kodak-essential-reference-guide-for-filmmakers.pdf", "local": "film-grain.webp", "title": "Film Grain", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "film-noir-lighting": {"prompt": "Apply Film Noir Lighting with stark black-and-white tonality, blinding highlights, pitch-black shadows, and hard illumination from steep angles. Cast narrow venetian-blind stripes across existing surfaces and faces where present. Add fine silver grain, sharp silhouettes, and minimal shadow fill. Keep the original subject and composition.", "credit": "Robby McKee · CC BY 2.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Self-Portrait_-16_(2757064302).jpg", "local": "film-noir-lighting.webp", "title": "Film Noir Lighting", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "film-tinting": {"prompt": "Apply the Film Tinting effect by converting the photograph to monochrome and bathing the entire frame in a uniform amber dye. Make highlights glow pale gold, midtones deepen to ochre, and dense shadows remain nearly black, with fine grain and minor emulsion wear. Keep the original subject and composition.", "credit": "Eastman Kodak · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Yellow_tinted_nitrate_base.jpg", "local": "film-tinting.webp", "title": "Film Tinting", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "fisheye-distortion": {"prompt": "Apply Fisheye Distortion, creating an exaggerated ultra-wide lens appearance with a bulging center, compressed peripheral details, and strongly bowed straight lines near the frame edges. Maintain continuous photographic texture and existing lighting, without adding a circular black border or new scenery. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "fisheye-distortion.webp", "title": "Fisheye Distortion", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "fisheye-lens": {"prompt": "Apply a Fisheye Lens effect with pronounced barrel distortion, straight lines bowing toward the frame edges, an enlarged central region, and compressed peripheral details. Suggest an extremely wide field of view through curved spatial geometry, subtle corner darkening, and mild edge softness. Keep the original subject and composition.", "credit": "Ermell", "source": "https://commons.wikimedia.org/wiki/File:Adelsdorf_Kirche_Altarraum-20210801-RM-160111.jpg", "local": "fisheye-lens.webp", "title": "Adelsdorf Kirche Altarraum-20210801-RM-160111", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "flash-powder-photography": {"prompt": "Apply a Flash Powder Photography effect with an intense frontal burst of white light, stark monochrome contrast, bright foreground highlights, and abrupt black shadows behind the subject. Freeze fine details with harsh outlines, rapid background light falloff, slight highlight bloom, and coarse historical plate grain. Keep the original subject and composition.", "credit": "Jacob Riis · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:One_of_four_pedlars_who_slept_in_the_celler_of_11_Ludlow_Street_rear.jpg", "local": "flash-powder-photography.webp", "title": "Flash Powder Photography", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "flat-design": {"prompt": "Transform this image into a Flat Design illustration using solid color fields, simplified silhouettes, crisp geometric edges, and a restrained high-contrast palette. Replace surface textures and modeled lighting with uniform fills; omit gradients, grain, bevels, and cast shadows. Keep the original subject and composition.", "credit": "CFCF · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:American_football_icon_simple_flat.svg", "local": "flat-design.webp", "title": "Flat Design", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "flicker-film": {"prompt": "Apply a Flicker Film aesthetic as a static frame, using stark black and white, clipped tonal transitions, faint inverted contour echoes, and sparse optical interference bands. Suggest alternating exposures through localized polarity reversals and subtle illusory color fringes, without adding separate panels. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/flicker-film", "title": "Flicker Film · 本库原创图解", "previewKind": "原创技法示意", "local": "flicker-film.webp"},
  "flip-book": {"prompt": "Apply a Flip Book effect, presenting the image on a small stack of cream paper pages with exposed edges and a gently curled top sheet. Show successive, slightly shifted action frames on the fanned pages, with black ink contours, paper grain, and minor registration jitter. Keep the original subject and composition.", "credit": "SunOfErat · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Filmmuseum_Berlin_-_Max_Skladanowsky_Flip_Book.jpg", "local": "flip-book.webp", "title": "Flip Book", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "flood-fill": {"prompt": "Apply a Flood Fill effect, replacing connected areas of similar color with large, perfectly uniform color blocks. Let fills stop at existing contrast boundaries, retaining irregular silhouettes and enclosed pockets. Use a reduced palette drawn from the photograph, without gradients, brush texture, or added outlines. Keep the original subject and composition.", "credit": "Image: Johnny Lam johnnylam · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Verrazzano-Narrows_Bridge_at_night_by_Johnny_Lam,_2013_(Unsplash).jpg", "local": "flood-fill.webp", "title": "Flood Fill", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "floydsteinberg-dither": {"prompt": "Apply a Floyd–Steinberg Dither effect, converting the image into pure black and white with fine, irregular single-pixel texture. Recreate shading through locally distributed dots and subtle directional wormlike patterns rather than repeated grids, preserving readable contours without gray pixels or smoothing. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "floydsteinberg-dither.webp", "title": "Floyd–Steinberg Dither", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "fluid-simulation": {"prompt": "Apply a Fluid Simulation effect with physically convincing translucent water curling around existing forms. Create coherent flowing sheets, splash crowns, suspended droplets, tiny bubbles, and swirling eddies, with refracted background details and sharp wet highlights. Match gravity, contact surfaces, and scene lighting without obscuring key features. Keep the original subject and composition.", "credit": "Nbrawand · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Render_final.png", "local": "fluid-simulation.webp", "title": "Fluid Simulation", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "focus-stacking": {"prompt": "Apply Focus Stacking to extend crisp detail across the subject’s near and far surfaces. Resolve fine textures, delicate edges, and small structural features at multiple depths while preserving natural background softness. Use seamless sharpness transitions without halos, doubled contours, or exaggerated microcontrast. Keep the original subject and composition.", "credit": "USGS Bee Inventory and Monitoring Lab from Beltsville, Maryland, USA · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Amegilla_stantoni,_f,_face,_Los_Banos_2021-11-10-18.57.33_ZS_PMax_UDR_copy_-_Flickr_-_Sam_Droege.jpg", "local": "focus-stacking.webp", "title": "Focus Stacking", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "forced-perspective": {"prompt": "Apply a Forced Perspective illusion by manipulating apparent scale and depth in existing surroundings, making the subject seem unusually large or small without relocating it. Align overlapping contours, sharpen distant details, and match lighting and contact shadows so separate depths appear connected. Keep the original subject and composition.", "credit": "Livioandronico2013", "source": "https://commons.wikimedia.org/wiki/File:Forced_perspective_gallery_by_Francesco_Borromini.jpg", "local": "forced-perspective.webp", "title": "Forced perspective gallery by Francesco Borromini", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "forward-diffusion-noising": {"prompt": "Apply Forward Diffusion Noising, partially obscuring the photograph with dense, fine Gaussian noise. Mix random multicolored and luminance speckles into every region, weakening contrast, dissolving sharp edges, and burying small textures while leaving broad shapes and underlying colors recognizable. Avoid directional streaks or patterned grain. Keep the original subject and composition.", "credit": "Image: Sebastian Pichler pichler_sebastian · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Bumper_cars_festival_(Unsplash).jpg", "local": "forward-diffusion-noising.webp", "title": "Forward Diffusion Noising", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "fourier-high-pass-filter": {"prompt": "Apply a Fourier High-Pass Filter effect, suppressing broad illumination and smooth color fields until fine structures dominate. Render hair, surface grain, and boundaries as crisp pale and dark traces against neutral gray, with subtle ringing beside strong edges and little remaining tonal depth. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "fourier-high-pass-filter.webp", "title": "Fourier High-Pass Filter", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "fourier-low-pass-filter": {"prompt": "Apply Fourier Low-Pass Filter to suppress fine textures, grain, and sharp boundaries while retaining broad silhouettes and large tonal masses. Create smooth, softly blended color regions with reduced microcontrast and gently diffused lighting. Avoid directional smears and added surface texture. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "fourier-low-pass-filter.webp", "title": "Fourier Low-Pass Filter", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "fourier-magnitude-spectrum": {"prompt": "Apply Fourier Magnitude Spectrum as a dominant translucent visualization over the photograph: a brilliant central point, symmetric starburst streaks, and scattered grayscale frequency speckles against a dark field. Compress brightness to reveal faint surrounding structures, retaining the scene subtly beneath the pattern. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "fourier-magnitude-spectrum.webp", "title": "Fourier Magnitude Spectrum", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "fractal-flames": {"prompt": "Transform this image into Fractal Flames, tracing its recognizable forms with glowing filaments, translucent ribbons, branching fans, and tangled spirals against deep darkness. Repeat delicate structures at multiple scales, blend jewel-toned colors smoothly, and concentrate light into bright knots with airy luminous trails. Keep the original subject and composition.", "credit": "“Jon Zander (Digon3)\" · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Lines_Apophysis_Fractal_Flame.jpg", "local": "fractal-flames.webp", "title": "Fractal Flames", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "fractal-landscape": {"prompt": "Apply a fractal landscape treatment, translating existing masses into rugged procedural terrain with recursively subdivided triangular facets, jagged ridgelines, branching valleys, and repeated roughness at multiple scales. Use earthy elevation colors, cool shadowed crevices, and directional light that reveals the angular relief. Keep the original subject and composition.", "credit": "Stevo-88 · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Fractal_terrain.jpg", "local": "fractal-landscape.webp", "title": "Fractal Landscape", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "frame-differencing": {"prompt": "Apply Frame Differencing to simulate subtracting two slightly offset copies of the photograph. Darken unchanged areas toward black and illuminate displaced boundaries as thin, paired white or colored contours. Emphasize shifted silhouettes while keeping a faint underlying scene visible for recognition. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "frame-differencing.webp", "title": "Frame Differencing", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "frame-interpolation": {"prompt": "Apply a Frame Interpolation effect, rendering a synthetic midpoint between subtly time-offset versions of the scene. Show gently displaced contours, faint double edges around moving details, localized optical-flow stretching, and soft translucent ghosting near occlusions. Retain natural colors and consistent lighting, avoiding uniform motion blur. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "frame-interpolation.webp", "title": "Frame Interpolation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "frangi-ridge-filter": {"prompt": "Transform this image into a Frangi Ridge Filter response map, emphasizing existing thin, elongated, branching structures as luminous white ridges against black. Vary ridge brightness with structural strength, retain multiple widths, and suppress flat surfaces, isolated rounded blobs, and unrelated texture. Keep the original subject and composition.", "credit": "Image: Amith Nair a_myth · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Deep_Wild_Green_(Unsplash).jpg", "local": "frangi-ridge-filter.webp", "title": "Frangi Ridge Filter", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "freelensing": {"prompt": "Apply a Freelensing effect with a narrow, tilted ribbon of sharp detail crossing the main subject and irregular soft blur elsewhere. Introduce pale peach light leaks from one edge, milky flare, lowered local contrast, and gently smeared highlights. Keep the original subject and composition.", "credit": "Ashley Campbell · CC BY 2.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Nikki_...again_(5296923025).jpg", "local": "freelensing.webp", "title": "Freelensing", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "freeze-frame": {"prompt": "Apply a Freeze Frame treatment resembling a single optically duplicated film frame: arrest every visible gesture, retain any existing exposure blur, and emphasize suspended action. Add slightly increased grain, mild contrast buildup, subtle print softness, and tiny dust flecks without motion trails. Keep the original subject and composition.", "credit": "Shohei Ohtaki / Motion Prompt · 本地取帧", "source": "https://showheyohtaki.github.io/motion-prompt/#040", "license": "MIT", "licenseUrl": "https://github.com/showheyohtaki/motion-prompt/blob/main/LICENSE", "title": "Freeze Frame · 动效分镜", "previewKind": "开源同类示例", "local": "freeze-frame.webp"},
  "front-projection": {"prompt": "Apply a Front Projection effect, making the existing background resemble a projected photographic plate behind the foreground subject. Give the backdrop slightly flatter contrast, fine screen texture, and subtle softness, with nearly concealed shadows directly behind the subject and crisp foreground lighting. Keep the original subject and composition.", "credit": "Wikiwikiyarou", "source": "https://commons.wikimedia.org/wiki/File:Front_projection_effect.jpg", "local": "front-projection.webp", "title": "Front projection effect", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "frosted-glass": {"prompt": "Apply Frosted Glass to make the photograph appear viewed through a rough, translucent pane. Scatter nearby details into fine granular distortions, soften edges, mute contrast, and diffuse highlights into cloudy patches while retaining the existing color palette. Avoid sharp reflections or opaque frosting. Preserve the original subject and composition.", "credit": "Image: Christian Gertenbach kc_gertenbach · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Portrait_of_elderly_woman_(Unsplash).jpg", "local": "frosted-glass.webp", "title": "Frosted Glass", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "frutiger-aero": {"prompt": "Transform this image into a Frutiger Aero aesthetic with luminous aqua blues, fresh grassy greens, glossy bubbles, and translucent glass accents. Add rounded reflective surfaces, smooth digital gradients, sparkling white highlights, and bright sky-like illumination. Favor clean, optimistic polish over gritty texture. Keep the original subject and composition.", "credit": "Aarón Ramirez · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Frutiger_Aero_Composite.jpg", "local": "frutiger-aero.webp", "title": "Frutiger Aero", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "fumage": {"prompt": "Apply a Fumage effect by rebuilding tonal forms from translucent soot deposits on warm ivory paper. Use smoky gray veils, curling black wisps, feathered edges, granular carbon specks, and rubbed highlights, letting recognizable details emerge from layered cloudlike stains. Keep the original subject and composition.", "credit": "Edgar Degas · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Factory_Smoke_MET_MM70517.jpg", "local": "fumage.webp", "title": "Fumage", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "fur-simulation": {"prompt": "Apply Fur Simulation by covering the subject’s surfaces with dense, fine strands following its underlying contours. Use varied strand lengths, natural clumping, soft root shadows, directional sheen, and scattered flyaway hairs along the silhouette. Preserve recognizable markings through corresponding fur colors and subtle wind-swept bends. Keep the original subject and composition.", "credit": "Film: Blender Foundation | www.bigbuckbunny.orgScreenshot: User:Toni Grappa · CC BY 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Blender3D_huelle_alles_zusammen.jpg", "local": "fur-simulation.webp", "title": "Fur Simulation", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/"},
  "gabor-filter-bank": {"prompt": "Transform this image into a Gabor Filter Bank visualization using aligned translucent response layers for different angles and texture scales. Highlight horizontal, vertical, and diagonal structures in distinct colors, with fine striped responses and broader luminous bands against subdued dark surfaces. Keep the original subject and composition.", "credit": "Image: Johnson Chou joujiahe · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Two_seeding_dandelions_(Unsplash).jpg", "local": "gabor-filter-bank.webp", "title": "Gabor Filter Bank", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "gamma-curve": {"prompt": "Apply a Gamma Curve effect, strongly lifting midtone brightness while keeping black and white endpoints anchored. Reveal shadow detail, create lighter intermediate tones, and soften the overall tonal weight through a smooth nonlinear adjustment. Preserve color relationships and existing texture without local halos. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "gamma-curve.webp", "title": "Gamma Curve", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "gan-portraits": {"prompt": "Apply a GAN Portraits effect with polished photorealistic facial rendering, soft studio-like illumination, finely synthesized skin texture, and unusually smooth tonal transitions. Introduce subtle generative imperfections in peripheral details, such as uneven accessories, ambiguous hair strands, or gently melted background textures, without changing identity. Keep the original subject and composition.", "credit": "StyleGAN2 · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:GAN_Mensch_StyleGAN2.png", "local": "gan-portraits.webp", "title": "GAN Portraits", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "gaussian-blur": {"prompt": "Apply Gaussian Blur evenly across the photograph, softening edges in every direction with smooth, rounded transitions. Blend fine textures and grain into continuous color gradients, gently diffuse highlights, and reduce small details without directional streaks, doubled contours, or artificial surface texture. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "gaussian-blur.webp", "title": "Gaussian Blur", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "gaussian-pyramid": {"prompt": "Transform this image into a Gaussian Pyramid visualization with one large base photograph and a neatly arranged sequence of progressively smaller copies. Increase smooth Gaussian softness at each reduced level, letting fine textures disappear while broad shapes and colors remain. Within every level, keep the original subject and composition.", "credit": "Image: Unknown author · Public domain (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Boston_Public_Library._Court_-_DPLA_-_14418fbd93fc9861130f58873cd70aca.jpg", "local": "gaussian-pyramid.webp", "title": "Gaussian Pyramid", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "generative-image-to-video": {"prompt": "Apply a Generative Image-to-Video look as a single cinematic frame suggesting emerging movement. Add slight directional blur to loose fabric, hair, foliage, or other movable details, with subtle depth separation and coherent lighting; avoid duplicated anatomy or invented camera angles. Keep the original subject and composition.", "credit": "Olivia Wall", "source": "https://commons.wikimedia.org/wiki/File:Interpolaci%C3%B3n_Generativa_Acotada.png", "local": "generative-image-to-video.webp", "title": "Interpolación Generativa Acotada", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "generative-inpainting": {"prompt": "Apply Generative Inpainting to small distracting background imperfections, replacing them with seamless continuations of nearby surfaces. Match local color, material texture, grain, perspective, shadow softness, and edge sharpness so repaired regions have no visible patch boundaries or repeated patterns. Keep the original subject and composition.", "credit": "Trougnouf with Stable Diffusion AI", "source": "https://commons.wikimedia.org/wiki/File:A_couple_of_face-painted_humans_happily_gazing_into_each_other%27s_eyes_-_crop_5_-_inpainted_(DSC03824).jpg", "local": "generative-inpainting.webp", "title": "A couple of face-painted humans happily gazing into each other's eyes - crop 5 - inpainted (DSC03824)", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "generative-outpainting": {"prompt": "Apply Generative Outpainting by extending the canvas modestly on every side, continuing the existing environment beyond its borders. Match perspective lines, material textures, color balance, grain, and lighting seamlessly; avoid mirrored repetitions or new focal subjects. Keep the original subject and composition intact within the expanded canvas.", "credit": "Elspea756", "source": "https://commons.wikimedia.org/wiki/File:Stable_Diffusion_outpainting_and_inpainting_step_4_of_4.png", "local": "generative-outpainting.webp", "title": "Stable Diffusion outpainting and inpainting step 4 of 4", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "glass-shot": {"prompt": "Apply the Glass Shot effect by rendering existing background areas as an expansive painted environment seamlessly aligned with the photographed foreground. Match perspective and illumination, adding subtle brushwork, atmospheric distance, slight glass softness, and barely perceptible joins between painted and real surfaces. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/glass-shot", "title": "Glass Shot · 本库原创图解", "previewKind": "原创技法示意", "local": "glass-shot.webp"},
  "go-motion": {"prompt": "Transform this image into a Go Motion miniature-effects frame, with tactile painted surfaces, practical studio lighting, and believable small-scale materials. Add short, directional shutter-blur streaks to parts suggesting movement while keeping stationary details crisp; avoid ghosted duplicate silhouettes. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/go-motion", "title": "Go Motion · 本库原创图解", "previewKind": "原创技法示意", "local": "go-motion.webp"},
  "gouraud-shading": {"prompt": "Apply a Gouraud Shading effect, rebuilding existing forms as low-polygon computer graphics with smoothly interpolated vertex colors. Use broad lighting gradients, muted diffuse surfaces, occasional triangular tonal transitions, and softened or missing small highlights; retain slightly angular silhouettes and a simple, clean background treatment. Keep the original subject and composition.", "credit": "Maarten Everts · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Gouraudshading00.png", "local": "gouraud-shading.webp", "title": "Gouraud Shading", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "grabcut-mask": {"prompt": "Apply GrabCut Mask as a foreground-separation preview, retaining the main subject's natural colors and texture while covering the background with a translucent dark overlay. Show a mostly hard selection boundary with slightly coarse treatment around hair, fine gaps, and ambiguous edges. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "grabcut-mask.webp", "title": "GrabCut Mask", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "gradient-map": {"prompt": "Apply a Gradient Map effect that remaps image brightness through deep violet shadows, magenta lower midtones, orange upper midtones, and pale yellow highlights. Make color follow tonal structure rather than object boundaries, maintaining smooth transitions, readable contrast, and original surface textures. Keep the original subject and composition.", "credit": "Nadar / Adam Cuerden (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Naser_al-Din_Shah_Qajar,_close_up,_with_slight_smile_by_Nadar.jpg", "local": "gradient-map.webp", "title": "Gradient Map, applied to “Naser al-Din Shah Qajar, close up, with slight smile by Nadar”", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "graduated-filter": {"prompt": "Apply a graduated filter effect, darkening the upper half with a restrained smoky amber tint that fades smoothly to clear across the middle. Preserve natural surface textures, crisp detail, and realistic highlights, with no visible dividing line or artificial vignette around the edges. Keep the original subject and composition.", "credit": "Esquilo · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Halftoned_filter.jpg", "local": "graduated-filter.webp", "title": "Graduated Filter", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "graph-segmentation": {"prompt": "Apply Graph Segmentation to group neighboring areas of similar appearance into irregular, connected regions of widely varying sizes. Use flattened local colors and fine contrasting boundary lines, retaining small distinctive patches while merging broad uniform surfaces. Avoid a regular grid or evenly sized cells. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "graph-segmentation.webp", "title": "Graph Segmentation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "grunge-typography": {"prompt": "Apply a grunge typography effect using distressed letter fragments, broken ink edges, uneven spacing, mixed character sizes, and overlapping text layers in peripheral areas. Add photocopier grain, paper stains, scratches, faded black ink, and occasional muted red accents without hiding defining features. Keep the original subject and composition.", "credit": "I don´t know · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Logo_bluesfestival_Luzern.jpg", "local": "grunge-typography.webp", "title": "Grunge Typography", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "gum-bichromate": {"prompt": "Apply a Gum Bichromate effect with matte, chalky pigments, coarse paper fibers, visible brushstrokes, and softly eroded photographic detail. Build earthy brown, charcoal, and muted ochre layers with uneven density, hand-worked highlights, painterly shadows, and irregular brushed borders rather than a glossy photographic surface. Keep the original subject and composition.", "credit": "Robert Demachy / The Metropolitan Museum of Art via Wikimedia Commons. Public domain / Commons.", "source": "https://www.metmuseum.org/art/collection/search/269329", "local": "gum-bichromate.webp", "title": "Gum Bichromate", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "halation": {"prompt": "Apply Halation around bright light sources and strongly backlit edges, creating narrow red-orange fringes with softly diffused outward glow. Concentrate the effect where intense highlights meet darker areas, retaining crisp detail elsewhere. Add restrained fine film grain and avoid uniform bloom across the entire frame. Keep the original subject and composition.", "credit": "Benh LIEU SONG (Flickr) (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Leg_Rowing_Fisherman_Inle_Lake_Myanmar.jpg", "local": "halation.webp", "title": "Halation, applied to “Leg Rowing Fisherman Inle Lake Myanmar”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "halftone-dot-screen": {"prompt": "Transform this image into a Halftone Dot Screen print with black circular dots on clean white paper. Arrange dot centers on a fixed, slightly rotated square grid, enlarging dots in shadows and shrinking them in highlights. Use crisp ink edges and no continuous gray. Keep the original subject and composition.", "credit": "Magica", "source": "https://commons.wikimedia.org/wiki/File:Halftone_screen.jpg", "local": "halftone-dot-screen.webp", "title": "Halftone screen", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "halftone": {"prompt": "Apply a Halftone effect, rebuilding tonal values from a clearly visible, regular grid of black ink dots on warm white paper. Vary dot sizes from tiny highlight specks to dense shadow clusters, adding slight ink spread and paper grain while retaining readable contours. Keep the original subject and composition.", "credit": "Daily Graphic; photographic source not securely named / Wikimedia Commons. Public domain; published 1880.", "source": "https://www.loc.gov/preservation/resources/rt/illbk/ibs2.html", "local": "halftone.webp", "title": "Halftone", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "hand-coloring": {"prompt": "Apply a historical Hand Coloring effect over a gray-brown monochrome print. Add delicate, selective watercolor-like washes of muted rose, pale blue, ochre, and green, with slight brush variation and occasional pigment pooling. Let photographic detail remain visible beneath translucent color and lightly textured paper. Keep the original subject and composition.", "credit": "Felice Beato; Japanese colorists unnamed / J. Paul Getty Museum. Getty Open Content; historical work in the public domain.", "source": "https://www.getty.edu/art/exhibitions/beato/index.html", "local": "hand-coloring.webp", "title": "Hand Coloring", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "harmonograph": {"prompt": "Transform this image into a Harmonograph drawing, rebuilding its recognizable shapes with fine continuous ink loops, nested oscillations, and gradually contracting spirals. Use repeated crossings to create dense shadow bands and airy open meshes for highlights, all on lightly textured ivory paper. Keep the original subject and composition.", "credit": "Exhibit made by Estes Objethos Atelier photo by Rodrigo Tetsuo Argenton · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Harmon%C3%B3grafo.jpg", "local": "harmonograph.webp", "title": "Harmonograph", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "harris-corner-detection": {"prompt": "Apply Harris Corner Detection as a technical overlay on the photograph, marking sharp junctions and two-direction brightness changes with tiny vivid red dots. Cluster markers around angular details and textured intersections, leaving smooth surfaces and simple uninterrupted edges mostly unmarked. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "harris-corner-detection.webp", "title": "Harris Corner Detection", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "hdr-imaging": {"prompt": "Apply an HDR imaging effect, recovering visible texture in bright highlights and deep shadows while maintaining luminous whites and grounded blacks. Enhance fine surface detail, cloud definition where present, and local tonal contrast with restrained saturation and minimal edge halos. Avoid uniformly flat lighting. Keep the original subject and composition.", "credit": "Cody Pope. CC BY-SA 2.5", "source": "https://commons.wikimedia.org/wiki/File:HDRToneMap.jpg", "local": "hdr-imaging.webp", "title": "HDR Imaging", "license": "CC BY-SA 2.5", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.5/"},
  "heliography": {"prompt": "Transform this image into a Heliography on a pewter plate, with extremely low contrast, smoky gray shapes, muted metallic shimmer, and uneven bitumen residue. Simulate grazing illumination that makes faint details emerge from the reflective surface, with softened edges and subdued highlights. Keep the original subject and composition.", "credit": "Joseph Nicéphore Niépce / Harry Ransom Center. Historical work in the public domain; digital recording by the Harry Ransom Center, source attribution retained.", "source": "https://www.hrc.utexas.edu/niepce-heliograph/", "local": "heliography.webp", "title": "Heliography", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "hexagonal-pixels": {"prompt": "Transform this image into a Hexagonal Pixels mosaic using a uniform honeycomb grid of flat-colored hexagonal cells. Sample each cell color from its corresponding image area, replace fine textures with solid fills, and render silhouettes as stepped hexagonal boundaries. Avoid gradients within cells; keep the original subject and composition.", "credit": "Image: Jez Timms jeztimms · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Eiffel_Tower,_Paris,_France_(Unsplash_ZHP6JNIXtfQ).jpg", "local": "hexagonal-pixels.webp", "title": "Hexagonal Pixels", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "histogram-equalization": {"prompt": "Apply Histogram Equalization to redistribute brightness across the entire image, expanding compressed tones into deeper blacks, brighter whites, and stronger midtone separation. Reveal previously muted textures with a distinctly global contrast shift, allowing some grain emphasis while retaining recognizable colors. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "histogram-equalization.webp", "title": "Histogram Equalization", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "hog-gradients": {"prompt": "Apply HOG Gradients with a regular grid of small square cells over a dimmed grayscale photograph. Fill each cell with thin, intersecting orientation strokes, forming starbursts whose brightness reflects local edge strength. Let these directional patterns collectively describe silhouettes and textured surfaces. Keep the original subject and composition.", "credit": "Image: POOYAN ESHTIAGHI pyeshtiaghi · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:VARZAHEH_desert_-_ISFAHAN_(Unsplash).jpg", "local": "hog-gradients.webp", "title": "HOG Gradients", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "hollywood-glamour-lighting": {"prompt": "Apply Hollywood Glamour Lighting with luminous monochrome skin tones, sculpted contours, and a high frontal key light producing a butterfly-shaped nose shadow where applicable. Add brilliant hair highlights, deep background shadows, delicate highlight diffusion, and fine photographic grain without erasing natural features. Keep the original subject and composition.", "credit": "George Hurrell · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Joan_Crawford_-_1936_-_Hurrell.JPG", "local": "hollywood-glamour-lighting.webp", "title": "Hollywood Glamour Lighting", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "holography": {"prompt": "Apply a Holography effect, making the image appear reconstructed in luminous depth within a dark, glossy plate. Use emerald and cyan light, fine interference shimmer, translucent contours, subtle spectral fringes, and layered depth cues that suggest viewpoint-dependent parallax rather than solid painted surfaces. Keep the original subject and composition.", "credit": "Tomasz Kawalec · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Transmission_hologram.jpg", "local": "holography.webp", "title": "Holography", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "hot-pixel-noise": {"prompt": "Apply Hot Pixel Noise, scattering sparse, sharply defined white, red, green, and blue pinpoints across the photograph. Make individual specks unnaturally bright and especially noticeable in dark regions, without halos, broad grain, or changes to overall exposure and texture. Keep the original subject and composition.", "credit": "Image: Angelina Litvin linalitvina · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Carver_at_work_(Unsplash).jpg", "local": "hot-pixel-noise.webp", "title": "Hot Pixel Noise", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "hough-circle-transform": {"prompt": "Apply Hough Circle Transform as a technical overlay on the original photograph. Trace detected circular features with thin, vivid green rings and tiny red center points, matching each circle's position and radius. Retain photographic colors and textures beneath the precise geometric annotations. Keep the original subject and composition.", "credit": "Image: Maxime Bhm maximebhm · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Artist_spray_painting_flowers_(Unsplash).jpg", "local": "hough-circle-transform.webp", "title": "Hough Circle Transform", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "hough-line-transform": {"prompt": "Apply a Hough Line Transform visualization over a slightly dimmed version of the photograph. Overlay thin, saturated red, cyan, and yellow straight segments aligned precisely with existing linear boundaries. Highlight dominant architectural or geometric directions without tracing curves or adding arbitrary lines. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "hough-line-transform.webp", "title": "Hough Line Transform", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "hsv-channel-split": {"prompt": "Transform this image into an HSV Channel Split visualization with three equal panels showing hue, saturation, and value separately. Render hue as a cyclic color map, saturation as grayscale intensity, and value as grayscale brightness, with crisp detail and no added texture. Keep the original subject and composition within each panel.", "credit": "Image: Julie Geiger · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:DeepInTheForest_cre8art4life_JulieGeiger.jpg", "local": "hsv-channel-split.webp", "title": "HSV Channel Split", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "hue-rotation": {"prompt": "Apply a Hue Rotation effect, shifting every hue by the same 120-degree angle around the color wheel. Create unexpected green, violet, and orange substitutions while retaining saturation, tonal structure, fine texture, and crisp edges; leave neutral grays neutral. Avoid spatial distortion. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "hue-rotation.webp", "title": "Hue Rotation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "hyperlapse": {"prompt": "Apply a Hyperlapse effect as a still-image impression of accelerated camera travel, keeping the main visual anchor stable while adding aligned peripheral motion streaks and faint stepped echoes of surrounding architecture. Combine directional perspective flow, compressed light trails, and crisp central detail. Keep the original subject and composition.", "credit": "Shohei Ohtaki / Motion Prompt · 本地取帧", "source": "https://showheyohtaki.github.io/motion-prompt/#171", "license": "MIT", "licenseUrl": "https://github.com/showheyohtaki/motion-prompt/blob/main/LICENSE", "title": "Hyperlapse · 动效分镜", "previewKind": "开源同类示例", "local": "hyperlapse.webp"},
  "image-based-lighting": {"prompt": "Apply Image-Based Lighting so the subject appears illuminated by its actual surroundings. Match directional highlights, broad soft shadows, colored environmental bounce, and reflections of visible scene elements. Differentiate glossy, rough, and matte materials through appropriate reflection sharpness, maintaining realistic exposure and grounded contact shadows. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/image-based-lighting", "title": "Image-Based Lighting · 本库原创图解", "previewKind": "原创技法示意", "local": "image-based-lighting.webp"},
  "image-morphing": {"prompt": "Apply an early digital image-morphing effect as a frozen intermediate frame, blending the subject with a gently reshaped version of itself. Show smoothly stretched contours, aligned landmarks, translucent doubled edges, and rubbery transitional surfaces, avoiding random smearing or unrelated added figures. Keep the original subject and composition.", "credit": "Edward Webb", "source": "https://commons.wikimedia.org/wiki/File:Morphing_madness.jpg", "local": "image-morphing.webp", "title": "Morphing madness", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/"},
  "image-prompt-adapter": {"prompt": "Apply an Image Prompt Adapter treatment, using the uploaded photograph as both appearance reference and structural guide. Harmonize its existing palette into cohesive colors, refine matching surface textures, and preserve contour placement, perspective, and lighting relationships. Produce a subtly restyled image without added panels or objects. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "image-prompt-adapter.webp", "title": "Image Prompt Adapter", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "image-to-image-diffusion": {"prompt": "Apply an Image-to-Image Diffusion treatment, gently resynthesizing the photograph into a polished illustrative version with coherent fine textures, softened tonal transitions, and subtly simplified surfaces. Retain the reference silhouettes, perspective, color relationships, and light direction; avoid new objects or substantial geometric changes. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "image-to-image-diffusion.webp", "title": "Image-to-Image Diffusion", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "indexed-color-palette": {"prompt": "Apply an Indexed Color Palette effect, limiting the entire photograph to sixteen adaptive colors drawn from the source. Create visibly stepped gradients, crisp color transitions, and fine ordered dithering where intermediate tones are needed, suggesting early computer graphics without oversized pixels. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "indexed-color-palette.webp", "title": "Indexed Color Palette", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "ink-bleed": {"prompt": "Apply an Ink Bleed effect with pigment spreading unevenly along visible paper fibers, feathered contours, soft capillary tendrils, and darker pools where strokes overlap. Use absorbent off-white paper, translucent color washes, and irregular drying edges while retaining readable forms. Keep the original subject and composition.", "credit": "Stilfehler", "source": "https://commons.wikimedia.org/wiki/File:Filters_-_Protrusions_-_Ink_Bleed.png", "local": "ink-bleed.webp", "title": "Filters - Protrusions - Ink Bleed", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "instagram-filters": {"prompt": "Apply an early 2010s vintage photo filter effect with faded charcoal blacks, warm amber midtones, slightly muted blues, darkened corners, and a thin pale border. Add delicate simulated grain and gently compressed highlights for an aged digital snapshot appearance. Keep the original subject and composition.", "credit": "sailko · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Instagram_versione_(santa_fiora,_peschiera).jpg", "local": "instagram-filters.webp", "title": "Instagram Filters", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "instance-segmentation": {"prompt": "Apply an Instance Segmentation effect, covering each separate visible object with its own translucent, brightly colored mask and matching crisp outline. Give different objects distinct colors even when they belong to the same category, retaining faint photographic detail beneath the overlays. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "instance-segmentation.webp", "title": "Instance Segmentation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "interlacing": {"prompt": "Apply an Interlacing effect using fine alternating horizontal scan lines and slightly offset image fields. Add comb-like teeth along moving-looking contours, narrow horizontal edge breaks, mild color bleeding, and restrained analog video noise, leaving stationary areas relatively coherent. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/interlacing", "title": "Interlacing · 本库原创图解", "previewKind": "原创技法示意", "local": "interlacing.webp"},
  "iris-shot": {"prompt": "Apply the Iris Shot effect using a sharply defined circular viewing aperture surrounded by opaque black masking. Center the opening on the existing focal subject, leaving its important features visible while obscuring outer corners. Add subtle monochrome film grain and a slightly softened aperture rim. Keep the original subject and composition.", "credit": "Diego Delso (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Esponja_(Scalarispongia_scalaris),_%C4%8Airkewwa,_Malta,_Malta,_2021-08-24,_DD_31.jpg", "local": "iris-shot.webp", "title": "Iris Shot, applied to “Esponja (Scalarispongia scalaris), Ċirkewwa, Malta, Malta, 2021-08-24, DD 31”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "isometric-pixel-graphics": {"prompt": "Transform this image into Isometric Pixel Graphics with parallel diagonal axes, no vanishing points, and consistent object scale regardless of depth. Build recognizable forms using crisp stair-stepped pixel edges, diamond-shaped surface grids, limited colors, and compact stepped shadows, retaining the existing arrangement. Keep the original subject and composition.", "credit": "Age of Empires · CC BY 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:AoE_II_DE,_isometrische_Perspektive_Dorf_20210126_03.png", "local": "isometric-pixel-graphics.webp", "title": "Isometric Pixel Graphics", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/"},
  "jpeg-compression-artifacts": {"prompt": "Apply a JPEG Compression Artifacts effect with visible square block boundaries, smeared fine textures, and stepped tonal transitions. Add ringing halos and mosquito-like speckles around sharp edges, plus coarse color blotches in detailed regions. Preserve recognizable forms beneath the degraded digital surface; keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "jpeg-compression-artifacts.webp", "title": "JPEG Compression Artifacts", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "jpeg-glitch": {"prompt": "Apply a JPEG Glitch effect with visible compression blocks, displaced horizontal image strips, abrupt chroma shifts, and smeared color boundaries. Add ringing around high-contrast edges and scattered mosaic-like corruption, balancing damaged regions with recognizable photographic detail rather than uniform noise. Keep the original subject and composition.", "credit": "Own work, based on respective photographs' authors Geoprofi Lars and Gyula Péter. Note that the latter's photograph is n", "source": "https://commons.wikimedia.org/wiki/File:London_Eye_-_bitblent_glitch_art.jpeg", "local": "jpeg-glitch.webp", "title": "London Eye - bitblent glitch art", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "jump-cut": {"prompt": "Apply a Jump Cut effect represented within a single still through sharply interrupted, slightly displaced fragments of the existing subject. Keep the background registered, use abrupt hard-edged discontinuities rather than smooth motion blur, and add restrained film grain to suggest missing moments in a continuous shot. Keep the original subject and composition.", "credit": "Shohei Ohtaki / Motion Prompt · 本地取帧", "source": "https://showheyohtaki.github.io/motion-prompt/#041", "license": "MIT", "licenseUrl": "https://github.com/showheyohtaki/motion-prompt/blob/main/LICENSE", "title": "Jump Cut · 动效分镜", "previewKind": "开源同类示例", "local": "jump-cut.webp"},
  "k-means-color-quantization": {"prompt": "Apply a K-Means Color Quantization effect, reducing the photograph to six representative colors sampled from its existing palette. Replace similar colors with identical flat fills, producing abrupt tonal steps and simplified surface detail while retaining irregular source contours. Avoid dithering and added outlines. Keep the original subject and composition.", "credit": "Not specified in SIPI Image Database", "source": "https://commons.wikimedia.org/wiki/File:Mandrill-k-means.png", "local": "k-means-color-quantization.webp", "title": "Mandrill-k-means", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "kaleidoscope-mirror": {"prompt": "Apply Kaleidoscope Mirror as a restrained optical overlay, repeating reflected angular fragments of the photograph into a radial rosette. Use crisp triangular seams, symmetrical color repetitions, and mirrored texture details, concentrating the pattern around rather than replacing the recognizable central subject. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "kaleidoscope-mirror.webp", "title": "Kaleidoscope Mirror", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "kaleidoscope": {"prompt": "Apply a Kaleidoscope effect using mirrored triangular segments, radial symmetry, repeated color fragments, and crisp reflective seams. Anchor the original subject centrally while multiplying surrounding details into concentric geometric patterns, with jewel-like highlights and alternating light and dark wedges. Keep the original subject recognizable and preserve the underlying composition.", "credit": "Albarubescens", "source": "https://commons.wikimedia.org/wiki/File:Rotational_symmetries_in_designs_produced_by_a_kaleidoscopeDSCN2440.jpg", "local": "kaleidoscope.webp", "title": "Rotational symmetries in designs produced by a kaleidoscopeDSCN2440", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "kinemacolor": {"prompt": "Apply a Two-Color Additive Cinema effect with restricted orange-red and green hues, weak blues, warm skin tones, and slightly muddy neutral areas. Add displaced red and green fringes along moving contours, soft projection contrast, fine film grain, and gentle exposure unevenness. Keep the original subject and composition.", "credit": "Natural Color Kinematograph Company, Prod. by Charles Urban (1867 - 1942) · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:1911_George_V_Kinemacolor.png", "local": "kinemacolor.webp", "title": "Kinemacolor", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "kinetic-typography": {"prompt": "Apply a Kinetic Typography treatment using existing text or small descriptive words as bold cutout letterforms. Suggest movement through stepped position echoes, changing letter scales, angled baselines, and crisp directional trails. Use a restrained midcentury palette and place lettering around essential visual details. Keep the original subject and composition.", "credit": "Simonsegni (Stefano Simonetti) · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Il_segno_animato_(fotogrammi_selezionati,_1999).jpg", "local": "kinetic-typography.webp", "title": "Kinetic Typography", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "kirlian-photography": {"prompt": "Apply a Kirlian Photography effect with a dark field and a jagged electric corona hugging the subject silhouette. Add branching violet and cyan sparks, fine white discharge filaments, scattered luminous points, and high-contrast surface detail with minimal ambient illumination. Keep the original subject and composition.", "credit": "Sérgio Valle Duarte .mw-parser-output .messagebox{margin:4px 0;width:auto;border-collap… · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:A_Kirlian_Photography,_female_1989.jpg", "local": "kirlian-photography.webp", "title": "Kirlian Photography", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "kirsch-compass-edges": {"prompt": "Transform this image into a Kirsch Compass Edges map with a nearly black background and bright white, pixel-sharp directional contours. Emphasize the strongest boundary response at each location, revealing angular silhouettes and textured edge fragments while removing continuous surface shading. Keep the original subject and composition.", "credit": "Image: Oshomah Abubakar oshomah · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Child_At_The_Ceremony_(Unsplash).jpg", "local": "kirsch-compass-edges.webp", "title": "Kirsch Compass Edges", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "kodachrome-color": {"prompt": "Apply a vintage three-layer color transparency effect with rich reds, brilliant yellows, deep blues, warm natural skin tones, and strongly defined shadows. Add fine film grain, dense blacks, crisp edges, and clean sunlit highlights without faded colors or heavy bloom. Keep the original subject and composition.", "credit": "Arthur Rothstein · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Guide_at_Little_Norway,_Blue_Mounds,_Wis._LCCN2017878934.jpg", "local": "kodachrome-color.webp", "title": "Kodachrome Color", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "kuwahara-filter": {"prompt": "Apply a Kuwahara Filter effect, replacing fine photographic texture with irregular, flat blocks of averaged color. Create a painterly mosaic of smooth patches with angular transitions, simplified shading, and clearly retained object boundaries. Reduce grain while preserving prominent contours and recognizable facial features. Keep the original subject and composition.", "credit": "Image: Patrick Hendry worldsbetweenlines · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Snow_mountain_background_photo_(Unsplash).jpg", "local": "kuwahara-filter.webp", "title": "Kuwahara Filter", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "l-system-plants": {"prompt": "Apply an L-System Plants effect, reconstructing visible forms from slender stems that repeatedly divide at consistent angles. Build nested leaf sprays, self-similar branching tiers, tapered brown twigs, and varied green foliage, using soft daylight and small overlapping shadows while preserving recognizable silhouettes. Keep the original subject and composition.", "credit": "Unknown author · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Fractal_tree_(Plate_b_-_2).jpg", "local": "l-system-plants.webp", "title": "L-System Plants", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "lab-opponent-channels": {"prompt": "Apply a Lab Opponent Channels effect using three equal panels: grayscale lightness, a green-to-red opponent map, and a blue-to-yellow opponent map. Make neutral colors appear midway along each opponent scale, revealing subtle chromatic differences without grain or distortion. Keep the original subject and composition within each panel.", "credit": "Image: Vicky Gu vickygu · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Vicky_Gu_2016_(Unsplash).jpg", "local": "lab-opponent-channels.webp", "title": "Lab Opponent Channels", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "lantern-slide": {"prompt": "Transform this image into a Lantern Slide with a luminous photographic positive on transparent glass, delicate hand-painted crimson, amber, and blue washes, and deep translucent shadows. Add a narrow dark slide border, tiny glass dust specks, and gentle projected-light falloff. Keep the original subject and composition.", "credit": "Unknown authorUnknown author · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:%22Lucea_and_Dolphin_Head,_Jamaica%22,_early_20th_century_(imp-cswc-GB-237-CSWC47-LS12-020).jpg", "local": "lantern-slide.webp", "title": "Lantern Slide", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "laplacian-edge": {"prompt": "Apply Laplacian Edges, creating a signed grayscale relief of local brightness changes around a neutral gray base. Outline boundaries with adjacent light and dark bands, emphasizing fine texture, sharp transitions, and slight noise. Remove original color and broad photographic shading. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "laplacian-edge.webp", "title": "Laplacian Edges", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "laplacian-of-gaussian": {"prompt": "Apply Laplacian of Gaussian, smoothing fine noise before rendering structural boundaries as controlled light-dark paired contours against neutral gray. Emphasize clean curves and major transitions, with softly rounded edge profiles and minimal speckling. Suppress tiny surface texture while retaining recognizable forms. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "laplacian-of-gaussian.webp", "title": "Laplacian of Gaussian", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "latent-space-interpolation": {"prompt": "Apply a Latent Space Interpolation preview effect, blending the photograph with a softly stylized version of the same scene at equal strength. Show translucent doubled contours, mixed surface textures, and smoothly averaged colors, resembling a pixel crossfade rather than a fully reconstructed transformation. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "latent-space-interpolation.webp", "title": "Latent Space Interpolation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "latent-space": {"prompt": "Apply a Latent-Space Morphing effect as a single surreal intermediate frame, blending existing surfaces into related organic or architectural forms. Use continuous contours, hybrid textures, and smoothly changing materials rather than transparent crossfades, keeping defining features recognizable throughout the transformation. Keep the original subject and composition.", "credit": "Kaiwen Zhang, Yifan Zhou, Xudong Xu, Xingang Pan & Bo Dai. Source illustration of the authors; Project page CC BY-SA 4.0", "source": "https://kevin-thu.github.io/DiffMorpher_page/", "local": "latent-space.webp", "title": "Latent-Space Morphing", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "lcd-subpixel-view": {"prompt": "Apply LCD Subpixel View, rebuilding the photograph as a regular matrix of narrow vertical red, green, and blue strips separated by dark gaps. Vary each strip's brightness according to its corresponding image color channel, producing a crisp enlarged display texture. Keep the original subject and composition.", "credit": "Image: Jakub Gorajek cinegeek · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Milky_Way_Glacier_Point_(Unsplash).jpg", "local": "lcd-subpixel-view.webp", "title": "LCD Subpixel View", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "led-volume": {"prompt": "Apply an LED Volume cinematic look with a realistic immersive backdrop, colored environmental light wrapping around the subject, and reflections matching nearby scenery. Balance foreground exposure with luminous background detail, adding subtle screen softness in distant areas without visible display borders. Keep the original subject and composition.", "credit": "Tim Sheerman-Chase · CC BY 2.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:University_of_Portsmouth_CCIXR_2_Virtual_Production_and_Mixed_Reality_Studio.jpg", "local": "led-volume.webp", "title": "LED Volume", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "lenticular-print": {"prompt": "Apply a Lenticular Print effect with fine vertical lens ridges, glossy plastic reflections, interlaced image strips, and restrained lateral ghosting along depth boundaries. Suggest alternating viewpoints through slightly offset peripheral contours and layered spatial separation while keeping the central image legible. Keep the original subject and composition.", "credit": "EgorovaSvetlana", "source": "https://commons.wikimedia.org/wiki/File:%D0%91%D1%80%D0%B0%D0%B2%D1%8B%D0%B9_%D1%81%D0%BE%D0%BB%D0%B4%D0%B0%D1%82_%D0%A8%D0%B2%D0%B5%D0%B9%D0%BA_%D0%B7%D0%BD%D0%B0%D1%87%D0%BE%D0%BA_%D0%BF%D0%B5%D1%80%D0%B5%D0%BB%D0%B8%D0%B2%D0%BD%D0%BE%D0%B9_%D1%81%D1%82%D0%B5%D1%80%D0%B5%D0%BE.jpg", "local": "lenticular-print.webp", "title": "Бравый солдат Швейк значок переливной стерео", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "levels-stretch": {"prompt": "Apply a Levels Stretch effect, expanding the tonal range so the darkest existing shadows reach pure black and the brightest highlights reach pure white. Scale intermediate tones smoothly, strengthening contrast without adding grain, halos, artificial textures, or new lighting. Keep the original subject and composition.", "credit": "Image: Nathan Dumlao nate_dumlao · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Coffee_art_and_iphone_(Unsplash).jpg", "local": "levels-stretch.webp", "title": "Levels Stretch", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "light-field-refocus": {"prompt": "Apply a Light Field Refocus effect by placing crisp focus on the main subject's depth plane while progressively softening nearer and farther details. Use smooth optical blur, rounded highlight discs, and clean depth boundaries without uniform haze or cutout halos. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/light-field-refocus", "title": "Light Field Refocus · 本库原创图解", "previewKind": "原创技法示意", "local": "light-field-refocus.webp"},
  "light-leaks": {"prompt": "Apply a Light Leaks effect with irregular translucent red, orange, and pale yellow veils entering from the image edges. Include softly feathered streaks, locally washed-out contrast, and occasional overexposed borders, blending the accidental exposure into fine film grain without masking key features. Keep the original subject and composition.", "credit": "simpleinsomnia", "source": "https://commons.wikimedia.org/wiki/File:Sailboats_in_the_ocean_with_light_leaks_(12418268115).jpg", "local": "light-leaks.webp", "title": "Sailboats in the ocean with light leaks (12418268115)", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "light-painting": {"prompt": "Apply a Light Painting effect with flowing luminous trails drawn around the subject, warm white ribbons, amber loops, and occasional cool blue streaks. Darken ambient light, add soft glow and reflected highlights, and retain crisp details beneath the long-exposure traces. Keep the original subject and composition.", "credit": "Gnangarra / CC BY 2.5 au; Wikimedia Commons", "source": "https://www.museoreinasofia.es/en/collections/artwork/space-writing/", "local": "light-painting.webp", "title": "Light Painting", "license": "CC BY 2.5 AU", "licenseUrl": "https://creativecommons.org/licenses/by/2.5/au/"},
  "light-trails": {"prompt": "Apply a Light Trails effect, stretching moving or implied moving lights into continuous luminous paths with bright cores, colored halos, and smooth directional curves. Use long-exposure lighting, restrained highlight bloom, and crisp stationary details, keeping trails away from essential subject features. Keep the original subject and composition.", "credit": "Dietmar Rabich", "source": "https://commons.wikimedia.org/wiki/File:Lissajous-Figur_--_2020_--_7766.jpg", "local": "light-trails.webp", "title": "Lissajous-Figur -- 2020 -- 7766", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "limited-animation": {"prompt": "Transform this image into Limited Animation with flat stylized shapes, bold clean outlines, simplified anatomy, and broad blocks of muted color. Use a static painted-background appearance, held-pose stiffness, and subtle cel-layer boundaries around articulated details, minimizing gradients and realistic surface texture. Keep the original subject and composition.", "credit": "Chuck Jones · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Dover_boys_triple_knockout.png", "local": "limited-animation.webp", "title": "Limited Animation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "linear-motion-blur": {"prompt": "Apply Linear Motion Blur, smearing image details along one consistent diagonal direction. Stretch highlights into parallel streaks and soften contours into continuous directional trails, with no circular movement or repeated hard-edged copies. Retain the underlying colors, exposure, and recognizable silhouettes. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "linear-motion-blur.webp", "title": "Linear Motion Blur", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "lineart-control": {"prompt": "Transform this image into a Line Art Control drawing, rendering recognizable silhouettes and important interior features as smooth, clean black ink contours on pure white. Use restrained line-weight variation, precise edges, and simplified details, removing photographic textures, gradients, shadows, and filled color areas. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "lineart-control.webp", "title": "Line Art Control", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "lippmann-interference-photography": {"prompt": "Apply a Lippmann Interference Photography effect, rendering fine photographic detail as luminous structural color on a reflective glass plate. Suggest angle-dependent hues through subtle color shifts across the surface, selective spectral brilliance, dark reflective undertones, and subdued colors outside the viewing sweet spot. Keep the original subject and composition.", "credit": "Dr. Richard Neuhauss (1855-1915) / Public domain; Wikimedia Commons", "source": "https://www.nobelprize.org/prizes/physics/1908/lippmann/facts/", "local": "lippmann-interference-photography.webp", "title": "Lippmann Interference Photography", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "liquid-glass-interface": {"prompt": "Apply a Liquid Glass Interface effect with floating, rounded translucent controls over the photograph. Simulate thick curved glass through blurred backgrounds, localized refraction, luminous rim highlights, subtle shadows, and softly tinted transparency. Vary curvature and apparent thickness between controls. Keep the original subject and composition.", "credit": "EvanTech10 · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:IOS_App_8.0.0_Article.png", "local": "liquid-glass-interface.webp", "title": "Liquid Glass Interface", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "liquid-light-show": {"prompt": "Apply a Liquid Light Show overlay with translucent islands of saturated magenta, amber, cyan, and violet. Create oily bubbles, flowing cellular boundaries, thin interference rims, and overlapping dye pools that cast luminous projected color across existing surfaces without fully obscuring their details. Keep the original subject and composition.", "credit": "_TheNightWatch_", "source": "https://commons.wikimedia.org/wiki/File:Liquid_light_show_(3625585961).jpg", "local": "liquid-light-show.webp", "title": "Liquid light show (3625585961)", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "liquify-brush": {"prompt": "Apply Liquify Brush, gently pushing a limited image region sideways into a smooth fluid deformation. Stretch nearby contours and textures along the stroke, with displacement fading gradually into untouched surroundings. Avoid global warping, hard seams, added blur, or altered lighting. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "liquify-brush.webp", "title": "Liquify Brush", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "liquify": {"prompt": "Apply a liquify effect with localized pushed contours, gently inflated forms, pinched details, and small swirling distortions. Stretch surrounding textures continuously along each deformation, maintaining smooth color transitions and coherent surface detail without pixel fragmentation. Keep defining features recognizable and leave the overall framing unchanged. Keep the original subject and composition.", "credit": "RaiyaniM (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Manene_Tradisi_Ganti_Baju_Mayat_di_Tana_Toraja.jpg", "local": "liquify.webp", "title": "Liquify, applied to “Manene Tradisi Ganti Baju Mayat di Tana Toraja”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "lith-printing": {"prompt": "Apply a Lith Printing effect with warm peach, dusty pink, and creamy highlights contrasting against deep brown-black shadows. Render light areas smooth and delicate, but fill darker regions with irregular peppery grain and gritty, rapidly building tonal density. Preserve photographic surface detail. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/lith-printing", "title": "Lith Printing · 本库原创图解", "previewKind": "原创技法示意", "local": "lith-printing.webp"},
  "lithophane": {"prompt": "Transform this image into a Lithophane, a thin ivory porcelain relief illuminated from behind. Make thin areas glow creamy white and thicker areas form soft gray-brown shadows, with continuous unpainted tonal modeling, delicate raised contours, and a subtly translucent ceramic surface. Keep the original subject and composition.", "credit": "Detlef Dauer · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Lithophanie_%E2%80%93_St%C3%B6vchen,_Messing,_D2162.jpg", "local": "lithophane.webp", "title": "Lithophane", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "local-binary-pattern": {"prompt": "Apply Local Binary Pattern, replacing photographic shading with dense grayscale texture codes formed by tiny neighboring-pixel comparisons. Create an embossed, granular mosaic of micro-patterns, emphasizing pores, fabric, and surface transitions while flattening broad illumination. Avoid realistic relief lighting or smooth tonal modeling. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "local-binary-pattern.webp", "title": "Local Binary Pattern", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "lomography": {"prompt": "Apply an Experimental Toy-Camera effect with vivid oversaturated colors, strong corner vignetting, uneven exposure, soft peripheral focus, and subtle chromatic fringes. Add fine analog grain and small accidental light flares for a spontaneous, imperfect snapshot appearance, keeping central details recognizable. Keep the original subject and composition.", "credit": "Sgroey / CC BY-SA 4.0; Wikimedia Commons", "source": "https://www.lomography.com/about/history", "local": "lomography.webp", "title": "Lomography", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "long-exposure-water": {"prompt": "Apply a Long Exposure Water effect to visible water, blending ripples and splashes into smooth, milky ribbons and mistlike pools. Retain gentle directional flow, subdued reflections, and luminous pale highlights while keeping stationary rocks, vegetation, architecture, and other solid forms sharply resolved. Keep the original subject and composition.", "credit": "Basile Morin · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Tad_Hang_waterfalls_at_sunset,_Tad_Lo_village,_Bolaven_Plateau,_Laos.jpg", "local": "long-exposure-water.webp", "title": "Long Exposure Water", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "lora-style-adapter": {"prompt": "Apply a LoRA Style Adapter effect at moderate strength, giving the photograph a consistent watercolor-like finish with translucent color washes, fine paper grain, softly pooled pigment, and selective crisp contours. Let original photographic detail remain visible beneath the treatment, without adding interface graphics or text. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/lora-style-adapter", "title": "LoRA Style Adapter · 本库原创图解", "previewKind": "原创技法示意", "local": "lora-style-adapter.webp"},
  "low-poly": {"prompt": "Transform this image into a Low Poly rendering built entirely from flat, interlocking polygonal facets, predominantly triangles. Replace smooth curves with angular silhouettes and convert shading into discrete color planes, using larger facets in simple areas and smaller facets around defining features. Keep the original subject and composition.", "credit": "KenClarck11 · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Joe_low_poly.png", "local": "low-poly.webp", "title": "Low Poly", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "luminance": {"prompt": "Apply a Luminance Grayscale effect, replacing all colors with neutral black, white, and gray according to perceptual brightness. Retain luminous yellows and greens, darker blues, smooth tonal transitions, natural surface texture, and existing light direction. Avoid tinting, added grain, or exaggerated contrast. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "luminance.webp", "title": "Luminance Grayscale", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "m-lsd": {"prompt": "Transform this image into an M-LSD Structural Lines visualization, emphasizing long, straight segments along existing architectural edges, furniture, and other linear forms. Draw thin white segments on a darkened photographic base, omit curved contours and fine textures, and retain clean endpoints and intersections. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "m-lsd.webp", "title": "M-LSD Structural Lines", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "magnetic-crt-distortion": {"prompt": "Apply Magnetic CRT Distortion with bending scanlines, localized luminous waves, and warped contours that curl around invisible magnetic centers. Add green-magenta color separation, uneven phosphor brightness, soft screen glow, and dark gaps between raster lines, keeping distortion restrained around identifying features. Keep the original subject and composition.", "credit": "William Crookes", "source": "https://commons.wikimedia.org/wiki/File:Crookes_magnetic_deflection_tube.png", "local": "magnetic-crt-distortion.webp", "title": "Crookes magnetic deflection tube", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "mandelbrot-set": {"prompt": "Apply a Mandelbrot set treatment, mapping intricate escape-time patterns across existing forms. Use black cardioid-and-disk motifs, miniature repeating copies, branching filaments, tightly curled boundary spirals, and vivid nested color bands in cobalt, magenta, and gold, concentrating detail along recognizable silhouettes. Keep the original subject and composition.", "credit": "PantheraLeo1359531 · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Mandelbrot-Menge_mit_Regenbogenfarben_20201028.png", "local": "mandelbrot-set.webp", "title": "Mandelbrot Set", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "masked-generation": {"prompt": "Apply Masked Generation to one small background region, replacing its texture with a plausible continuation of adjacent surroundings. Match perspective, material grain, color, shadows, and edge softness, with an invisible transition at the mask boundary. Leave all unmasked pixels and the main subject untouched. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "masked-generation.webp", "title": "Masked Generation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "match-cut": {"prompt": "Apply a Match Cut effect as a single-frame transition composite, matching an existing prominent silhouette to a secondary analogous shape at exactly the same scale and position. Use a crisp localized splice, contrasting surface textures, and seamless contour alignment rather than diffuse double exposure. Keep the original subject and composition.", "credit": "Shohei Ohtaki / Motion Prompt · 本地取帧", "source": "https://showheyohtaki.github.io/motion-prompt/#042", "license": "MIT", "licenseUrl": "https://github.com/showheyohtaki/motion-prompt/blob/main/LICENSE", "title": "Match Cut · 动效分镜", "previewKind": "开源同类示例", "local": "match-cut.webp"},
  "matrix-digital-rain": {"prompt": "Apply a green digital rain effect with vertical columns of luminous glyphs against deep black, white-green leading characters, and progressively dimmer emerald trails. Vary column lengths, symbol density, and subtle downward smearing, allowing the subject to remain recognizable through the cascading screen-like texture. Keep the original subject and composition.", "credit": "Tassilo Mödl · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Cmatrix.png", "local": "matrix-digital-rain.webp", "title": "Matrix Digital Rain", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "mean-shift-segmentation": {"prompt": "Apply a Mean Shift Segmentation effect, merging neighboring areas of similar color into distinct, nearly uniform patches. Preserve major color relationships and recognizable silhouettes while flattening fine texture, reducing grain, and simplifying shading into broad regions with clean, slightly organic boundaries. Keep the original subject and composition.", "credit": "Image: Ryan Hafey ryanhafey · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Derelict_train_carriage_(Unsplash).jpg", "local": "mean-shift-segmentation.webp", "title": "Mean Shift Segmentation", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "median-filter": {"prompt": "Apply Median Filter to remove isolated bright and dark specks while smoothing tiny texture variations. Give fine details a slightly simplified, flattened appearance, but keep major boundaries relatively firm and colors faithful. Avoid luminous halos, directional smearing, and excessive loss of recognizable features. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "median-filter.webp", "title": "Median Filter", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "mezzotint": {"prompt": "Apply a Mezzotint effect using dense, irregular black stippling on warm white paper. Build velvety shadows from clustered ink-like dots, soften midtones through progressively scattered grain, and reveal pale highlights with sparse marks. Retain smooth tonal transitions without continuous gray fills; keep the original subject and composition.", "credit": "Image: Jairo Alzate jairoalzate · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Bocachico_(Unsplash).jpg", "local": "mezzotint.webp", "title": "Mezzotint", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "miniature-effects": {"prompt": "Transform this image into a Miniature Effects shot, recreating its forms as carefully painted scale models photographed to appear life-size. Add subtle plaster, wood, and flocked surface textures, tiny construction seams, convincing directional shadows, and deep focus rather than toy-like blur. Keep the original subject and composition.", "credit": "Laika ac from USA", "source": "https://commons.wikimedia.org/wiki/File:Laika_ac_Hideaki_Anno%27s_%22TOKUSATSU%22_Special_Effects_Museum_(7898482150).jpg", "local": "miniature-effects.webp", "title": "Laika ac Hideaki Anno's \"TOKUSATSU\" Special Effects Museum (7898482150)", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/"},
  "miniature-faking": {"prompt": "Apply a miniature faking effect with a narrow, sharply focused band across the main subject and progressively stronger blur toward the foreground and background. Increase color vibrancy, tidy fine textures, and introduce gently toy-like surface clarity and bright model-display lighting without changing the viewpoint. Keep the original subject and composition.", "credit": "High Contrast", "source": "https://commons.wikimedia.org/wiki/File:Miniature_faking_-_agricultural_vehicle.JPG", "local": "miniature-faking.webp", "title": "Miniature faking - agricultural vehicle", "license": "CC BY 3.0 DE", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/de/"},
  "mirror-repeat": {"prompt": "Apply a mirror repeat effect in secondary background areas, arranging reduced image fragments into a precise grid with alternating horizontal and vertical reflections. Create crisp tile seams, symmetrical edge junctions, and rhythmic repeated colors while leaving the main subject unduplicated and unobscured. Keep the original subject and composition.", "credit": "Agnes Monkelbaan (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Kop-hals-rompboerderij_(Tjepma_state)_Overijsselsestraatweg_22,_Reduzum._23-03-2026._(actm.)_03.jpg", "local": "mirror-repeat.webp", "title": "Mirror Repeat, applied to “Kop-hals-rompboerderij (Tjepma state) Overijsselsestraatweg 22, Reduzum. 23-03-2”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "mirror-tiling": {"prompt": "Apply Mirror Tiling as a subtle geometric overlay, arranging reflected rectangular fragments in a regular grid with alternating horizontal and vertical flips. Create crisp shared boundaries and symmetrical texture repetitions, emphasizing background regions while leaving the principal subject clearly readable. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "mirror-tiling.webp", "title": "Mirror Tiling", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "mobius-transformation": {"prompt": "Apply Möbius Transformation to bend the photograph into sweeping circular arcs, placing enlarged regions beside tightly compressed details. Keep local intersections and fine textures coherent as scale changes smoothly across the image. Avoid rubbery folds, hard seams, and added objects. Preserve the original subject and composition within the transformed image.", "credit": "Image: Brina Blum brina_blum · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Mainz,_Germany_(Unsplash_sMHhx5m3MbM).jpg", "local": "mobius-transformation.webp", "title": "Möbius Transformation", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "mode-7": {"prompt": "Apply a Mode 7 effect, rendering the existing ground or lower background as a flat pixelated texture plane stretching toward the horizon. Enlarge foreground texels, tightly compress distant rows, and use a limited palette with crisp sprite-like subjects rather than detailed geometry. Keep the original subject and composition.", "credit": "Anomie · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Mode_7_Test-0000.png", "local": "mode-7.webp", "title": "Mode 7", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "moire-pattern": {"prompt": "Apply a Moiré Pattern effect with broad interference waves and rippling color bands emerging over fine repeating textures. Overlay closely spaced grids at slightly different angles, producing alternating dark and light beats with subtle rainbow aliasing, while keeping unpatterned areas relatively clean. Keep the original subject and composition.", "credit": "Brocken Inaglory", "source": "https://commons.wikimedia.org/wiki/File:Moir%C3%A9_fringes_IMG_3712.jpg", "local": "moire-pattern.webp", "title": "Moiré fringes IMG 3712", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "monocular-depth-map": {"prompt": "Transform this image into a Monocular Depth Map, replacing natural colors with smooth grayscale distance fields. Render nearer surfaces lighter and farther surfaces darker, using coherent object silhouettes, gradual tonal changes across receding planes, and crisp depth discontinuities at overlaps rather than lighting shadows. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "monocular-depth-map.webp", "title": "Monocular Depth Map", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "mordancage": {"prompt": "Apply a Mordançage effect with monochrome photographic tones and deep shadow regions lifting into delicate, wrinkled gelatin veils. Introduce curled emulsion edges, fluid distortions, pale bleached patches, and torn-looking pockets of texture concentrated in darker areas, while retaining readable highlights and essential contours. Keep the original subject and composition.", "credit": "stacey svendsen from a little bit of everywhere · CC BY 2.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Self_portrait_(8618889472).jpg", "local": "mordancage.webp", "title": "Mordançage", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "morphological-closing": {"prompt": "Apply Morphological Closing to fill tiny dark holes and narrow shadow-colored gaps within brighter regions. Connect closely spaced light fragments and smooth small inward notches along their boundaries. Keep larger dark areas and broad color relationships intact without creating glow or general blur. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "morphological-closing.webp", "title": "Morphological Closing", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "morphological-gradient": {"prompt": "Apply a Morphological Gradient effect, turning local brightness differences into luminous edge bands against nearly black, uniform regions. Trace object boundaries and fine textures with consistent-width white or pale gray outlines, emphasizing both sides of contrast transitions without directional embossed shading. Suppress broad surface color. Keep the original subject and composition.", "credit": "Image: Dustin Scarpitti dusty_blanco · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Dusk_on_beach_shore_(Unsplash).jpg", "local": "morphological-gradient.webp", "title": "Morphological Gradient", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "morphological-opening": {"prompt": "Apply Morphological Opening to remove tiny bright flecks, narrow luminous protrusions, and isolated light specks. Slightly simplify the outlines of bright regions while leaving larger light masses intact. Keep dark surroundings, existing colors, and broad lighting relationships stable without general blur. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "morphological-opening.webp", "title": "Morphological Opening", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "motion-blur": {"prompt": "Apply Motion Blur with continuous directional streaks following the scene's implied movement. Stretch highlights into luminous trails, soften moving contours, and retain sharper stationary surfaces to establish contrast. Use translucent smearing rather than discrete repeated copies, with realistic exposure blending and preserved color relationships. Keep the original subject and composition.", "credit": "Radomianin / CC BY-SA 4.0; Wikimedia Commons", "source": "https://www.moma.org/artists/16790-anton-giulio-bragaglia", "local": "motion-blur.webp", "title": "Motion Blur", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "motion-capture": {"prompt": "Apply a motion capture visualization effect, rendering the subject as a smooth shaded digital double with small luminous tracking markers at visible articulation points and thin skeletal rig connections. Preserve natural posture, silhouette, and subtle asymmetries, with restrained wireframe accents and cool studio lighting. Keep the original subject and composition.", "credit": "Mbrickn", "source": "https://commons.wikimedia.org/wiki/File:2010_Motion_Capture_Suit.jpg", "local": "motion-capture.webp", "title": "2010 Motion Capture Suit", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "motion-control-photography": {"prompt": "Apply a Motion-Control Photography aesthetic, giving existing forms the tangible finish of carefully lit miniatures combined through precisely registered exposure passes. Use crisp model details, layered depth, luminous practical highlights, restrained directional motion blur, fine film grain, and subtle optical matte traces. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/motion-control-photography", "title": "Motion-Control Photography · 本库原创图解", "previewKind": "原创技法示意", "local": "motion-control-photography.webp"},
  "motion-sequence": {"prompt": "Transform this image into a Motion Sequence study arranged as an orderly grid of consecutive photographic frames. Repeat the subject with small, plausible changes in movement, maintaining consistent camera position, lighting, scale, monochrome tones, fine grain, and narrow pale gutters. Keep the original subject and composition within each frame.", "credit": "Eadweard Muybridge / Library of Congress via Wikimedia Commons. Public Domain/Commons PDM.", "source": "https://www.loc.gov/item/2005684184/", "local": "motion-sequence.webp", "title": "Motion Sequence", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "mser-regions": {"prompt": "Apply MSER Regions as an overlay of selectively outlined, translucent colored patches around distinctive connected light and dark areas. Include nested regions where appropriate, leave unstable textures unmarked, and avoid tracing every edge. Retain the original photographic detail beneath crisp region boundaries. Keep the original subject and composition.", "credit": "Image: Clem Onojeghuo clemono2 · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Letchworth_Garden_City,_United_Kingdom_(Unsplash_PYpPX76yZ1A).jpg", "local": "mser-regions.webp", "title": "MSER Regions", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "multi-scale-retinex": {"prompt": "Apply Multi-Scale Retinex, lifting shadow detail and compressing broad illumination differences while strengthening local texture and contrast. Balance bright and dim regions, retain restrained natural colors, and reveal surface detail without flattening every contour or adding dramatic new lighting. Keep highlights controlled and edges clean. Keep the original subject and composition.", "credit": "Image: Rusu George Lucian rgeorgelucian · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Rusu_George_Lucian_2016-04-12_(Unsplash).jpg", "local": "multi-scale-retinex.webp", "title": "Multi-Scale Retinex", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "multiplane-camera": {"prompt": "Apply a Multiplane Camera effect by rendering the scene as painted animation layers on spaced glass panels. Give foreground shapes crisp cutout edges, middle layers delicate brushwork, and distant scenery softer colors and atmospheric haze. Emphasize overlapping planes and subtle depth separation. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/multiplane-camera", "title": "Multiplane Camera · 本库原创图解", "previewKind": "原创技法示意", "local": "multiplane-camera.webp"},
  "neon-sign-glow": {"prompt": "Transform this image into a Neon Sign Glow treatment, tracing the subject’s defining contours with luminous glass tubes in hot pink, electric blue, and orange-red. Use rounded bends, consistent stroke thickness, bright cores, soft colored halos, and faint reflections against dark surroundings. Keep the original subject and composition.", "credit": "Carol M. Highsmith · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Neon_sign_outside_a_bar,_not_Billy_Bob%27s,_which_is_a_separate_night_club_and_dance_hall_nearby,_in_the_Stockyards_District_of_Fort_Worth,_Texas_LCCN2014632898.tif", "local": "neon-sign-glow.webp", "title": "Neon Sign Glow", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "neumorphism": {"prompt": "Transform this image into a Neumorphism relief using pale monochromatic surfaces, rounded forms, and shallow extrusions emerging from a matching background. Pair soft upper-left highlights with blurred lower-right shadows, adding gentle inset recesses and matte material texture without hard outlines. Keep the original subject and composition.", "credit": "Awesomecat · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Neumorphism-fixed.jpg", "local": "neumorphism.webp", "title": "Neumorphism", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "neural-radiance-fields": {"prompt": "Apply a Neural Radiance Fields look with photorealistic spatial depth, nuanced reflections, translucent material detail, and softly integrated volumetric lighting. Add slight peripheral haze and gently blurred uncertainty around difficult fine structures, while keeping the viewpoint fixed and central surfaces convincing. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/neural-radiance-fields", "title": "Neural Radiance Fields · 本库原创图解", "previewKind": "原创技法示意", "local": "neural-radiance-fields.webp"},
  "neural-relighting": {"prompt": "Apply Neural Relighting with a warm directional key light from the upper left and cool, soft fill from the right. Redirect cast shadows consistently, shift specular highlights to match surface geometry, and preserve natural material textures without changing viewpoint. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/neural-relighting", "title": "Neural Relighting · 本库原创图解", "previewKind": "原创技法示意", "local": "neural-relighting.webp"},
  "neural-style-transfer": {"prompt": "Apply a Neural Style Transfer effect, translating photographic surfaces into layered painterly brushstrokes, swirling pigment textures, and harmonized teal, ochre, and crimson tones. Let repeated stroke patterns follow major forms, preserving recognizable contours while replacing fine photographic detail with expressive painted texture. Keep the original subject and composition.", "credit": "Kira Wales · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Jimmy_Wales_in_France,_with_the_style_of_Munch%27s_%22The_Scream%22_applied_using_neural_style_transfer.jpg", "local": "neural-style-transfer.webp", "title": "Neural Style Transfer", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "night-vision": {"prompt": "Apply a Night Vision effect with monochrome phosphor green, murky dark green shadows, bright lime highlights, coarse sensor grain, and scattered luminous noise. Compress tonal contrast, bloom intense light sources, soften fine details, and add subtle edge vignetting for an amplified low-light appearance. Keep the original subject and composition.", "credit": "Sgt. 1st Class Aaron Shuemake / West Virginia National Guard. Public domain.", "source": "https://ntrs.nasa.gov/citations/19930043196", "local": "night-vision.webp", "title": "Night Vision", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "non-local-means-denoise": {"prompt": "Apply Non-Local Means Denoising to suppress random luminance grain and colored speckles while retaining recurring textures and meaningful detail. Make flat surfaces cleaner and shadows smoother, with stable edges and natural tonal transitions. Avoid waxy skin, smeared patterns, or invented texture. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "non-local-means-denoise.webp", "title": "Non-Local Means Denoising", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "normal-map": {"prompt": "Transform this image into a Normal Map effect, replacing photographic colors with a smooth RGB surface-orientation visualization. Use a lavender-blue base for forward-facing surfaces, with pink, cyan, and green shifts across differently tilted planes. Remove cast shadows and natural texture while emphasizing relief and contour changes. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "normal-map.webp", "title": "Normal Map", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "normal-mapping": {"prompt": "Apply a Normal Mapping effect by giving existing surfaces fine simulated bumps, pores, grooves, and embossed details that respond consistently to directional light. Use tiny highlight and shadow variations to suggest relief while keeping silhouettes, surface positions, and outer edges completely unchanged. Keep the original subject and composition.", "credit": "Paolo Cignoni", "source": "https://commons.wikimedia.org/wiki/File:Normal_map_example.png", "local": "normal-mapping.webp", "title": "Normal map example", "license": "CC BY-SA 1.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/1.0/"},
  "ntsc-composite-artifacts": {"prompt": "Apply NTSC Composite Artifacts with crawling checkerboard dots along high-contrast boundaries, rainbow cross-color interference over fine patterns, and smeared chroma bleeding beyond luminance edges. Add faint horizontal scanlines, analog noise, uneven saturation, and soft television detail while keeping forms legible. Keep the original subject and composition.", "credit": "Dmitry Makeev", "source": "https://commons.wikimedia.org/wiki/File:Composite_video.jpg", "local": "ntsc-composite-artifacts.webp", "title": "Composite video", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "ntsc": {"prompt": "Apply an NTSC Composite Bleed effect with softened, slightly washed-out colors spreading horizontally beyond comparatively sharper luminance edges. Add subtle rainbow fringes, faint dot-crawl patterns along contrasting boundaries, and mild analog video noise. Avoid large displaced blocks or dramatic tracking tears; keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "ntsc.webp", "title": "NTSC Composite Bleed", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "op-art": {"prompt": "Transform this image into Op Art using tightly repeated black-and-white stripes, concentric contours, and alternating geometric bands that follow existing forms. Create apparent vibration and warped depth through changing line spacing, sharp edges, and extreme contrast, keeping recognizable silhouettes within the pattern. Keep the original subject and composition.", "credit": "Basile Morin · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Ambigram_Future_tessellation.png", "local": "op-art.webp", "title": "Op Art", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "openpose": {"prompt": "Transform this image into a Pose Skeleton visualization, representing visible articulated figures with bright joint dots connected by thin, multicolored rods over a strongly darkened photograph. Follow existing limb positions and joint bends, using distinct colors for different body segments and no filled silhouettes. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "openpose.webp", "title": "OpenPose Skeleton", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "optical-flow-frame-interpolation": {"prompt": "Apply an Optical Flow Interpolation effect as a still-frame simulation, introducing localized rubbery contours, stretched textures, and translucent double edges around implied movement. Add subtle warping where foreground and background meet, while leaving stationary regions crisp and maintaining otherwise natural photographic color and lighting. Keep the original subject and composition.", "credit": "User:Peregrine Fisher, User:nr1jack", "source": "https://commons.wikimedia.org/wiki/File:Motion_interpolation_example.jpg", "local": "optical-flow-frame-interpolation.webp", "title": "Motion interpolation example", "license": "CC BY 2.5", "licenseUrl": "https://creativecommons.org/licenses/by/2.5/"},
  "optical-flow-vector-field": {"prompt": "Apply Optical Flow Vectors as a technical overlay of small, high-contrast arrows anchored to visible image features. Use coherent arrow directions and lengths to suggest estimated displacement between slightly shifted frames, leaving low-detail areas sparse. Keep the underlying photograph legible and naturally colored. Preserve the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/optical-flow-vector-field", "title": "Optical Flow Vectors · 本库原创图解", "previewKind": "原创技法示意", "local": "optical-flow-vector-field.webp"},
  "optical-printer": {"prompt": "Apply an Optical Printer effect with faint superimposed image echoes, localized enlargement, soft composite boundaries, and slight misregistration. Introduce accumulated film grain, increased contrast, washed highlights, subtle color shifts, and tiny dust artifacts characteristic of repeatedly photographed film. Keep the original subject and composition.", "credit": "Historical documentation, public domain according to Wikimedia Commons.", "source": "https://collection.sciencemuseumgroup.org.uk/objects/co8236963/oxberry-optical-printer", "local": "optical-printer.webp", "title": "Optical Printer", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "orb-keypoints": {"prompt": "Apply ORB Keypoints as a computer-vision overlay on a subdued photograph. Distribute thin colored circles across distinctive corners and textured patches, varying circle sizes by feature scale and adding short orientation ticks. Leave smooth areas sparsely marked and preserve visible photographic detail. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "orb-keypoints.webp", "title": "ORB Keypoints", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "orton-effect": {"prompt": "Apply the Orton Effect by combining crisp underlying detail with a softly defocused luminous overlay. Make highlights bloom gently, enrich colors, and deepen shadows while retaining clear dark contours. Create a dreamy photographic atmosphere without flattening textures or blurring every feature equally. Keep the original subject and composition.", "credit": "Herr Kriss · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Orton_(PAC)_-_result_image.jpg", "local": "orton-effect.webp", "title": "Orton Effect", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "oscilloscope-art": {"prompt": "Transform this image into Oscilloscope Art, rebuilding visible forms from luminous green phosphor traces against a near-black field. Use looping contours, intertwined waveforms, bright intersections, fine scan jitter, and soft persistence trails. Suggest interior shading through denser overlapping lines rather than solid fills. Keep the original subject and composition.", "credit": "Telec. Concepteur", "source": "https://commons.wikimedia.org/wiki/File:Collection_Charles_Cros._Cam%C3%A9ras_film_(m%C3%A9dia_-_image_anim%C3%A9e)._Cam%C3%A9ras_pour_oscilloscope_type_6_-_Telec._Cam%C3%A9ra_Telec_pour_oscilloscope_de_l%27Institut_de_Phon%C3%A9tique,_type_6411,_n%C2%B0_de_s%C3%A9rie_372_EN_35_-_btv1b55009458z_(06_of_20).jpg", "local": "oscilloscope-art.webp", "title": "Collection Charles Cros. Caméras film (média : image animée). Caméras pour oscilloscope type 6 - Telec. Caméra Telec pour oscilloscope de l' (1)", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "otsu-binarization": {"prompt": "Apply Otsu Binarization, separating the entire photograph into solid black and solid white using one global brightness threshold. Create bold connected masses, hard contours, and simplified details, allowing shaded regions to merge naturally. Eliminate color, intermediate gray, gradients, and decorative dithering. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "otsu-binarization.webp", "title": "Otsu Binarization", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "paik-abe-video-synthesizer": {"prompt": "Apply a Paik–Abe Video Synthesizer effect, replacing natural shading with abrupt patches of electric cyan, hot magenta, acid green, and saturated yellow. Layer slightly offset silhouettes, luminous color bleed, soft analog scanlines, and clipped electronic highlights while retaining recognizable outlines. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/paik-abe-video-synthesizer", "title": "Paik–Abe Video Synthesizer · 本库原创图解", "previewKind": "原创技法示意", "local": "paik-abe-video-synthesizer.webp"},
  "paint-on-glass-animation": {"prompt": "Transform this image into a Paint-on-Glass Animation frame with luminous translucent pigments, wet brush marks, smeared color transitions, and softly dissolving edges. Suggest hand-worked oil paint on backlit glass through scraped highlights, pooled color, and faint traces of earlier strokes. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/paint-on-glass-animation", "title": "Paint-on-Glass Animation · 本库原创图解", "previewKind": "原创技法示意", "local": "paint-on-glass-animation.webp"},
  "palette-cycling": {"prompt": "Apply a Palette Cycling effect using a restricted indexed-color appearance and repeating bands of cyan, blue, green, and violet. Arrange neighboring color steps along existing flowing forms to suggest rippling movement in a single frame, with fixed outlines and crisp pixel boundaries. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/palette-cycling", "title": "Palette Cycling · 本库原创图解", "previewKind": "原创技法示意", "local": "palette-cycling.webp"},
  "palette-glitch": {"prompt": "Apply a Palette Glitch effect with localized blocks of incorrectly mapped colors, abrupt hue substitutions, and posterized tonal bands. Introduce selective channel offsets inside corrupted regions while leaving neighboring areas normally colored. Use hard digital boundaries and conspicuously unnatural color combinations; keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "palette-glitch.webp", "title": "Palette Glitch", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "panning-shot": {"prompt": "Transform this image into a Panning Shot, keeping the main subject mostly sharp against long horizontal background streaks. Stretch surrounding colors into directional bands, add restrained motion softness to moving extremities, and preserve clear focal contours. Maintain natural exposure and avoid radial zoom blur. Keep the original subject and composition.", "credit": "Md.Mijanur rahman Mijan · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Bicycle_ride_in_Dhaka.jpg", "local": "panning-shot.webp", "title": "Panning Shot", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "panoramic-photography": {"prompt": "Apply a historical Panoramic Photography treatment with an elongated horizontal presentation, warm monochrome tones, fine plate detail, and subtle exposure changes across faint vertical joins. Extend only peripheral scenery to suggest a broader sweep, with slight swing-lens curvature near the outer edges. Keep the original subject and composition.", "credit": "Charles H. Fontayne (1814–1901) and William Southgate Porter (1822–1889) · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Cincinnati_Panorama_of_1848.jpg", "local": "panoramic-photography.webp", "title": "Panoramic Photography", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "particle-systems": {"prompt": "Apply a particle systems effect, reconstructing visible forms from dense swarms of tiny luminous points and softly translucent flecks. Use bright clustered cores, smoky irregular edges, scattered sparks, short directional trails, and varied particle sizes, with additive glow against darker existing areas. Keep the original subject and composition.", "credit": "Holger Weihe · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Partikelsystem.jpg", "local": "particle-systems.webp", "title": "Particle Systems", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "patch-tokenization-grid": {"prompt": "Apply a Patch Tokenization Grid effect, dividing the photograph into evenly sized square patches with thin, crisp, neutral-colored boundary lines. Keep each tile aligned and its photographic content unchanged, making local textures, colors, and edges readable as separate units. Avoid gaps, shuffled tiles, labels, or dimensional shading. Keep the original subject and composition.", "credit": "Image: Nicola Gypsicola nicolagypsicola · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Bass_player_in_black_and_white_(Unsplash).jpg", "local": "patch-tokenization-grid.webp", "title": "Patch Tokenization Grid", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "pen-plotter-art": {"prompt": "Transform this image into Pen Plotter Art, rebuilding forms with fine, uniform ink strokes on warm white paper. Use geometric grids, repeated contours, crosshatching, and controlled positional irregularities; create dark areas through overlapping lines rather than painted gradients. Include subtle paper fibers. Keep the original subject and composition.", "credit": "Tomasz Sienicki [user: tsca, mail: tomasz.sienicki at gmail.com] · CC BY 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Automatisches_Zeichengeraet_ZUSE_Z64_ubt.JPG", "local": "pen-plotter-art.webp", "title": "Pen Plotter Art", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/"},
  "pencil-sketch": {"prompt": "Transform this image into a Pencil Sketch with delicate graphite-gray contours on lightly textured white paper. Emphasize fine edges, pale interior areas, soft rubbed shading, and restrained pencil grain, leaving highlights mostly unmarked. Avoid heavy black fills, colored marks, or painted surfaces. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "pencil-sketch.webp", "title": "Pencil Sketch", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "pepper-s-ghost": {"prompt": "Apply a Pepper’s Ghost effect by making the main subject appear as a faint, luminous reflection suspended against the existing background. Allow background details to show through, with pale highlights, subdued contrast, slight glass reflections, and minimal reflected-edge doubling rather than smoky outlines. Keep the original subject and composition.", "credit": "Bertrand (no first name given)", "source": "https://commons.wikimedia.org/wiki/File:Peppers_Ghost.jpg", "local": "pepper-s-ghost.webp", "title": "Peppers Ghost", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "perlin-noise": {"prompt": "Apply a Perlin Noise effect using smooth, organic gradients that resemble drifting clouds, pale marble veins, and swirling water. Blend layered light and dark undulations into existing surfaces, with softly connected contours and no harsh static or isolated speckles. Keep the original subject and composition.", "credit": "Lord Belbury · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Perlin_noise_example.png", "local": "perlin-noise.webp", "title": "Perlin Noise", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "perspective-warp": {"prompt": "Apply Perspective Warp to tilt the photograph onto an oblique quadrilateral plane, narrowing one side and stretching the opposite side. Make parallel lines converge naturally, with clean resampled edges and unchanged surface textures and colors. Avoid curved distortions. Preserve the original subject and composition within the transformed plane.", "credit": "Image: Keilidh Ewan keilidhewan · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Orange_Fruit_(Unsplash).jpg", "local": "perspective-warp.webp", "title": "Perspective Warp", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "petzval-swirl-bokeh": {"prompt": "Apply Petzval Swirl Bokeh with a sharply resolved main subject and progressively softer surroundings. Stretch peripheral background highlights into tangential cat-eye ovals that form a circular swirl, adding gentle corner darkening, mild edge softness, and warm natural light without blurring important subject details. Keep the original subject and composition.", "credit": "Javier Perez Montes · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Rosa_Yellow_Fairy_-_Rosaleda_Parque_del_Oeste_-_Madrid_01.jpg", "local": "petzval-swirl-bokeh.webp", "title": "Petzval Swirl Bokeh", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "phenakistiscope-loop": {"prompt": "Apply a Phenakistiscope Loop treatment with hand-drawn sequential poses arranged around a peripheral circular disc, separated by narrow radial viewing slits. Use muted printed colors, aged card texture, crisp silhouette changes, and faint rotational echoes, keeping the main image anchored within the center. Keep the original subject and underlying composition.", "credit": "Simon Stampfer · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Optical_Toy,_Phenakistiscope_Disc_with_Distorted_Man,_1833_(CH_18607979).jpg", "local": "phenakistiscope-loop.webp", "title": "Phenakistiscope Loop", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "phong-shading": {"prompt": "Apply a Phong Shading effect, rendering existing forms as smooth early computer-generated solids with glossy plastic surfaces and tight, bright specular highlights. Use continuously curved lighting gradients, simple directional illumination, restrained ambient shadows, clean silhouettes, and minimal texture or environmental reflections. Keep the original subject and composition.", "credit": "Davi.trip · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Shading_models.png", "local": "phong-shading.webp", "title": "Phong Shading", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "photo-booth-strip": {"prompt": "Transform this image into a Photo Booth Strip with four vertically stacked repetitions of the uploaded view, separated by pale borders on a narrow photographic paper strip. Use monochrome chemistry, direct frontal lighting, gentle grain, slightly uneven exposure, and worn paper edges. Within every frame, keep the original subject and composition.", "credit": "leafar · CC BY-SA 2.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Photo_booth_strip_00001.jpg", "local": "photo-booth-strip.webp", "title": "Photo Booth Strip", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/"},
  "photochrom": {"prompt": "Apply a Photochrom effect, combining precise photographic luminance detail with boldly placed lithographic color layers. Use saturated blue, ochre, brick red, and muted green where appropriate, slightly simplified color boundaries, fine irregular ink texture, and subtle registration offsets on warm matte paper. Keep the original subject and composition.", "credit": "Library of Congress / Photochrom Print Collection / Public Domain", "source": "https://www.loc.gov/pictures/collection/pgz/process.html", "local": "photochrom.webp", "title": "Photochrom", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "photocopy-aesthetic": {"prompt": "Transform this image into a Photocopy Aesthetic, using harsh black toner on slightly dirty off-white paper. Crush shadows into solid masses, erase delicate midtones, and introduce speckled deposits, broken edges, streaks, uneven density, and faint duplicate contours from repeated copying. Keep the original subject and composition.", "credit": "Miloslav Požár", "source": "https://commons.wikimedia.org/wiki/File:Ob%C4%9Bd,_xerox,_monotyp,_1984.jpg", "local": "photocopy-aesthetic.webp", "title": "Oběd, xerox, monotyp, 1984", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "photodynamism": {"prompt": "Apply Photodynamism by dissolving implied movement into connected translucent ribbons, flowing smears, and overlapping contours across a relatively still background. Anchor the motion with a few sharper resting forms, using subdued monochrome tones and long-exposure luminosity rather than separate evenly spaced snapshots. Keep the original subject and composition.", "credit": "Sebastiano Arturo Luciani · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:L%27Antiteatro._Il_cinematografo_come_arte_(page_135_crop).jpg", "local": "photodynamism.webp", "title": "Photodynamism", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "photoelasticity": {"prompt": "Apply a Photoelasticity effect by making the subject resemble transparent stressed plastic viewed between crossed polarizers. Add curved rainbow interference bands, dense colored fringes around corners and contact points, glassy edges, and near-black unstressed regions against a darkened background. Keep the original subject and composition.", "credit": "Colin · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Photoelasticity_-_Gillette_Fusion_razor_holder.jpg", "local": "photoelasticity.webp", "title": "Photoelasticity", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "photogram": {"prompt": "Transform this image into a Photogram, rendering the subject as luminous white silhouettes and translucent gray forms on deep black photographic paper. Combine sharp contact edges with soft hovering shadows, overlapping transparency, delicate surface textures, and slight development mottling. Remove conventional modeled lighting. Keep the original subject and composition.", "credit": "Uploaded by Cormaggio", "source": "https://commons.wikimedia.org/wiki/File:Lemons_photogram.jpg", "local": "photogram.webp", "title": "Lemons photogram", "license": "CC BY-SA 1.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/1.0/"},
  "photogrammetry": {"prompt": "Apply a Photogrammetry effect, rendering the scene as a reconstructed three-dimensional scan covered in photographic textures. Introduce subtle triangulated surface irregularities, baked lighting, stretched textures near occlusions, and small rough mesh gaps along complex edges, while retaining realistic color and recognizable volume. Keep the original subject and composition.", "credit": "DanielNaseri", "source": "https://commons.wikimedia.org/wiki/File:Wall_Painting.png", "local": "photogrammetry.webp", "title": "Wall Painting", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "photographic-joiners": {"prompt": "Transform this image into Photographic Joiners: overlapping rectangular photographic prints with visible white borders, seams, slight rotations, and uneven exposure. Introduce small viewpoint offsets and repeated details across neighboring tiles, creating a fractured but readable reconstruction rather than a seamless panorama. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/photographic-joiners", "title": "Photographic Joiners · 本库原创图解", "previewKind": "原创技法示意", "local": "photographic-joiners.webp"},
  "photogravure": {"prompt": "Apply a Photogravure effect with richly inked, velvety blacks, subtle continuous gray transitions, and delicate highlight detail. Add microscopic random aquatint grain rather than regular dots, warm textured paper, softly absorbed edges, and a faint recessed plate impression around the image. Keep the original subject and composition.", "credit": "Alvin Langdon Coburn · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Andrew_Lang_by_Alvin_Langdon_Coburn,_August_27,_1904,_photogravure,_from_the_National_Portrait_Gallery_-_NPG-S-NPG_87_288_c.jpg", "local": "photogravure.webp", "title": "Photogravure", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "photomicrography": {"prompt": "Apply a Photomicrography treatment that makes existing surfaces resemble magnified translucent specimens, revealing fine cellular meshes, granular inclusions, and delicate internal striations. Use transmitted illumination, shallow focus, restrained monochrome tones, and a softly darkened circular field without cropping essential details. Keep the original subject and composition.", "credit": "National Museum of Health and Medicine · CC BY 2.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Transverse_section_with_chronic_inflammation_(CP_2328),_National_Museum_of_Health_and_Medicine_(4777488210).jpg", "local": "photomicrography.webp", "title": "Photomicrography", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "photomontage": {"prompt": "Transform this image into a Photomontage of visibly cut photographic fragments, mismatched scales, displaced detail duplicates, and scattered typographic scraps. Use hard scissor-cut edges, torn paper fibers, overlapping layers, inconsistent grayscale tones, and subtle paste shadows while retaining the overall arrangement. Keep the original subject and composition.", "credit": "Theo van Doesburg", "source": "https://commons.wikimedia.org/wiki/File:Theo_van_Doesburg_038.jpg", "local": "photomontage.webp", "title": "Simultaneous portrait of Nelly-Pétro.", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "photorealistic-cgi": {"prompt": "Transform this image into Photorealistic CGI with physically convincing materials, fine surface textures, natural reflections, and lighting matched precisely to the scene. Integrate modeled forms seamlessly using accurate perspective, soft contact shadows, realistic depth of field, and restrained motion blur where appropriate. Keep the original subject and composition.", "credit": "Awinch1001", "source": "https://commons.wikimedia.org/wiki/File:Renderman3.jpg", "local": "photorealistic-cgi.webp", "title": "Renderman3", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "photosculpture": {"prompt": "Transform this image into a Photosculpture, rendering the subject as a solid, three-dimensional ivory plaster bust or statuette. Model recognizable facial contours, clothing folds, and pose with hand-finished surfaces, subtle tool marks, crisp silhouettes, and soft directional shadows rather than photographic skin texture. Keep the original subject and composition.", "credit": "Willème, Auguste François (Sedan, en 1830 - Roubaix, en 1905), sculpteur · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Portrait_de_Jean-Baptiste-Fran%C3%A7ois_Bressant_(1815-1866),_acteur._S1577_(1_of_5).jpg", "local": "photosculpture.webp", "title": "Photosculpture", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "pincushion-distortion": {"prompt": "Apply Pincushion Distortion to create a centrally pinched appearance, bowing straight lines near the perimeter inward toward the middle. Increase the curvature toward the corners while keeping central details relatively stable. Retain natural colors, lighting, and continuous textures without folds or tears. Preserve the original subject and composition.", "credit": "Image: Alex Lambley alexscottlambley · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Daring_(Unsplash).jpg", "local": "pincushion-distortion.webp", "title": "Pincushion Distortion", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "pinhole-photography": {"prompt": "Apply a Pinhole Photography effect with gentle, consistent softness across near and distant details, deep apparent focus, slight corner darkening, and subdued contrast. Suggest a long exposure through faint motion trails in moving elements while stationary structures remain softly defined, with delicate grain. Keep the original subject and composition.", "credit": "SqueakyMarmot from Vancouver, Canada", "source": "https://commons.wikimedia.org/wiki/File:Kidz_Labs_pinhole_camera_(430043248).jpg", "local": "pinhole-photography.webp", "title": "Kidz Labs pinhole camera (430043248)", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "pinscreen-animation": {"prompt": "Apply a Pinscreen Animation effect in black, white, and finely graduated gray. Build forms from dense pinprick textures and tiny elongated side-lit shadows, creating velvety dark masses, luminous open areas, and soft engraving-like contours on a matte white board. Keep the original subject and composition.", "credit": "Lëa-Kim Châteauneuf · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:%C3%89cran_d%27%C3%A9pingles_-_D%C3%A9tail_(face).jpg", "local": "pinscreen-animation.webp", "title": "Pinscreen Animation", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "pixel-art": {"prompt": "Transform this image into Pixel Art using a visibly low-resolution square grid, a restricted color palette, and deliberate clusters of solid pixels. Create sharp stair-step contours, simplified shading, and selective checkerboard dithering, with no smooth gradients, blurred edges, or antialiasing. Keep the original subject and composition.", "credit": "Nodin Cutfeet · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Cree_woodlands_techno_pixel_art.jpg", "local": "pixel-art.webp", "title": "Pixel Art", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "pixel-sorting": {"prompt": "Apply a Pixel Sorting effect by stretching selected image regions into ordered horizontal or vertical bands of color and brightness. Create sharp stripe boundaries, elongated pixel runs, and abrupt transitions between intact details and corrupted areas, using colors sampled from the photograph. Keep the original subject and composition.", "credit": "Diego Delso (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Amanecer_en_Huitzila,_M%C3%A9xico,_2013-10-10,_DD_01.JPG", "local": "pixel-sorting.webp", "title": "Pixel Sorting, applied to “Amanecer en Huitzila, México, 2013-10-10, DD 01”", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "pixelation-2": {"prompt": "Apply Nearest-Neighbor Pixelation, reducing the image to a low-resolution grid and enlarging it into prominent, uniformly sized square pixels. Give each block one flat sampled color, with hard staircase edges, simplified textures, and no interpolation, blur, outlines, or added grain. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "pixelation-2.webp", "title": "Nearest-Neighbor Pixelation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "pixelation": {"prompt": "Apply a Pixelation effect using large, clearly visible square and rectangular blocks, each filled with one sampled color. Replace fine details with coarse color clusters, preserve the broad light and dark masses, and use crisp block boundaries without smoothing or added outlines. Keep the original subject and composition.", "credit": "Created with DALL·E, an AI system by OpenAI", "source": "https://commons.wikimedia.org/wiki/File:AP_Press_photo_of_anthropomorphic_rhinoceroses_wearing_a_business_suit_infront_of_Parliament_building,_giving_a_speech_on_a_microphone_on_a_lecterns,_pixelation_on_his_chest_area,_a_thick_black_censor_bar_covering_his.jpg", "local": "pixelation.webp", "title": "AP Press photo of anthropomorphic rhinoceroses wearing a business suit infront of Parliament building, giving a speech on a microphone on a", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "pixilation": {"prompt": "Apply a Pixilation stop-motion look to this still, giving existing gestures a stiff, deliberately staged quality with crisp silhouettes and puppet-like articulation. Suggest discontinuous movement through a few faint, separated positional echoes rather than continuous blur, using natural textures and subtly uneven exposure. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/pixilation", "title": "Pixilation · 本库原创图解", "previewKind": "原创技法示意", "local": "pixilation.webp"},
  "plasma-effect": {"prompt": "Apply a Plasma Effect using smoothly flowing psychedelic fields of magenta, cyan, violet, yellow, and electric blue. Form liquid blobs, nested color waves, and swirling gradients across existing shapes, with soft luminous transitions and no hard pattern boundaries, retaining recognizable underlying forms. Keep the original subject and composition.", "credit": "Ben Taylor, who is the creator of TheArtProblem.com · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Plasma_fractal_theartproblem_3993.jpg", "local": "plasma-effect.webp", "title": "Plasma Effect", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "platinum-print": {"prompt": "Apply a Platinum Print effect with a completely matte surface, exceptionally fine neutral-to-warm gray gradations, delicate luminous highlights, and deep yet open shadows. Embed the image softly into visible cotton paper fibers, avoiding glossy reflections, coarse grain, or harsh contrast. Keep the original subject and composition.", "credit": "The J. Paul Getty Museum / Peter Henry Emerson / Public Domain", "source": "https://www.getty.edu/art/exhibitions/focus_platinum/", "local": "platinum-print.webp", "title": "Platinum Print", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "pochoir-stencil-print": {"prompt": "Apply the Pochoir Stencil Print effect with vivid gouache-like color blocks, sharply cut silhouettes, and thick matte pigment on textured paper. Use slight hand-brushed density variations, occasional stencil overlap, and crisp decorative simplification, avoiding halftone dots, photographic gradients, or glossy surfaces. Keep the original subject and composition.", "credit": "Rijksmuseum · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:La_Guirlande_des_mois,_1917-1920_L%27Eau,_RP-P-2009-1823.jpg", "local": "pochoir-stencil-print.webp", "title": "Pochoir Stencil Print", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "point-cloud-proxy": {"prompt": "Transform this image into a Point Cloud Proxy, reconstructing visible forms as dense, discrete dots sampled from the photograph's colors against a dark background. Suggest shallow spatial depth through dot size and brightness, leaving small gaps between points and avoiding continuous surfaces or connecting lines. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "point-cloud-proxy.webp", "title": "Point Cloud Proxy", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "point-cloud-rendering": {"prompt": "Transform this image into a Point Cloud Rendering, rebuilding visible surfaces from dense spatial dots and tiny colored splats. Introduce sparse gaps, depth-dependent point sizes, granular silhouettes, and a dark background visible between samples. Avoid continuous polygon surfaces while retaining recognizable volumes. Keep the original subject and composition.", "credit": "Mweaver89", "source": "https://commons.wikimedia.org/wiki/File:LiDAR_visualization_of_bulk_material_in_an_open-top_truck.png", "local": "point-cloud-rendering.webp", "title": "LiDAR visualization of bulk material in an open-top truck", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "polar-coordinates": {"prompt": "Apply a polar coordinates effect to the surrounding scenery, wrapping background textures into circular bands and bending straight lines into concentric arcs around a compact planet-like center. Blend the angular seam smoothly and concentrate radial stretching away from defining subject features. Keep the original subject and composition.", "credit": "Alexandre Duret-Lutz from Paris, France", "source": "https://commons.wikimedia.org/wiki/File:Stereographic_projection_of_a_panorama_built_from_6_pictures._Shot_handheld_using_the_tripod_as_a_pole._Part_of_my_(a_href%3D%22http-www.flickr.com-photos-gadl-sets-72157594279945875-%22)Wee_planets(-a)_set._-_Flickr_-_gadl.jpg", "local": "polar-coordinates.webp", "title": "Stereographic projection of a panorama built from 6 pictures. Shot handheld using the tripod as a pole. Part of my (a href=\"http-www.flickr.", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/"},
  "polaroid-manipulation": {"prompt": "Apply a 1970s instant-photo emulsion manipulation effect, making photographic details resemble thick, wet paint pushed beneath a glossy surface. Introduce melted contours, pressure-dragged streaks, swirling color pools, soft chemical bleeding, and uneven pastel saturation while retaining recognizable features. Keep the original subject and composition.", "credit": "Hellbus · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Chevy_Nova_SX-70_manipulation.jpg", "local": "polaroid-manipulation.webp", "title": "Polaroid Manipulation", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "polaroid-sx-70": {"prompt": "Transform this image into an Integral Instant Film photograph, using softly muted colors, creamy highlights, warm skin tones where present, gentle shadow haze, and subtle chemical mottling. Fit the uncropped image within a square print surrounded by an ivory border with a wider bottom margin. Keep the original subject and composition.", "credit": "Moki8 · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Polaroid_Big_Shot.jpg", "local": "polaroid-sx-70.webp", "title": "Polaroid SX-70", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "political-retouching": {"prompt": "Apply a Political Retouching effect resembling an altered archival photograph, with monochrome grain, airbrushed background patches, scraped emulsion marks, and awkwardly repeated wall or ground textures. Suggest an erased peripheral presence through a faint ghost outline and unnaturally blank patch. Keep the original subject and composition.", "credit": "Unidentified Soviet photographer. · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Soviet_censorship_with_Stalin2.jpg", "local": "political-retouching.webp", "title": "Political Retouching", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "portrait-vignette": {"prompt": "Apply a Portrait Vignette effect with a softly feathered oval image area centered on the main subject. Fade surrounding details gradually into warm ivory photographic paper, using gentle sepia tones, fine grain, and luminous midtones without a hard oval outline or dark corners. Keep the original subject and composition.", "credit": "Unknown photographer / J. Paul Getty Museum. Getty Open Content; historical work in the public domain.", "source": "https://www.getty.edu/art/collection/object/107HCH", "local": "portrait-vignette.webp", "title": "Portrait Vignette", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "posterization": {"prompt": "Apply a Posterization effect by reducing the image to a few distinct tonal levels per color channel. Turn smooth gradients into flat, sharply separated color bands, simplify shadows and highlights, and retain recognizable contours without introducing pixel blocks, grain, or drawn outlines. Keep the original subject and composition.", "credit": "Yann SEGALEN (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Friction_d%27une_allumette.jpg", "local": "posterization.webp", "title": "Posterization, applied to “Friction d'une allumette”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "praxinoscope": {"prompt": "Transform this image into a Praxinoscope display, translating the subject into brightly colored sequential drawings inside an open rotating drum. Show a central ring of mirrors reflecting a clear, steady-looking action phase, with neighboring phases on the surrounding strip, polished reflections, and no viewing slits. Keep the original subject and composition.", "credit": "Sukkoria · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Toy_praxinoscope_by_Charles_%C3%89mile_Reynaud_-_CnAM_16696-2_-_01.jpg", "local": "praxinoscope.webp", "title": "Praxinoscope", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "prewitt-edge": {"prompt": "Apply Prewitt Edges, replacing photographic tones with stark grayscale boundary responses on black. Emphasize horizontal and vertical transitions using uniformly weighted, slightly broad edge bands, with angular intersections and subdued diagonal texture. Make stronger contrast brighter while leaving flat regions dark. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "prewitt-edge.webp", "title": "Prewitt Edges", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "psychedelic-poster-art": {"prompt": "Transform this image into Psychedelic Poster Art, using saturated orange against electric blue, magenta against green, and tightly packed swirling ornament. Bend contours into flowing, lettering-like shapes without readable text, add dense decorative borders, and retain flat printed-ink textures with vibrating color boundaries. Keep the original subject and composition.", "credit": "MerleEllaPatsy · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Official_Film_Poster_for_The_Tale_of_the_Dog_Documentary_Film_(2021).jpg", "local": "psychedelic-poster-art.webp", "title": "Psychedelic Poster Art", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "pulfrich-effect": {"prompt": "Apply a Pulfrich Effect visualization as a static motion study, suggesting lateral movement through closely spaced translucent positions that follow a shallow elliptical depth path. Use asymmetric brightness between motion echoes, subtle overlap, and a clear central subject; avoid red-cyan anaglyph coloring. Keep the original subject and composition.", "credit": "Cmglee · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Pulfrich_effect_pendulum.svg", "local": "pulfrich-effect.webp", "title": "Pulfrich Effect", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "push-processing": {"prompt": "Apply a Push Processing effect with coarse, conspicuous photographic grain, steep contrast, dense blocked shadows, and harsh luminous highlights. Reduce subtle shadow detail, introduce uneven grain clumping and slightly rough tonal transitions, and retain an underexposed, available-light atmosphere rather than a polished digital finish. Keep the original subject and composition.", "credit": "Sérgio Valle Duarte .mw-parser-output .messagebox{margin:4px 0;width:auto;border-collap… · CC BY 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Vieira_Souto_-_Lagoa_Rodrigo_de_Freitas,_seagull.jpg", "local": "push-processing.webp", "title": "Push Processing", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/"},
  "quantel-paintbox": {"prompt": "Apply a 1980s Digital Airbrush effect with saturated turquoise, hot pink, and violet accents, soft sprayed-looking shading, and exceptionally smooth electronic gradients. Combine crisp masked silhouettes with glossy highlight strokes and subtly pixelated edge details, avoiding physical canvas texture. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/quantel-paintbox", "title": "Quantel Paintbox · 本库原创图解", "previewKind": "原创技法示意", "local": "quantel-paintbox.webp"},
  "quickshift-superpixels": {"prompt": "Apply a Quickshift Superpixels effect, dividing the photograph into many irregular, tightly adjoining patches that follow local color boundaries. Fill each patch with its average source color, creating an uneven mosaic with crisp borders and simplified texture rather than geometric tiles. Keep the original subject and composition.", "credit": "Image: Tanaphong Toochinda daen_2chinda · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Tanaphong_Toochinda_2017_(Unsplash).jpg", "local": "quickshift-superpixels.webp", "title": "Quickshift Superpixels", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "rack-focus": {"prompt": "Apply a Rack Focus effect as a still frame captured after a focus shift: make one existing depth plane crisply detailed while another becomes strongly defocused. Use smooth optical blur, soft circular highlight bokeh, and a natural transition between distances, without motion streaks. Keep the original subject and composition.", "credit": "Michael Weinman, CC BY-SA 2.0; via Wikimedia Commons. Frames rearranged and resized. https://creativecommons.org/licenses/by-sa/2.0", "source": "https://www.filmmakersacademy.com/glossary/rack-focus/", "local": "rack-focus.webp", "title": "Rack Focus", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/"},
  "radial-zoom-blur": {"prompt": "Apply Radial Zoom Blur, drawing textures and highlights into straight streaks radiating outward from a central focal point. Keep the focal region comparatively clear, increasing blur toward the edges to suggest rapid forward camera movement. Preserve existing colors and avoid rotational trails. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "radial-zoom-blur.webp", "title": "Radial Zoom Blur", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "radiosity": {"prompt": "Apply a radiosity rendering effect, emphasizing matte surfaces illuminated by diffuse light bouncing throughout the scene. Let existing colored surfaces cast subtle matching tints onto nearby areas, with soft contact shadows, gently brightened recesses, and smooth indirect-light gradients rather than mirrorlike highlights. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/radiosity", "title": "Radiosity · 本库原创图解", "previewKind": "原创技法示意", "local": "radiosity.webp"},
  "random-walker-segmentation": {"prompt": "Apply a Random Walker Segmentation effect, separating the image into flat, distinctly colored labeled regions guided by foreground and background seed areas. Let crisp boundaries follow existing brightness and color changes, suppressing texture within each region without imposing a regular grid. Keep the original subject and composition.", "credit": "Image: Timothy Lamm timothylamm · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Timothy_Lamm_2017_(Unsplash).jpg", "local": "random-walker-segmentation.webp", "title": "Random Walker Segmentation", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "raster-bars": {"prompt": "Apply a Raster Bars effect with thick horizontal bands of electric cyan, magenta, violet, and yellow, each shaded with smooth gradients and bright central highlights. Layer overlapping bands behind the subject, adding subtle scanlines and vintage screen glow without obscuring important details. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/raster-bars", "title": "Raster Bars · 本库原创图解", "previewKind": "原创技法示意", "local": "raster-bars.webp"},
  "raycasting": {"prompt": "Apply a Raycasting effect with coarse upright wall-like surfaces rendered as adjacent vertical texture strips, shrinking toward the distance. Use enlarged nearby texture pixels, sharp rectangular corners, flat floor shading, and simple depth-based darkening, translating existing background structures rather than introducing new corridors. Keep the original subject and composition.", "credit": "Mewtow · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Exemple_de_rendu_en_raycasting.jpg", "local": "raycasting.webp", "title": "Raycasting", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "reaction-diffusion-patterns": {"prompt": "Apply Reaction-Diffusion Patterns across existing surfaces, creating rounded spots, winding stripes, and branching organic mazes with roughly uniform spacing. Use contrasting cream and charcoal tones, smooth irregular boundaries, and subtle surface-following shading so the markings resemble natural pigmentation rather than pasted geometric tiles. Keep the original subject and composition.", "credit": "Zhu, Jianfeng & Zhang, Yong-Tao & Alber, Mark & Newman, Stuart. · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Turin1.png", "local": "reaction-diffusion-patterns.webp", "title": "Reaction-Diffusion Patterns", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "rear-projection": {"prompt": "Apply a Rear Projection treatment, keeping the foreground sharply studio-lit while making the existing background resemble footage on a translucent screen. Add softer background focus, lower contrast, visible projected grain, slight hotspot illumination, and restrained lateral background blur with subtly mismatched lighting. Keep the original subject and composition.", "credit": "Wikiwikiyarou", "source": "https://commons.wikimedia.org/wiki/File:Rear_projection_effect.jpg", "local": "rear-projection.webp", "title": "Rear projection effect", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "recursive-ray-tracing": {"prompt": "Transform this image into an early recursive ray tracing render, with clean geometric surfaces, mirror-polished highlights, glasslike refraction on suitable existing elements, and reflections nested within reflections. Use crisp cast shadows, precise perspective, smooth synthetic shading, and restrained environmental detail. Keep the original subject and composition.", "credit": "Gilles Tran", "source": "https://commons.wikimedia.org/wiki/File:Glasses_800_edit.png", "local": "recursive-ray-tracing.webp", "title": "Glasses 800 edit", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "redscale-film": {"prompt": "Apply a Redscale Film effect with dominant crimson shadows, burnt-orange midtones, and golden-yellow highlights. Suppress blue responses, shifting skies toward mustard or muted olive where present. Add organic film grain, slightly softened fine detail, and uneven warm color density without introducing digital glitches. Keep the original subject and composition.", "credit": "cliffchen1973 from Kaohsiung, Taiwan · CC BY 2.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:HK_Redscale_%E5%A4%A9%E6%98%9F%E7%A2%BC%E9%A0%AD_(4708320905).jpg", "local": "redscale-film.webp", "title": "Redscale Film", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "reinhard-color-transfer": {"prompt": "Apply Reinhard Color Transfer, matching the supplied reference palette when available; otherwise use warm cream highlights, muted teal shadows, and subdued terracotta midtones. Harmonize overall brightness, color balance, and tonal spread while retaining natural textures, sharp edges, and spatial detail. Keep the original subject and composition.", "credit": "Image: Verena Yunita Yapi verenayunita · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Ceramics,_Cafe,_Camera_(Unsplash).jpg", "local": "reinhard-color-transfer.webp", "title": "Reinhard Color Transfer", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "reverse-motion": {"prompt": "Apply the Reverse Motion effect as a frozen cinematic moment suggesting action running backward. Use inward-converging motion trails, recoiling droplets where liquid exists, and fragments appearing to rejoin their source where appropriate. Add faint sequential ghosting and vintage film grain without introducing unrelated objects. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/reverse-motion", "title": "Reverse Motion · 本库原创图解", "previewKind": "原创技法示意", "local": "reverse-motion.webp"},
  "rgb-channel-isolation": {"prompt": "Apply an RGB Channel Isolation effect, displaying only the source red channel as neutral grayscale intensity. Make red-rich areas light and red-poor cyan or blue areas dark, with smooth gray transitions and intact fine detail. Remove all color tinting and added texture. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "rgb-channel-isolation.webp", "title": "RGB Channel Isolation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "rgb-channel-split": {"prompt": "Apply an RGB Channel Split effect by offsetting red, green, and blue image layers in different directions. Create clearly separated colored double edges around high-contrast contours, with overlapping colors across textured areas. Keep displacement consistent across the frame rather than stronger at corners; keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "rgb-channel-split.webp", "title": "RGB Channel Split", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "rgb-split": {"prompt": "Apply an RGB Split effect by offsetting red, green, and blue channels into visible colored double contours. Add selective horizontal line displacement, small block errors, and brief-looking image jumps concentrated near high-contrast edges. Preserve a readable central image beneath the damaged digital signal aesthetic. Keep the original subject and composition.", "credit": "Rosa Menkman. CC BY 2.0", "source": "https://commons.wikimedia.org/wiki/File:Glitch_Art.jpg", "local": "rgb-split.webp", "title": "RGB Split", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "risograph-register-error": {"prompt": "Apply a Stencil-Print Registration Error effect using two grainy ink layers in coral red and deep teal on warm uncoated paper. Offset the layers slightly to create colored fringes, doubled contours, and darker overprinted intersections, with uneven ink coverage and visible paper fibers. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "risograph-register-error.webp", "title": "Risograph Registration Error", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "risograph": {"prompt": "Transform this image into a stencil duplicator print, separating forms into fluorescent pink, teal, and sunflower-yellow ink layers on uncoated cream paper. Add coarse halftone dots, grainy solid fills, slight registration offsets, translucent overprints, and uneven ink coverage with tactile paper fibers. Keep the original subject and composition.", "credit": "Mario Felipe", "source": "https://commons.wikimedia.org/wiki/File:Impress%C3%A3o_em_risografia_em_dua_cores,_2014.jpg", "local": "risograph.webp", "title": "Impressão em risografia em dua cores, 2014", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "roberts-cross": {"prompt": "Apply Roberts Cross, producing a dark monochrome edge map with extremely fine, pixel-sharp traces of local contrast. Emphasize diagonal transitions, tiny angular details, and lightly speckled texture noise. Keep boundaries narrow and somewhat fragmented, without broad halos or smoothing. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "roberts-cross.webp", "title": "Roberts Cross", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "rolling-ball-background": {"prompt": "Apply Rolling-Ball Background subtraction, reducing broad uneven shading and slow brightness variations across the image. Make small bright structures and fine luminous details stand out against a darker, more uniform background, preserving their local edges and textures without adding glow or new light sources. Keep the original subject and composition.", "credit": "Image: Valentin Antonini valentinant · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Man_with_his_smatphone_on_a_rooftop_in_Paris_(Unsplash).jpg", "local": "rolling-ball-background.webp", "title": "Rolling-Ball Background", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "rolling-shutter-wobble": {"prompt": "Apply Rolling Shutter Wobble, bending vertical structures into soft gelatinous curves and diagonally skewed segments. Vary horizontal displacement progressively between image rows, creating stretched contours and uneven leaning shapes without adding blur or changing the existing colors and lighting. Keep the original subject and composition.", "credit": "Image: Jan Senderek jansenderek · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Golden_Gate_Bridge_(Unsplash).jpg", "local": "rolling-shutter-wobble.webp", "title": "Rolling Shutter Wobble", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "rotoscoping": {"prompt": "Apply the Rotoscoping effect by translating photographic forms into hand-traced animated shapes while retaining natural anatomy and pose. Use slightly wavering contour lines, simplified flat color regions, selective painted shading, and small registration irregularities around silhouettes, preserving recognizable facial and environmental details. Keep the original subject and composition.", "credit": "Patent by Max Fleischer, artist Unknown authorUnknown author cropped/retouched by Rl", "source": "https://commons.wikimedia.org/wiki/File:US_patent_1242674_figure_3.png", "local": "rotoscoping.webp", "title": "US patent 1242674 figure 3", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "rutt-etra-scan-processing": {"prompt": "Apply Rutt–Etra Scan Processing, rebuilding the image as closely spaced luminous horizontal scanlines on black. Raise bright regions into curved peaks and compress shadows into low valleys, creating a rippling electronic relief with white phosphor glow, slight jitter, and sparse analog noise. Keep the original subject and composition.", "credit": "Wilfredor (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Protests_opposing_Venezuelan_Bolivarian_Revolution_in_Avenida_Paulista,_S%C3%A3o_Paulo,_Brazil.jpg", "local": "rutt-etra-scan-processing.webp", "title": "Rutt–Etra Scan Processing, applied to “Protests opposing Venezuelan Bolivarian Revolution in Avenida Paulista, São Paul”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "saliency-map": {"prompt": "Transform this image into a Saliency Map, rendering visually prominent features as bright white and pale gray regions against a dark grayscale field. Emphasize distinctive contrast, color differences, and texture concentrations with softly graduated intensity, suppressing less noticeable areas without introducing directional lighting. Keep the original subject and composition.", "credit": "Image: Lance Anderson lanceanderson · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Cake_store_(Unsplash).jpg", "local": "saliency-map.webp", "title": "Saliency Map", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "salted-paper-print": {"prompt": "Transform this image into a Salted Paper Print with muted reddish-brown shadows, creamy highlights, and gentle tonal gradations. Emphasize an uncoated matte surface, visible paper fibers, softened fine details, faint uneven sensitization, and lightly faded edges, with no glossy reflections or dense blacks. Keep the original subject and composition.", "credit": "The Metropolitan Museum of Art / Hill and Adamson / Public Domain", "source": "https://www.vam.ac.uk/articles/photographic-processes", "local": "salted-paper-print.webp", "title": "Salted Paper Print", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "sand-animation": {"prompt": "Transform this image into a Sand Animation frame, shaping the scene from dark granular deposits on a warm glowing lightbox. Use dense opaque silhouettes, translucent thin sand layers, finger-swept highlights, soft crumbling edges, scattered specks, and flowing transitional contours. Keep the original subject and composition.", "credit": "Manas Sahoo · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Maharana_pratap_-_Sand_Animation.jpg", "local": "sand-animation.webp", "title": "Sand Animation", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "saturation-boost": {"prompt": "Apply a Saturation Boost effect, intensifying existing colors into vivid, almost artificial reds, electric blues, and lush greens wherever those hues occur. Preserve neutral areas, fine texture, original hue relationships, and readable highlights and shadows. Avoid halos, added grain, or oversharpening. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "saturation-boost.webp", "title": "Saturation Boost", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "scanimate-analog-animation": {"prompt": "Apply an Analog Scan Animation effect, bending existing contours into elastic electronic curves with localized stretching, rolling distortions, and luminous trailing outlines. Use saturated rainbow gradients, bright white cores, soft phosphor halos, horizontal scanlines, and slight analog instability without introducing lettering or logos. Keep the original subject and composition.", "credit": "Telec. Concepteur", "source": "https://commons.wikimedia.org/wiki/File:Collection_Charles_Cros._Cam%C3%A9ras_film_(m%C3%A9dia_-_image_anim%C3%A9e)._Cam%C3%A9ras_pour_oscilloscope_type_6_-_Telec._Cam%C3%A9ra_Telec_pour_oscilloscope_de_l%27Institut_de_Phon%C3%A9tique,_type_6411,_n%C2%B0_de_s%C3%A9rie_372_EN_35_-_btv1b55009458z_(10_of_20).jpg", "local": "scanimate-analog-animation.webp", "title": "Collection Charles Cros. Caméras film (média : image animée). Caméras pour oscilloscope type 6 - Telec. Caméra Telec pour oscilloscope de l' (1)", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "scanline-displacement": {"prompt": "Apply a Scanline Displacement effect by shifting individual horizontal image rows sideways with alternating smooth waves and irregular jitter. Produce thin lateral tears, rippling vertical contours, and intermittent misaligned bands. Preserve the existing colors and avoid replacing rows with black scanlines; keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "scanline-displacement.webp", "title": "Scanline Displacement", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "scanning-electron-micrograph": {"prompt": "Transform this image into a Scanning Electron Micrograph, rendering surfaces in sculptural grayscale with exceptionally deep focus, crisp microscopic textures, bright raised edges, and dark crevices. Add fine detector noise and directional relief shading, making familiar materials resemble magnified specimens. Keep the original subject and composition.", "credit": "BernbaumJG · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Ebola_Virus_-_Electron_Micrograph.tiff", "local": "scanning-electron-micrograph.webp", "title": "Scanning Electron Micrograph", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "scharr-filter": {"prompt": "Apply a Scharr Filter effect, rendering fine grayscale contours on black with consistent sensitivity to vertical, horizontal, and diagonal boundaries. Make line brightness follow local contrast, revealing delicate texture and clean curved edges without directional bias. Leave flat regions dark and untextured. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "scharr-filter.webp", "title": "Scharr Filter", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "schlieren-photography": {"prompt": "Apply a Schlieren Photography effect with a neutral gray field and sharply defined light-dark bands revealing transparent air currents around the subject. Introduce delicate curling plumes, refractive ripples, and paired bright and dark gradients without opaque smoke, while retaining clear subject edges. Keep the original subject and composition.", "credit": "NASA & US Air Force: J.T. Heineck / Ed Schairer / Maj. Jonathan Orso / Maj. Jeremy Vand…", "source": "https://commons.wikimedia.org/wiki/File:Shockwave_pattern_around_a_T-38C_observed_with_Background-Oriented_Schlieren_photography_(2).jpg", "local": "schlieren-photography.webp", "title": "Supersonic Shock Bands and Wake", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "schufftan-process": {"prompt": "Apply a Schüfftan Process treatment, making the existing setting resemble monumental model architecture seamlessly combined with the foreground through a mirror. Use aligned perspective, deep focus, monochrome film grain, slight reflection softness, and faint brightness discontinuities at architectural joins. Keep the original subject and composition.", "credit": "Unknown authorUnknown author", "source": "https://commons.wikimedia.org/wiki/File:Donald_Calthrop_Blackmail_1929_Still.jpg", "local": "schufftan-process.webp", "title": "Donald Calthrop Blackmail 1929 Still", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "screen-tearing": {"prompt": "Apply Screen Tearing, splitting the photograph into several horizontal bands with abrupt sideways offsets. Create sharply misaligned object edges at each tear, retaining crisp pixels, original colors, and intact detail inside each band. Avoid wavy distortion or generalized noise. Keep the original subject and composition.", "credit": "Image: Tiago Aguiar tiagoaguiar · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Violet_flowers_on_a_cliff_(Unsplash).jpg", "local": "screen-tearing.webp", "title": "Screen Tearing", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "scribble-control": {"prompt": "Transform this image into a Scribble Control sketch, using sparse, rough black strokes on a clean white background to indicate major silhouettes, gestures, and a few essential interior features. Make lines uneven and loosely hand-drawn, omitting shading, color, grain, and fine detail. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "scribble-control.webp", "title": "Scribble Control", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "seam-carving": {"prompt": "Apply a Seam Carving effect by modestly narrowing low-detail background spaces without squeezing the main subject. Preserve natural anatomy, object proportions, sharp contours, and existing textures; allow only subtle compression of empty sky, walls, or ground between important elements. Maintain their relative arrangement. Keep the original subject and composition.", "credit": "Image: Clem Onojeghuo clemono2 · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Flav_(Unsplash).jpg", "local": "seam-carving.webp", "title": "Seam Carving", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "seamless-tiling": {"prompt": "Transform this image into a Seamless Tiling texture with precisely matching opposite borders, continuous colors, and smoothly connected edge details. Blend boundary transitions into surrounding textures without visible seams, hard joins, or abrupt lighting changes. Present one repeatable tile, concentrating adjustments near the borders rather than duplicating central features. Keep the original subject and composition.", "credit": "Image: Ahmed Saffu saffu · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Sandbank_(Unsplash).jpg", "local": "seamless-tiling.webp", "title": "Seamless Tiling", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "segmentation-boundaries": {"prompt": "Apply a Segmentation Boundaries effect, dividing the photograph into many small, irregular superpixel regions outlined with thin, bright cyan and yellow lines. Retain photographic color and texture beneath the dense boundary network, with cells following local edges rather than a regular grid. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "segmentation-boundaries.webp", "title": "Segmentation Boundaries", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "selective-color": {"prompt": "Apply a Selective Color effect by retaining vivid natural color in one prominent existing object or clearly bounded area. Convert everything else to neutral grayscale with rich shadows and gentle highlights, using precise masks and clean edges without color spill or halos. Keep the original subject and composition.", "credit": "A S M Jobaer · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Flag_of_Bangladesh_in_selective_color_against_a_monochrome_forest_background.jpg", "local": "selective-color.webp", "title": "Selective Color", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "semantic-segmentation-map": {"prompt": "Transform this image into a Semantic Segmentation Map, replacing photographic detail with flat, saturated color masks for visible categories such as people, clothing, vegetation, and background. Assign the same color to every region of the same category, with crisp silhouettes and no shading. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "semantic-segmentation-map.webp", "title": "Semantic Segmentation Map", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "sepia-matrix": {"prompt": "Apply a Sepia Matrix effect, remapping the photograph into warm brown shadows, coppery midtones, and pale cream highlights. Create a unified historic photographic palette with smooth tonal transitions and intact surface detail. Avoid added scratches, vignettes, paper borders, or artificial grain. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "sepia-matrix.webp", "title": "Sepia Matrix", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "sepia-toning": {"prompt": "Apply a Sepia Toning effect, replacing all original colors with a continuous range of warm brown tones, from creamy ivory highlights through tobacco midtones to deep chocolate shadows. Add restrained photographic grain and a matte paper finish without excessive distressing or artificial stains. Keep the original subject and composition.", "credit": "Giovanni Ussi", "source": "https://commons.wikimedia.org/wiki/File:City_of_Bolzano_-_Photo_by_Giovanni_Ussi_-_In_Black_and_White_Sepia_28.jpg", "local": "sepia-toning.webp", "title": "City of Bolzano - Photo by Giovanni Ussi - In Black and White Sepia 28", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "shaky-cam": {"prompt": "Apply a shaky cam still-frame effect with short irregular directional smears, faint doubled contours, and uneven motion blur concentrated around background details and high-contrast edges. Suggest an abrupt handheld jolt while leaving the main subject readable; avoid smooth radial zoom streaks or reframing. Keep the original subject and composition.", "credit": "Dietmar Rabich · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:M%C3%BCnster,_Prinzipalmarkt_--_2024_--_6718.jpg", "local": "shaky-cam.webp", "title": "Shaky Cam", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "shitomasi-corners": {"prompt": "Apply Shi–Tomasi Corners as a sparse technical overlay, placing small bright green dots at the strongest, well-defined corners and textured junctions. Space markers apart and avoid weak edges, flat surfaces, or dense redundant clusters. Keep the underlying photograph clearly visible. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "shitomasi-corners.webp", "title": "Shi–Tomasi Corners", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "sift-scale-space": {"prompt": "Apply SIFT Scale Space as a multiscale feature visualization over the photograph. Draw thin, brightly colored circles of noticeably different radii around distinctive blobs, corners, and textured regions, each with a radial orientation stroke. Include overlapping scales without obscuring underlying details. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "sift-scale-space.webp", "title": "SIFT Scale Space", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "silhouette-animation": {"prompt": "Transform this image into Silhouette Animation, reducing foreground subjects to opaque black paper cutouts without internal facial or clothing detail. Use crisp hand-cut contours, subtle joint overlaps, and layered scenery against a luminous ivory background with delicate gray decorative shapes and backlit paper texture. Keep the original subject and composition.", "credit": "Lotte Reiniger/Primrose Productions · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Lotte_Reiniger_Prinz_Achmed_002.jpg", "local": "silhouette-animation.webp", "title": "Silhouette Animation", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "silkscreen-print": {"prompt": "Transform this image into a Silkscreen Print with flattened vivid color blocks, stark photographic shadow shapes, and coarse stencil edges. Add slight color-layer misregistration, overlapping translucent inks, occasional mesh texture, uneven ink coverage, and visible paper fibers for a tactile printed finish. Keep the original subject and composition.", "credit": "Manolis Angelakis · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:OSCAL_2017_silkscreen_printed_materials_07.jpg", "local": "silkscreen-print.webp", "title": "Silkscreen Print", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "skeletonization": {"prompt": "Transform this image into a Skeletonization visualization, reducing foreground shapes to thin white centerlines on black. Preserve their branching structure, connectivity, and enclosed loops, using nearly single-pixel strokes instead of exterior outlines. Remove solid fills and photographic texture while retaining the recognizable arrangement of forms. Keep the original subject and composition.", "credit": "Image: Fineas Anton fineas_anton · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Forest_skyline_and_clouds_(Unsplash).jpg", "local": "skeletonization.webp", "title": "Skeletonization", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "skeuomorphic-interface": {"prompt": "Transform this image into a Skeuomorphic Interface, presenting existing forms as tactile digital panels and physical-looking controls. Use stitched leather borders, brushed metal details, subtle wood grain, embossed edges, raised buttons, and soft inset shadows. Keep material textures believable and lighting consistent across the simulated surfaces. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/skeuomorphic-interface", "title": "Skeuomorphic Interface · 本库原创图解", "previewKind": "原创技法示意", "local": "skeuomorphic-interface.webp"},
  "slic-superpixels": {"prompt": "Apply SLIC Superpixels to divide the photograph into compact, connected, roughly equal-sized color cells that follow meaningful object boundaries. Fill each cell with its average local color and separate cells with thin dark seams, replacing fine texture with an orderly irregular mosaic. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "slic-superpixels.webp", "title": "SLIC Superpixels", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "slit-scan-photography": {"prompt": "Apply Slit-Scan Photography with luminous color ribbons stretched into deep perspective corridors, elongated surface bands, and continuous exposure trails. Draw streaks from existing colors and align them with the scene's vanishing directions, using saturated spectral highlights against dark recesses while preserving recognizable central forms. Keep the original subject and composition.", "credit": "Glogger", "source": "https://commons.wikimedia.org/wiki/File:Keyboard_eq1985.png", "local": "slit-scan-photography.webp", "title": "Keyboard eq1985", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "slow-motion": {"prompt": "Apply a Slow Motion photographic treatment, suggesting an extended instant through finely resolved airborne particles, gently trailing fabric or hair where present, and restrained translucent motion echoes around moving edges. Keep stationary forms sharp, with soft cinematic lighting and smooth tonal transitions. Keep the original subject and composition.", "credit": "Robin Férand", "source": "https://commons.wikimedia.org/wiki/File:Slow_Motion_Sequence_With_Panasonic_Gh4_(209493041).jpeg", "local": "slow-motion.webp", "title": "Slow Motion Sequence With Panasonic Gh4", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/"},
  "snorricam": {"prompt": "Apply a SnorriCam effect, locking the main subject sharply in place while making the surroundings appear to sway around them. Add curved directional background blur, a subtly tilted environment, close body-mounted camera intimacy, and gritty film grain without blurring the face. Keep the original subject and composition.", "credit": "GAFFVISUALS", "source": "https://commons.wikimedia.org/wiki/File:Bastidores_da_produ%C3%A7%C3%A3o_do_videoclipe_Ferro_com_artista_Sacik_Brow_-_Guilherme_Fernandes_na_montagem_de_snorricam.jpg", "local": "snorricam.webp", "title": "Bastidores da produção do videoclipe Ferro com artista Sacik Brow - Guilherme Fernandes na montagem de snorricam", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "sobel-magnitude": {"prompt": "Apply Sobel Magnitude, turning the photograph into a grayscale gradient map with luminous contours in every orientation. Show strong boundaries in white, subtle texture edges in gray, and uniform surfaces in black. Retain slightly thick, softly graded outlines rather than binary strokes. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "sobel-magnitude.webp", "title": "Sobel Magnitude", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "sobel-x": {"prompt": "Apply a Sobel X effect in monochrome, emphasizing vertical boundaries wherever brightness changes horizontally. Render strong responses as bright narrow bands against black, with weaker gradients in gray. Suppress horizontal boundaries and flat areas while retaining slightly soft edge thickness. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "sobel-x.webp", "title": "Sobel X", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "sobel-y": {"prompt": "Apply a Sobel Y effect in monochrome, emphasizing horizontal boundaries wherever brightness changes vertically. Render strong responses as bright narrow bands against black, with weaker gradients in gray. Suppress vertical boundaries and flat areas while retaining slightly soft edge thickness. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "sobel-y.webp", "title": "Sobel Y", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "sodium-vapor-process": {"prompt": "Apply a Sodium Vapor Process composite effect with exceptionally clean foreground separation, individually resolved fine hairs, and translucent fabric retaining delicate background visibility wherever present. Use natural colors without yellow spill, smooth matte edges, subtle film grain, and balanced foreground and background exposure. Keep the original subject and composition.", "credit": "RicHard-59", "source": "https://commons.wikimedia.org/wiki/File:Sodium_vapor_process.png", "local": "sodium-vapor-process.webp", "title": "Sodium vapor process", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "soft-edge": {"prompt": "Apply a Soft Edges effect, reducing the photograph to pale gray contours on white, with feathered transitions and varying line intensity. Emphasize major silhouettes and meaningful interior edges while suppressing fine texture, hard black outlines, and binary contrast. Give contours a gently blurred, continuous appearance. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "soft-edge.webp", "title": "Soft Edges", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "soft-focus": {"prompt": "Apply a Soft Focus effect with gently softened contours, luminous highlight halos, smooth tonal transitions, and delicate atmospheric diffusion. Preserve a readable core of detail beneath the glow rather than applying uniform blur. Use restrained contrast, subtle grain, and soft, flattering light. Keep the original subject and composition.", "credit": "Julia Margaret Cameron / The Metropolitan Museum of Art. The Met Open Access / Public Domain.", "source": "https://www.vam.ac.uk/articles/julia-margaret-camerons-working-methods", "local": "soft-focus.webp", "title": "Soft Focus", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "solarization-filter": {"prompt": "Apply a Solarization Filter effect, leaving darker tones unchanged while inverting values above a bright tonal threshold. Create partially negative highlights, strange complementary colors, and abrupt contour-like transitions where tones cross the threshold. Retain photographic texture rather than adding drawn edges. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "solarization-filter.webp", "title": "Solarization Filter", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "solarization": {"prompt": "Apply Solarization with selective tonal reversals, silvery midtones, darkened highlights, and luminous shadows. Outline major forms with narrow light and dark contour bands, retaining recognizable photographic detail beneath uncanny metallic shading. Use predominantly monochrome tones, fine darkroom grain, and smooth gradients interrupted by reversal boundaries. Keep the original subject and composition.", "credit": "N0TABENE", "source": "https://commons.wikimedia.org/wiki/File:Monochrome_pos_neg_digital_solarized.jpg", "local": "solarization.webp", "title": "Monochrome pos neg digital solarized", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "special-effects-makeup": {"prompt": "Apply a Special Effects Makeup treatment using sculpted prosthetic textures, exaggerated creases, recessed shadows, and subtly raised healed scar details on suitable visible surfaces. Add matte rubber or wax finishes, stippled pigment, faint blended appliance edges, and directional lighting that reveals physical relief. Keep the original subject and composition.", "credit": "Lisa Sonia (Li) · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:As_a_film_Make-up_artist,_Creating_Zombies_is_something_I_enjoy_doing_at_SCARLET_STUDIOS.jpg", "local": "special-effects-makeup.webp", "title": "Special Effects Makeup", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "speed-ramping": {"prompt": "Apply a speed ramping inspired still-image effect, keeping the main subject sharply resolved while transitioning nearby motion trails from short, widely spaced echoes to long, densely overlapping streaks. Follow plausible movement directions and blend sharp and blurred regions smoothly to imply changing speed. Keep the original subject and composition.", "credit": "Shohei Ohtaki / Motion Prompt · 本地取帧", "source": "https://showheyohtaki.github.io/motion-prompt/#038", "license": "MIT", "licenseUrl": "https://github.com/showheyohtaki/motion-prompt/blob/main/LICENSE", "title": "Speed Ramping · 动效分镜", "previewKind": "开源同类示例", "local": "speed-ramping.webp"},
  "spiral-halftone": {"prompt": "Apply a Spiral Halftone effect using one continuous black spiral winding outward across a clean white background. Vary its width with image brightness: broad sections form shadows, narrow sections describe highlights. Use crisp edges and no gray ink or separate dots; keep the original subject and composition.", "credit": "Image: Scott Webb scottwebb · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Blurry_bus_in_motion_(Unsplash).jpg", "local": "spiral-halftone.webp", "title": "Spiral Halftone", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "spirit-duplicator": {"prompt": "Transform this image into a Spirit Duplicator print, translating forms into violet linework and sparse lavender shading on pale, slightly absorbent paper. Add fuzzy dye edges, uneven ink density, faint doubled contours, paper fibers, and patchy fading that suggests an exhausted master. Keep the original subject and composition.", "credit": "Richard Masoner · CC BY-SA 2.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Ditto_machine_copies_of_tests.jpg", "local": "spirit-duplicator.webp", "title": "Spirit Duplicator", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/"},
  "spirit-photography": {"prompt": "Apply a Spirit Photography effect with antique sepia tones, fine plate grain, subdued lighting, and a faint translucent duplicate of the subject nearby. Let the background show through this secondary apparition, adding soft exposure halos and slight motion softness while keeping the primary figure solid. Keep the original subject and composition.", "credit": "Buguet (Paris) · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Napoleon_III_%22ghost%22_photo.jpg", "local": "spirit-photography.webp", "title": "Spirit Photography", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "spirograph": {"prompt": "Apply a Gear-Drawn Rosette effect, reconstructing visible forms through fine looping curves, repeated radial petals, dense woven line bands, and open star-shaped spaces. Use overlapping cyan, magenta, and blue pen lines on warm white paper, with precise paths and delicate ink accumulation. Keep the original subject and composition.", "credit": "Rev. Daniel Elis Axelrod · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Spirograph_2019-01-20_to_21st_BDD_Front_Back_CC0_Rev_Daniel_Elis_Axelrod_2021.jpg", "local": "spirograph.webp", "title": "Spirograph", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "split-field-diopter": {"prompt": "Apply a Split-Field Diopter effect, making the nearest existing detail and a distant background feature simultaneously tack sharp on opposite sides of the frame. Leave an intermediate soft-focus zone and a subtle blurred vertical transition, with natural cinematic lighting and fine film grain. Keep the original subject and composition.", "credit": "SavidgeMichael", "source": "https://commons.wikimedia.org/wiki/File:A_Split-Field_Composition_Study_in_Old_Westbury_Gardens.jpg", "local": "split-field-diopter.webp", "title": "A Split-Field Composition Study in Old Westbury Gardens", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "split-screen": {"prompt": "Apply a Split Screen treatment by arranging two synchronized versions of the original view in adjacent panels with a clean vertical divider. Introduce modest differences in exposure and color temperature, with crisp rectangular boundaries and no blending between views. Within each panel, keep the original subject and composition.", "credit": "75Portlewes", "source": "https://commons.wikimedia.org/wiki/File:Split-screen_rame_from_Free_Wheelin%27_(1976)._No_1.png", "local": "split-screen.webp", "title": "Split-screen rame from Free Wheelin' (1976). No 1", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "split-toning": {"prompt": "Apply Split Toning with muted teal coloring in shadows and soft peach-gold coloring in highlights. Blend the two hues gradually through neutral midtones, preserving luminance detail, natural edge definition, and restrained saturation. Maintain distinct tonal color separation without adding colored outlines or texture overlays. Keep the original subject and composition.", "credit": "Dietmar Rabich (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Amboy_(California,_USA)_--_2012_--_4.jpg", "local": "split-toning.webp", "title": "Split Toning, applied to “Amboy (California, USA) -- 2012 -- 4”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "sprite-scaling": {"prompt": "Apply a Sprite Scaling effect by rendering existing elements as flat bitmap cutouts, with larger foreground pixel blocks and progressively smaller, finer background sprites. Emphasize depth through overlapping layers, stepped contours, and simple arcade-style shading, avoiding smoothly modeled three-dimensional surfaces. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/sprite-scaling", "title": "Sprite Scaling · 本库原创图解", "previewKind": "原创技法示意", "local": "sprite-scaling.webp"},
  "star-filter": {"prompt": "Apply a Star Filter effect to existing bright points and specular reflections, extending them into symmetrical four-point or six-point stars with fine needlelike rays. Add gentle luminous halos, subtle spectral glints, and mild highlight bloom while leaving darker textures and ordinary edges clear. Keep the original subject and composition.", "credit": "Flocci Nivis · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Pictures_With_Star_filter_03.jpg", "local": "star-filter.webp", "title": "Star Filter", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "steadicam-float": {"prompt": "Transform this image into a cinematic stabilized-camera float frame, with a perfectly level horizon, a sharply anchored subject, gentle directional blur in peripheral scenery, and subtle foreground parallax cues. Use natural lighting and smooth tonal transitions to suggest unhurried gliding rather than handheld shake. Keep the original subject and composition.", "credit": "Pattymooney · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:1994_Ot_Pi_Dick_Crow_Steadicam_Athens.jpg", "local": "steadicam-float.webp", "title": "Steadicam Float", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "steel-engraving": {"prompt": "Transform this image into a Steel Engraving printed in black ink on ivory paper. Build tones entirely from exceptionally fine parallel lines, precise crosshatching, stippled accents, and tiny tapered strokes. Add crisp contours, delicate highlights, subtle paper fibers, and a faint plate impression. Keep the original subject and composition.", "credit": "Samuel Hollyer (1826-1919) of a daguerreotype by Gabriel Harrison (1818-1902)(original … · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Walt_Whitman,_steel_engraving,_July_1854.jpg", "local": "steel-engraving.webp", "title": "Steel Engraving", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "stencil-coloring": {"prompt": "Apply the Stencil Coloring effect over a grainy black-and-white photographic base. Fill selected existing objects with bright translucent crimson, yellow, and turquoise dyes, allowing slight registration offsets, uneven dye density, and small color spills beyond their silhouettes. Leave uncolored areas monochrome with visible luminance detail. Keep the original subject and composition.", "credit": "Lucien Nonguet / Ferdinand Zecca · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:The_Life_and_Passion_of_Jesus_Christ_(1907).jpg", "local": "stencil-coloring.webp", "title": "Stencil Coloring", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "stereo-day-night-tissue": {"prompt": "Apply a Stereo Day-Night Tissue treatment, presenting paired, subtly offset photographic views on thin translucent paper. Blend subdued daylight sepia with backlit jewel-colored washes, glowing existing windows or highlights, and tiny pierced points of light. Show delicate tissue fibers and a dark card surround. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/stereo-day-night-tissue", "title": "Stereo Day-Night Tissue · 本库原创图解", "previewKind": "原创技法示意", "local": "stereo-day-night-tissue.webp"},
  "stereoscopic-3d-cinema": {"prompt": "Apply a Stereoscopic 3D Cinema anaglyph effect with subtly offset red and cyan contour pairs, stronger separation in foreground details, and gentler offsets in distant areas. Preserve a stable central subject, layered depth cues, restrained film grain, and slight projection softness. Keep the original subject and composition.", "credit": "Dominic Alves", "source": "https://commons.wikimedia.org/wiki/File:Illusion_of_Depth_and_Space_(10_22)_-_3D_Anaglyph_(Red_and_%22Green%22)_Stereoscopic_Glasses_-_Shadowless_(3386183538).jpg", "local": "stereoscopic-3d-cinema.webp", "title": "Illusion of Depth and Space (10 22) - 3D Anaglyph (Red and \"Green\") Stereoscopic Glasses - Shadowless (3386183538)", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "stereoscopy": {"prompt": "Transform this image into a Stereoscopy card with two nearly identical photographs placed side by side on cream cardstock. Introduce subtle horizontal viewpoint differences and convincing foreground-background parallax, using matching sepia tones, fine grain, and softly rounded print corners. Keep the original subject and composition within each view.", "credit": "London Stereoscopic Company / The Metropolitan Museum of Art. The Met Open Access / Public Domain.", "source": "https://blog.scienceandmediamuseum.org.uk/a-z-photography-l-is-for-london-stereoscopic-company/", "local": "stereoscopy.webp", "title": "Stereoscopy", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "stipple-pointillism": {"prompt": "Transform this image into Stipple Pointillism using individual black ink dots on white paper. Build darker tones through increased dot density and leave highlights sparsely dotted, keeping dots small, irregularly placed, and clearly separated where possible. Avoid continuous shading, lines, or regular grids. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "stipple-pointillism.webp", "title": "Stipple Pointillism", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "stop-motion-animation": {"prompt": "Transform this image into a Stop-Motion Animation frame with tangible handmade models, painted miniature scenery, and tactile clay, fabric, or carved surfaces. Include tiny fingerprints, uneven seams, subtly stiff poses, shallow miniature-scale depth of field, and practical studio shadows rather than digital smoothness. Keep the original subject and composition.", "credit": "Ladislas Starevich / Khanzhonkov; Wikimedia Commons reproduction; Commons page marks public domain;unknown still source;200×151px original.", "source": "https://www.bfi.org.uk/features/stop-motion-imperfection-why-animation-needs-human-touch", "local": "stop-motion-animation.webp", "title": "Stop-Motion Animation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "stop-trick": {"prompt": "Apply a Stop Trick effect as two adjacent, identically framed film stills capturing an abrupt substitution. Keep the subject intact in the first and transformed into a sculptural replica in the second, with perfectly aligned surroundings, monochrome grain, slight gate jitter, and a hard cut. Keep the original subject and composition.", "credit": "Georges Méliès / La Cinémathèque française. Historical film in the public domain; digital restoration/presentation Cinémathèque française.", "source": "https://www.cinematheque.fr/henri/film/52460-escamotage-d-une-dame-chez-robert-houdin-georges-melies-1896/", "local": "stop-trick.webp", "title": "Stop Trick", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "stroboscopic-photography": {"prompt": "Apply a Stroboscopic Photography effect with several sharply frozen, translucent movement echoes trailing closely along a plausible motion path. Use a darkened setting, crisp flash illumination, bright repeated edges, and minimal continuous blur, keeping the main exposure dominant. Keep the original subject and composition.", "credit": "Harold Edgerton · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Milk_Drop_Coronet,_1957_v2.jpg", "local": "stroboscopic-photography.webp", "title": "Stroboscopic Photography", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "structure-tensor-orientation": {"prompt": "Apply Structure Tensor Orientation as a false-color map of local edge and texture alignment. Assign consistent hues to matching directions, add short aligned strokes in coherent regions, and desaturate flat or directionally ambiguous areas. Preserve visible structural boundaries beneath the flowing directional field. Keep the original subject and composition.", "credit": "Image: Alec Weir xcvii · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Cliff_rocks_on_the_coastline_(Unsplash).jpg", "local": "structure-tensor-orientation.webp", "title": "Structure Tensor Orientation", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "subsurface-scattering": {"prompt": "Apply a subsurface scattering effect to suitable skin, waxy, or stone-like surfaces, adding soft internal light diffusion, warm translucent thin edges, and gently glowing backlit areas. Preserve fine surface texture and opaque boundaries while softening internal shadow transitions; avoid an all-over luminous haze. Keep the original subject and composition.", "credit": "Piotrek Chwała", "source": "https://commons.wikimedia.org/wiki/File:Subsurface_scattering.png", "local": "subsurface-scattering.webp", "title": "Subsurface scattering", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "super-resolution": {"prompt": "Apply Super-Resolution, enlarging the image with cleaner diagonal edges, smoother pixel staircases, and restrained recovery of fine texture. Clarify hair strands, fabric weave, and small existing details where supported, while preserving natural grain and avoiding invented markings, waxy surfaces, or strong sharpening halos. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "super-resolution.webp", "title": "Super-Resolution", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "swirl": {"prompt": "Apply Swirl, twisting the central image region into a smooth spiral with rotation strongest near the center and gradually fading toward unchanged outer edges. Curve nearby contours and textures into flowing arcs while retaining original colors, lighting, and recognizable details. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "swirl.webp", "title": "Swirl", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "teal-and-orange-color-grading": {"prompt": "Apply a teal and orange color grading effect, shifting shadows toward deep cyan and teal while warming skin, highlights, and practical lights toward amber and orange. Maintain natural facial detail, controlled saturation, rich blacks, and smooth tonal separation without coloring every surface equally. Keep the original subject and composition.", "credit": "AshokVijaya", "source": "https://commons.wikimedia.org/wiki/File:Teal_and_orange_city.jpg", "local": "teal-and-orange-color-grading.webp", "title": "Teal and orange city", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "teletext-graphics": {"prompt": "Transform this image into teletext graphics, translating forms into chunky rectangular mosaic cells on a rigid character grid. Limit colors to saturated red, green, blue, cyan, magenta, yellow, white, and black. Use stepped silhouettes, flat fills, and sparse character-like marks without smooth gradients. Keep the original subject and composition.", "credit": "Gabidgjtx · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:RTL_Teletext_homepage.jpg", "local": "teletext-graphics.webp", "title": "Teletext Graphics", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "template-matching-heatmap": {"prompt": "Apply Template Matching Heatmap using a distinctive existing image patch as the reference. Overlay translucent blue for weak similarity, yellow for moderate matches, and red hotspots at strong matching positions. Retain visible photographic structure beneath the smooth score field, without inventing repeated objects. Keep the original subject and composition.", "credit": "Image: Alexey Okhrimenko alexeyok · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Autumn_carpathians_(Unsplash).jpg", "local": "template-matching-heatmap.webp", "title": "Template Matching Heatmap", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "temporal-echo": {"prompt": "Apply Temporal Echo to create several staggered, translucent copies of the subject trailing along a plausible movement direction. Fade successive silhouettes gradually, retaining recognizable contours and softly overlapping colors rather than continuous motion blur. Keep the primary subject sharp and the background stable. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "temporal-echo.webp", "title": "Temporal Echo", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "text-to-image-generation": {"prompt": "Apply a Text-to-Image Generation aesthetic with richly synthesized surface detail, polished cinematic lighting, unusually coherent color grading, and subtly dreamlike background textures. Introduce minor ambiguous ornamental shapes in peripheral areas while preserving believable anatomy and avoiding invented lettering. Keep the original subject and composition.", "credit": "Left intentionally blank · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Th%C3%A9%C3%A2tre_D%E2%80%99op%C3%A9ra_Spatial.png", "local": "text-to-image-generation.webp", "title": "Text-to-Image Generation", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "texture-mapping": {"prompt": "Apply an early Texture Mapping effect, rendering existing forms as simple three-dimensional surfaces wrapped in visibly low-resolution image textures. Make patterns follow perspective and curvature, with stretched texels on steep angles, occasional mapping seams, basic lighting, and slightly angular silhouettes. Keep the original subject and composition.", "credit": "Asier03", "source": "https://commons.wikimedia.org/wiki/File:Texture_Mapping_example.png", "local": "texture-mapping.webp", "title": "Texture Mapping example", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "thaumatrope": {"prompt": "Apply a Thaumatrope effect, rendering the scene as two optically blended illustrations on warm ivory card. Use faint doubled contours, translucent overlapping layers, subtle rotational smearing, and alternating pale and dark edge echoes to suggest a flickering spinning disc frozen mid-turn. Keep the original subject and composition.", "credit": "Marcin Wichary from San Francisco, U.S.A. · CC BY 2.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Humble_beginnings,_pt._1_(2150574179)_(2).jpg", "local": "thaumatrope.webp", "title": "Thaumatrope", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "thermal-false-color-look": {"prompt": "Apply a Thermal False Color effect by mapping image brightness into deep violet, cobalt blue, cyan, yellow, orange, and white zones. Use smooth color transitions, slightly softened boundaries, and fine sensor-like noise, suggesting heat imagery without adding measurements or diagnostic labels. Keep the original subject and composition.", "credit": "Dietmar Rabich (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Darwin_(AU),_Stokes_Hill_Wharf_--_2019_--_4362.jpg", "local": "thermal-false-color-look.webp", "title": "Thermal False Color, applied to “Darwin (AU), Stokes Hill Wharf -- 2019 -- 4362”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "thin-plate-spline-warp": {"prompt": "Apply Thin-Plate Spline Warp to stretch selected image regions into gentle, continuous bends. Shift nearby landmarks by different amounts, creating elastic contours and smoothly flowing textures without abrupt seams, angular kinks, or duplicated details. Retain the existing colors and lighting. Preserve the original subject and composition.", "credit": "Image: Matt Benson · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Asheville_crops.jpeg", "local": "thin-plate-spline-warp.webp", "title": "Thin-Plate Spline Warp", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "three-strip-technicolor": {"prompt": "Apply a Three-Strip Dye-Transfer Cinema treatment with richly saturated reds, emerald greens, clear blues, warm natural skin tones where present, and deep neutral blacks. Use dense dye-like color, controlled luminous highlights, fine film grain, crisp separation between hues, and softly rounded photographic detail. Keep the original subject and composition.", "credit": "Marcin Wichary from San Francisco, U.S.A.", "source": "https://commons.wikimedia.org/wiki/File:3-strip_Technicolor_camera.jpg", "local": "three-strip-technicolor.webp", "title": "3-strip Technicolor camera", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
  "threshold": {"prompt": "Apply a Threshold effect using only pure black and pure white, with absolutely no gray or intermediate colors. Convert bright areas into solid white and dark areas into dense black, creating hard binary edges and stark silhouettes while retaining essential identifying details. Keep the original subject and composition.", "credit": "Colin (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Sky_Garden_-_Workmen.jpg", "local": "threshold.webp", "title": "Threshold, applied to “Sky Garden - Workmen”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "tilt-shift-miniature-look": {"prompt": "Apply Tilt-Shift Miniature, retaining a narrow horizontal band of crisp detail while smoothly increasing defocus above and below it. Add modest saturation and gentle contrast for a convincing small-scale model appearance, with soft highlights and unchanged scene geometry. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "tilt-shift-miniature-look.webp", "title": "Tilt-Shift Miniature", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "time-displacement": {"prompt": "Apply a Time Displacement effect, depicting different regions of the subject at slightly different implied moments of movement. Introduce sliced offsets, flowing contour distortions, and staggered movement phases across limbs or silhouettes, with transitions following broad tonal bands rather than simple transparent duplicates. Keep the original subject and composition.", "credit": "Glogger", "source": "https://commons.wikimedia.org/wiki/File:Stevemann_selfportrait_home-made_slit-shutter_camera1992.png", "local": "time-displacement.webp", "title": "Stevemann selfportrait home-made slit-shutter camera1992", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "time-lapse": {"prompt": "Transform this image into a time-lapse composite, keeping stable structures crisp while showing successive translucent positions of existing moving elements. Stretch clouds into soft streaks where present, trace existing lights into luminous paths, and blend subtle changes in illumination across the scene. Keep the original subject and composition.", "credit": "Cburnett", "source": "https://commons.wikimedia.org/wiki/File:Time_lapse_temps_modificat.png", "local": "time-lapse.webp", "title": "Time lapse temps modificat", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "tintype": {"prompt": "Transform this image into a Tintype with charcoal-black shadows, muted silver-gray highlights, and a dark lacquered iron surface. Add subtle metallic sheen, fine collodion detail, irregular chemical edges, tiny abrasions, and modest corner wear, keeping the overall image slightly underlit and physically tactile. Keep the original subject and composition.", "credit": "Miscellaneous Items in High Demand, PPOC, Library of Congress / Public domain; Wikimedia Commons", "source": "https://www.loc.gov/collections/liljenquist-civil-war-photographs/articles-and-essays/ambrotypes-and-tintypes/", "local": "tintype.webp", "title": "Tintype", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "total-variation-denoising": {"prompt": "Apply Total Variation Denoising, removing fine speckle and small brightness fluctuations while retaining strong, relatively sharp boundaries. Turn noisy surfaces into smooth, coherent color regions, with gentle gradients occasionally forming subtle flat steps or patches. Avoid broad blur, added brush texture, and sharpening halos. Keep the original subject and composition.", "credit": "Image: Jamie Dench dench · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Jamie_Dench_2015_(Unsplash).jpg", "local": "total-variation-denoising.webp", "title": "Total Variation Denoising", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "traveling-mat": {"prompt": "Apply a Travelling Matte effect with a visibly isolated foreground subject against a separately photographed-looking background. Add fine monochrome film grain, slight exposure mismatch, thin pale matte fringes, clipped hair edges, and subtle registration errors around the silhouette. Preserve believable lighting while keeping the original subject and composition.", "credit": "Goatart", "source": "https://commons.wikimedia.org/wiki/File:Opticalprinter2.JPG", "local": "traveling-mat.webp", "title": "Opticalprinter2", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "trimap": {"prompt": "Transform this image into a Trimap with exactly three flat tones: white for definite foreground, black for definite background, and middle gray for the uncertain boundary band. Widen gray zones around hair and intricate edges, using crisp transitions without gradients or photographic texture. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "trimap.webp", "title": "Trimap", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "truchet-tiles": {"prompt": "Transform this image into a Truchet Tiles pattern on a regular square grid. Use rotated paired quarter-circle arcs to form flowing black paths over white tiles. Thicken arcs in darker image regions and thin them in highlights, preserving recognizable tonal masses; keep the original subject and composition.", "credit": "Image: Pablo Merchán Montes · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Hands_holding_cocoa_beans.jpg", "local": "truchet-tiles.webp", "title": "Truchet Tiles", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "tv-static-snow": {"prompt": "Apply TV Static Snow, covering the photograph with dense, irregular black, white, and gray pixel speckles resembling a frozen instant of television interference. Mix tiny sharp dots with occasional coarser noise clusters, partially obscuring details while leaving the underlying scene recognizable. Keep the original subject and composition.", "credit": "Image: Josh Reeder-Esparza joshre · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Snowy_mountain_lake_shore_(Unsplash).jpg", "local": "tv-static-snow.webp", "title": "TV Static Snow", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "two-color-technicolor": {"prompt": "Apply an Early Two-Color Cinema treatment using a restricted red-orange and cyan-green palette. Render skin or warm surfaces peach and coral, shift blues toward turquoise, and suppress distinct yellows and violets. Add gentle dye bleed, fine film grain, soft contrast, and slight color misregistration. Keep the original subject and composition.", "credit": "Harry Beaumont / John Arnold · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:The-Broadway-Melody-Technicolor-Frame.png", "local": "two-color-technicolor.webp", "title": "Two-Color Technicolor", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "ultraviolet-photography": {"prompt": "Transform this image into reflected Ultraviolet Photography with stark monochrome tonal shifts, unnaturally dark foliage, and dark nectar-guide patterns on any visible flower petals. Emphasize skin pigmentation where present, subdued glass transmission, fine photographic grain, and crisp surface detail without neon fluorescence. Keep the original subject and composition.", "credit": "Callophrys rubi · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Third_of_three_panels_showing_UV_reflection_in_the_subfamily_of_tiger_moths_(Arctiinae).jpg", "local": "ultraviolet-photography.webp", "title": "Ultraviolet Photography", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "undercranking": {"prompt": "Apply an Undercranking treatment that suggests accelerated silent-film movement through widely spaced directional motion echoes, abrupt short blur streaks, and slightly jittered moving contours. Use high-contrast monochrome, coarse film grain, faint scratches, and mild exposure unevenness while keeping the central form readable. Keep the original subject and composition.", "credit": "Metro-Goldwyn-Mayer", "source": "https://commons.wikimedia.org/wiki/File:Ben-Hur_(1925)_-_6.jpg", "local": "undercranking.webp", "title": "Ben-Hur (1925) - 6", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "unsharp-mask": {"prompt": "Apply Unsharp Mask to increase local contrast along edges, making contours, fine textures, and small details visibly crisper. Introduce restrained light and dark edge halos without changing the overall palette or exposure. Avoid exaggerated grain, brittle outlines, and clipped highlights. Preserve the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "unsharp-mask.webp", "title": "Unsharp Mask", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "van-dyke-brown-print": {"prompt": "Apply the Van Dyke Brown Print effect using rich chocolate shadows, warm sepia midtones, and creamy paper highlights. Embed the image in visible cotton fibers with a matte surface, delicate tonal transitions, subtle exposure unevenness, and softly feathered sensitizer marks at the margins. Keep the original subject and composition.", "credit": "Petr Vodička · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:VanDyke-feather.jpg", "local": "van-dyke-brown-print.webp", "title": "Van Dyke Brown Print", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "vaporwave-aesthetic": {"prompt": "Apply a Vaporwave Aesthetic with pastel pink and cyan lighting, lavender shadows, retro wireframe overlays, chrome-like highlights, and softly glowing sunset gradients. Add analog video scanlines, faint color bleeding, and restrained digital glitches, integrating decorative elements into existing background spaces. Keep the original subject and composition.", "credit": "AtikaAtikawa · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Wikiwave_00000.png", "local": "vaporwave-aesthetic.webp", "title": "Vaporwave Aesthetic", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "vector-display-graphics": {"prompt": "Apply a 1970s vector display graphics effect, rebuilding visible forms as continuous luminous green or cyan outlines against deep black. Use smooth geometric strokes, bright intersections, subtle phosphor halos, and restrained persistence trails, without filled shading, raster stair-stepping, or paper texture. Keep the original subject and composition.", "credit": "RetroEditor · CC BY 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Vectrex_Spike_Controller.jpg", "local": "vector-display-graphics.webp", "title": "Vector Display Graphics", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/"},
  "vhs-tape-artifacts": {"prompt": "Apply a VHS tape artifacts effect with softened analog detail, bleeding reds, displaced chroma edges, faint luminance noise, and intermittent horizontal white dropouts. Add slight sideways displacement in narrow tracking bands and a wavering strip near the bottom, avoiding modern digital compression blocks. Keep the original subject and composition.", "credit": "Fourierkim", "source": "https://commons.wikimedia.org/wiki/File:VHS_VCR_mechanism.jpg", "local": "vhs-tape-artifacts.webp", "title": "VHS VCR mechanism", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "vhs-tracking-noise": {"prompt": "Apply a VHS Tracking Noise effect with wavering horizontal distortion bands, brief white dropout streaks, soft color bleeding, and displaced chromatic fringes. Add uneven analog grain and a narrow noisy tracking strip near the bottom while keeping the picture legible; keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "vhs-tracking-noise.webp", "title": "VHS Tracking Noise", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "video-feedback": {"prompt": "Apply a Video Feedback effect, repeating the image into progressively smaller luminous echoes that recede as a tunnel behind the main forms. Add slight rotational drift, phosphor glow, saturated rainbow fringes, deep black gaps, and accumulating analog noise without obscuring the primary silhouette. Keep the original subject and composition.", "credit": "Deathgleaner", "source": "https://commons.wikimedia.org/wiki/File:Video_feedback_octagon_pattern.jpg", "local": "video-feedback.webp", "title": "Video feedback octagon pattern", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "volumetric-light": {"prompt": "Apply Volumetric Light with distinct shafts of warm illumination cutting through cool atmospheric haze. Show suspended dust glowing inside the beams, soft scattering around light sources, and darker occluded gaps behind solid objects. Maintain believable beam direction, depth, and gently fading edges. Keep the original subject and composition.", "credit": "Unknown authorUnknown author · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Shaft_of_light_at_natural_entrance._(8a25cd96-de5c-4e5d-ac1b-be268f59b891).jpg", "local": "volumetric-light.webp", "title": "Volumetric Light", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "voronoi-mosaic": {"prompt": "Transform this image into a Voronoi Mosaic of irregular, tightly adjoining polygonal cells. Fill each cell with one representative local image color, using uneven cell sizes and crisp straight boundaries. Replace fine texture with flat facets, avoiding grout, bevels, and artificial lighting. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "voronoi-mosaic.webp", "title": "Voronoi Mosaic", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "vortograph": {"prompt": "Apply the Vortograph effect with triangular mirrored fragments, overlapping angular reflections, bright crystalline planes, and deep geometric shadows. Concentrate kaleidoscopic repetition within existing forms and surrounding textures, retaining a readable central silhouette. Use monochrome photographic grain and slightly imperfect optical reflections. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/vortograph", "title": "Vortograph · 本库原创图解", "previewKind": "原创技法示意", "local": "vortograph.webp"},
  "voxel-graphics": {"prompt": "Transform this image into Voxel Graphics, rebuilding visible forms from densely stacked colored cubes. Create chunky stepped contours, bumpy volumetric surfaces, small square facets, and simple directional lighting with dark gaps between blocks, using finer cubes for important identifying features. Keep the original subject and composition.", "credit": "Vossman; M. W. Toews; cmglee · CC BY-SA 2.5 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Voxels.svg", "local": "voxel-graphics.webp", "title": "Voxel Graphics", "license": "CC BY-SA 2.5", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.5/"},
  "watercolor-wash": {"prompt": "Apply a Watercolor Wash effect with translucent sampled colors, softly merged tonal areas, and muted fine detail. Add lightly mottled paper texture, uneven pigment coverage, delicate blooms, and darker pigment pooling along selected boundaries. Preserve major contours while softening minor edges; keep the original subject and composition.", "credit": "Image: Markus Birner markusbirner · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Lecture_Room_Stairs_(Unsplash).jpg", "local": "watercolor-wash.webp", "title": "Watercolor Wash", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "watershed-regions": {"prompt": "Transform this image into a Watershed Regions visualization with interlocking catchment-like patches separated by thin, sharply defined boundary lines. Let regions follow brightness-gradient ridges, using varied translucent colors over subdued photographic detail. Include smaller basins in textured areas and broader basins across smooth surfaces. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "watershed-regions.webp", "title": "Watershed Regions", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "wave-displacement": {"prompt": "Apply Wave Displacement, bending the photograph with smooth periodic horizontal and vertical ripples. Turn straight contours into repeating sinusoidal curves, gently compressing and stretching nearby textures in alternating bands. Preserve the existing palette, surface detail, and lighting without adding water or reflections. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://docs.opencv.org/4.x/d2/d96/tutorial_py_table_of_contents_imgproc.html", "local": "wave-displacement.webp", "title": "Wave Displacement", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "wet-plate-collodion": {"prompt": "Apply a Wet-Plate Collodion effect with exceptionally crisp central detail, silvery monochrome tones, dense shadows, and pale blue-sensitive highlights. Introduce irregular poured-emulsion borders, faint chemical streaks, scattered pinholes, and subtle glass-plate imperfections, keeping these artifacts strongest near the edges. Keep the original subject and composition.", "credit": "Heinrich Stürzl / CC BY-SA 4.0; Wikimedia Commons", "source": "https://www.vam.ac.uk/articles/photographic-processes", "local": "wet-plate-collodion.webp", "title": "Wet-Plate Collodion", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "whip-pan": {"prompt": "Apply a Whip Pan effect with strong horizontal motion streaks, elongated highlights, smeared color bands, and directional edge trails. Let the background dissolve into rapid lateral blur while retaining enough recognizable subject detail to anchor the image. Avoid radial blur or vertical dragging. Keep the original subject and composition.", "credit": "Diego Delso (photo); processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Centro_hist%C3%B3rico,_Baku,_Azerbaiy%C3%A1n,_2016-09-26,_DD_221-223_HDR.jpg", "local": "whip-pan.webp", "title": "Whip Pan, applied to “Centro histórico, Baku, Azerbaiyán, 2016-09-26, DD 221-223 HDR”", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "white-balance-shift": {"prompt": "Apply a White Balance Shift effect, warming the entire photograph through stronger red and weaker blue relative to green. Give neutral surfaces an amber cast, highlights a creamy warmth, and shadows a restrained brown tint while preserving material texture and lighting direction. Keep the original subject and composition.", "credit": "Image: Changyu Hu charliehu · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:People_walking_across_urban_street_(Unsplash).jpg", "local": "white-balance-shift.webp", "title": "White Balance Shift", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "wiener-deblurring": {"prompt": "Apply Wiener Deblurring, reducing soft focus or mild motion smearing to reveal clearer contours and restrained fine detail. Preserve natural colors and lighting, retain a slight grainy texture, and allow only faint ringing near high-contrast boundaries. Avoid brittle oversharpening or invented intricate patterns. Keep the original subject and composition.", "credit": "Image: crabtree crabtree · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:Fluffy_Dandelion_Seeds_(Unsplash).jpg", "local": "wiener-deblurring.webp", "title": "Wiener Deblurring", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "williams-process": {"prompt": "Apply a Williams Process composite treatment in monochrome, making the foreground appear optically inserted into the existing setting. Preserve precise silhouettes but introduce thin dark matte fringes, occasional pale halos, slightly mismatched grain, and contrasting foreground and background exposure. Add restrained archival softness. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/williams-process", "title": "Williams Process · 本库原创图解", "previewKind": "原创技法示意", "local": "williams-process.webp"},
  "wipe": {"prompt": "Apply a Wipe transition effect frozen halfway across the image, using a crisp vertical boundary between the original photograph and a warm monochrome version of the same scene. Keep spatial details precisely registered across the dividing edge, with subtle film grain throughout. Keep the original subject and composition.", "credit": "Carl Louis Gregory (1882-1951), images taken and published in his professional capacity as NARA staff", "source": "https://commons.wikimedia.org/wiki/File:Optical_printer_for_old_and_shrunken_films,_designed_by_Carl_Louis_Gregory,_1940.jpg", "local": "wipe.webp", "title": "Optical printer for old and shrunken films, designed by Carl Louis Gregory, 1940", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "wire-removal": {"prompt": "Apply a Wire Removal effect by erasing visible suspension wires, harnesses, rods, and support rigs around the subject. Reconstruct the exposed background with matching texture, grain, lighting, and clean contours, making any suspended elements appear convincingly unsupported without changing their positions. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/wire-removal", "title": "Wire Removal · 本库原创图解", "previewKind": "原创技法示意", "local": "wire-removal.webp"},
  "wireframe-cgi": {"prompt": "Transform this image into Wireframe CGI, tracing recognizable forms with luminous green and cyan polygon edges against a near-black background. Remove opaque surface fills, reveal rear-facing structural lines through transparent volumes, and use sparse perspective grids, slight raster aliasing, and restrained screen glow. Keep the original subject and composition.", "credit": "Rama", "source": "https://commons.wikimedia.org/wiki/File:European_Patrol_Corvette_wireframe-001.png", "local": "wireframe-cgi.webp", "title": "European Patrol Corvette wireframe-001", "license": "CC BY-SA 3.0 FR", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/fr/"},
  "wireframe-overlay": {"prompt": "Apply a Wireframe Overlay effect, covering the visible image surfaces with a fine triangular mesh of luminous cyan lines and small vertex dots. Vary triangle sizes around important contours, retain the photograph beneath, and create a precise technical appearance without solid polygon fills. Keep the original subject and composition.", "credit": "Image: NASA / Eileen Collins · scikit-image (public domain)", "source": "https://github.com/lllyasviel/ControlNet/blob/main/docs/annotator.md", "local": "wireframe-overlay.webp", "title": "Wireframe Overlay", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "woodburytype": {"prompt": "Transform this image into a Woodburytype with rich continuous brown-black tones, luminous cream highlights, and exceptionally smooth tonal gradations without halftone dots. Suggest pigmented gelatin through faintly raised glossy shadows, subtle relief visible in grazing light, and a clean paper support. Keep the original subject and composition.", "credit": "Rijksmuseum · CC0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Aanplakkers_van_reclamebiljetten_in_Londen_Street_Advertising_(titel_op_object),_RP-F-F25486-B.jpg", "local": "woodburytype.webp", "title": "Woodburytype", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "woodcut-print": {"prompt": "Apply a Woodcut Print effect with bold black ink masses, stark white carved cuts, and strong simplified contours. Replace smooth shading with angular gouge marks and rough directional hatching. Add subtle broken ink edges and a lightly textured paper surface; keep the original subject and composition.", "credit": "Image: Jon Flobrant jonflobrant · CC0 (via Wikimedia Commons), processed for the Atlas", "source": "https://commons.wikimedia.org/wiki/File:A_village_church_in_winter_(Unsplash).jpg", "local": "woodcut-print.webp", "title": "Woodcut Print", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/"},
  "wordart": {"prompt": "Apply a decorative 1990s typography effect, styling existing lettering or adding a compact descriptive heading with arched baselines, stretched letterforms, rainbow gradients, thick outlines, chunky simulated extrusion, offset shadows, and glossy white highlights. Give the lettering a playful molded-plastic appearance without obscuring important details. Keep the original subject and composition.", "credit": "Basile Morin · CC BY-SA 4.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Ambigram_The_art.png", "local": "wordart.webp", "title": "WordArt", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/"},
  "x-ray-radiograph": {"prompt": "Transform this image into an X-Ray Radiograph with luminous white bones or dense internal structures, translucent charcoal soft tissues, and a nearly black background. Use stark monochrome contrast, ghostly overlapping silhouettes, faint photographic plate grain, and softly glowing structural edges. Keep the original subject and composition.", "credit": "Wilhelm Röntgen · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:First_medical_X-ray_by_Wilhelm_R%C3%B6ntgen_of_his_wife_Anna_Bertha_Ludwig%27s_hand_-_18951222.jpg", "local": "x-ray-radiograph.webp", "title": "X-Ray Radiograph", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "xerographic-animation": {"prompt": "Transform this image into Xerographic Animation with sketchy black toner outlines, rough pencil contours, occasional stray construction marks, and flat painted color fills. Add slight line-density variation, powdery edge speckles, and subtly textured painted backgrounds, avoiding uniformly smooth digital inking or glossy dimensional shading. Keep the original subject and composition.", "credit": "本库原创图解 · 参考 Atlas 技法说明", "source": "https://atlas.letz.ai/effect/xerographic-animation", "title": "Xerographic Animation · 本库原创图解", "previewKind": "原创技法示意", "local": "xerographic-animation.webp"},
  "zoetrope": {"prompt": "Apply a Zoetrope effect with narrow dark vertical viewing slits, a subtly curved paper-strip appearance, and successive pose echoes concentrated around moving details. Use muted ink colors, aged paper grain, crisp intermittent silhouettes, and restrained lateral motion blur to suggest a spinning drum. Keep the original subject and composition.", "credit": "Runner1616 · CC BY-SA 3.0 · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Zoetrope_NN.jpg", "local": "zoetrope.webp", "title": "Zoetrope", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/"},
  "zone-system": {"prompt": "Apply a Zone System-inspired black-and-white print treatment with deep blacks, luminous whites, and carefully separated intermediate grays. Preserve texture in important shadows and bright surfaces, shape local contrast gently, and add restrained fine grain with crisp natural edges. Keep the original subject and composition.", "credit": "Ansel Adams · Public domain · via Wikimedia Commons", "source": "https://commons.wikimedia.org/wiki/File:Ansel_Adams_-_National_Archives_79-AA-G01.jpg", "local": "zone-system.webp", "title": "Zone System", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/"},
  "zoom-blur": {"prompt": "Apply a Zoom Blur effect with radial streaks extending outward from the main subject, mimicking a focal-length change during exposure. Keep the central focal area recognizable, lengthen streaks toward the edges, and blend existing colors into translucent directional trails with luminous highlights. Keep the original subject and composition.", "credit": "Joost J. Bakker, CC BY 2.0; via Wikimedia Commons. Reduced. https://creativecommons.org/licenses/by/2.0", "source": "https://helpx.adobe.com/uk/premiere-elements/desktop/special-effects-basics/effects-reference.html", "local": "zoom-blur.webp", "title": "Zoom Blur", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/"},
};
